                rollBoundPanel.showDrops(data);
                if (navButton != null)
                {
                    clientToolbar.openPanel(navButton);
                }
            }
        }));
        eventBus.register(dropsMenuListener);
        tradeableItemsInitialized = false;
        rollAnimationManager.setAllTradeableItems(Collections.emptySet());
