package com.rollbound.account;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import com.google.common.util.concurrent.ThreadFactoryBuilder;
import net.runelite.client.util.Filepath;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.file.StandardOpenOption;
import java.util.Properties;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/**
 * Local-only account guard for RollBound.
 *
 * Enabled RuneScape account hashes are stored in the plugin's local data directory.
 * Nothing from this class is written to Firebase, and only the account currently
 * logged into this RuneLite client can be enabled or disabled.
 */
@Singleton
public final class AccountGuardManager
{
    private static final String FILE_NAME = "account-guard.properties";

    private final Client client;
    private final Properties enabledAccounts = new Properties();
    private final Object fileIoLock = new Object();
    private Filepath storageFile;
    private ExecutorService ioExecutor;

    @Inject
    public AccountGuardManager(Client client)
    {
        this.client = client;
    }

    public synchronized void setDataDirectory(Filepath dataDirectory)
    {
        enabledAccounts.clear();
        storageFile = null;

        if (dataDirectory == null)
        {
            return;
        }

        try
        {
            dataDirectory.createDirectories();
            storageFile = dataDirectory.joinSegment(FILE_NAME);
            load();
        }
        catch (IOException ignored)
        {
            storageFile = null;
        }
    }

    public long getCurrentAccountHash()
    {
        if (client == null || client.getGameState() != GameState.LOGGED_IN)
        {
            return -1L;
        }
        return client.getAccountHash();
    }

    public String getCurrentDisplayName()
    {
        if (client == null || client.getGameState() != GameState.LOGGED_IN)
        {
            return null;
        }

        Player player = client.getLocalPlayer();
        if (player == null)
        {
            return null;
        }

        String name = player.getName();
        return name == null || name.trim().isEmpty() ? null : name.trim();
    }

    public synchronized boolean isCurrentAccountEnabled()
    {
        long hash = getCurrentAccountHash();
        return hash != -1L && enabledAccounts.containsKey(Long.toString(hash));
    }

    public synchronized boolean enableCurrentAccount()
    {
        long hash = getCurrentAccountHash();
        if (hash == -1L)
        {
            return false;
        }

        enabledAccounts.setProperty(Long.toString(hash), displayNameForStorage());
        save();
        return true;
    }

    public synchronized boolean disableCurrentAccount()
    {
        long hash = getCurrentAccountHash();
        if (hash == -1L)
        {
            return false;
        }

        Object removed = enabledAccounts.remove(Long.toString(hash));
        if (removed != null)
        {
            save();
            return true;
        }
        return false;
    }

    /** Keep the local display label current without changing authorization. */
    public synchronized void refreshCurrentDisplayName()
    {
        long hash = getCurrentAccountHash();
        if (hash == -1L)
        {
            return;
        }

        String key = Long.toString(hash);
        if (!enabledAccounts.containsKey(key))
        {
            return;
        }

        String name = displayNameForStorage();
        String previous = enabledAccounts.getProperty(key);
        if (!name.equals(previous))
        {
            enabledAccounts.setProperty(key, name);
            saveAsync();
        }
    }

    private String displayNameForStorage()
    {
        String name = getCurrentDisplayName();
        return name == null ? "Enabled account" : name;
    }

    private void load() throws IOException
    {
        if (storageFile == null || !storageFile.exists())
        {
            return;
        }

        try (BufferedReader reader = storageFile.openBufferedReader())
        {
            enabledAccounts.load(reader);
        }
    }

    private void save()
    {
        Filepath file = storageFile;
        if (file == null)
        {
            return;
        }

        Properties snapshot = new Properties();
        snapshot.putAll(enabledAccounts);
        saveProperties(file, snapshot);
    }

    private synchronized ExecutorService ensureExecutor()
    {
        if (ioExecutor == null || ioExecutor.isShutdown() || ioExecutor.isTerminated())
        {
            ioExecutor = Executors.newSingleThreadExecutor(
                    new ThreadFactoryBuilder().setNameFormat("rollbound-account-guard-%d").setDaemon(true).build());
        }
        return ioExecutor;
    }

    private void saveAsync()
    {
        Filepath file = storageFile;
        if (file == null)
        {
            return;
        }

        Properties snapshot = new Properties();
        snapshot.putAll(enabledAccounts);
        ensureExecutor().execute(() -> saveProperties(file, snapshot));
    }

    private void saveProperties(Filepath file, Properties values)
    {
        synchronized (fileIoLock)
        {
            try (BufferedWriter writer = file.openBufferedWriter(
                    StandardOpenOption.CREATE,
                    StandardOpenOption.TRUNCATE_EXISTING,
                    StandardOpenOption.WRITE))
            {
                values.store(writer, "RollBound local account guard");
            }
            catch (IOException ignored)
            {
                // Fail closed for future sessions if the local guard cannot be persisted.
            }
        }
    }

    public synchronized void shutdown()
    {
        if (ioExecutor != null)
        {
            ioExecutor.shutdownNow();
            ioExecutor = null;
        }
    }

}

package com.rollbound.account;

import lombok.Getter;
import lombok.Setter;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.AccountHashChanged;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Monitors for account changes and updates the stored display name.
 */
@Singleton
public class AccountManager
{
	@Inject
	private Client client;


	@Inject
	private EventBus eventBus;

	private long hash = -1;
	@Getter @Setter private volatile String playerName;
	private boolean nameSet = false;

	public boolean ready() { return hash != -1 && nameSet; }

	public void init()
	{
		if (client.getGameState() == GameState.LOGGED_IN && client.getAccountHash() != -1)
		{
			hash = client.getAccountHash();
			nameSet = false;
		}
	}

	@Subscribe
	private void onAccountHashChanged(AccountHashChanged event)
	{
		long newHash = client.getAccountHash();
		if (hash != newHash)
		{
			hash = newHash;
			nameSet = false; // Player is null at this point, so name is set in onClientTick
		}
	}

	@Subscribe
	private void onClientTick(ClientTick event)
	{
		if (client.getGameState().getState() < GameState.LOADING.getState()) return;
		if (hash == -1) return;
		if (nameSet) return;

		Player player = client.getLocalPlayer();
		if (player == null) return;

		String name = player.getName();
		if (name == null) return;

		setPlayerName(name);
		nameSet = true;
		emit();
	}

	@Subscribe
	private void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN && hash != -1)
		{
			reset();
		}
	}

	public void reset() {
		hash = -1;
		setPlayerName(null);
		emit();
	}

	private void emit()
	{
		eventBus.post(new AccountChanged(hash, playerName));
	}
}

package com.rollbound.backup;

import com.google.gson.Gson;
import com.rollbound.managers.ObtainedItemsManager;
import com.rollbound.managers.RollHistoryManager;
import com.rollbound.managers.RolledByManager;
import com.rollbound.managers.RolledItemsManager;
import net.runelite.client.util.Filepath;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.file.StandardOpenOption;
import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.Date;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Creates a complete local RollBound backup after every completed roll.
 *
 * All file access is rooted in RuneLite's plugin-data directory via {@link Filepath}.
 * The plugin descriptor migrates the legacy .runelite/Rollbound directory on first use,
 * so existing Backups folders are preserved.
 */
@Singleton
public final class LocalBackupManager
{
    private static final Logger log = LoggerFactory.getLogger(LocalBackupManager.class);

    private static final int MAX_BACKUPS = 30;
    private static final String BACKUP_FOLDER_PATTERN = "'RB Backup ('dd-MM-yyyy') ('HH-mm-ss')'";

    private static final String ROLLED_FILE = "rollbound_rolled.json";
    private static final String OBTAINED_FILE = "rollbound_obtained.json";
    private static final String ROLLED_BY_FILE = "rollbound_rolled_by.json";
    private static final String HISTORY_FILE = "rollbound_roll_history.json";

    private final RolledItemsManager rolledItemsManager;
    private final ObtainedItemsManager obtainedItemsManager;
    private final RolledByManager rolledByManager;
    private final RollHistoryManager rollHistoryManager;
    private final Gson gson;

    private volatile Filepath pluginDataDirectory;

    /** Event ids already backed up during this RuneLite session. */
    private final Set<String> backedEventIds = new HashSet<>();
    private boolean baselineEstablished;

    @Inject
    public LocalBackupManager(
            RolledItemsManager rolledItemsManager,
            ObtainedItemsManager obtainedItemsManager,
            RolledByManager rolledByManager,
            RollHistoryManager rollHistoryManager,
            Gson gson)
    {
        this.rolledItemsManager = rolledItemsManager;
        this.obtainedItemsManager = obtainedItemsManager;
        this.rolledByManager = rolledByManager;
        this.rollHistoryManager = rollHistoryManager;
        this.gson = gson.newBuilder().setPrettyPrinting().create();
    }

    /** Called by RollBoundPlugin after RuneLite provides the plugin-scoped data directory. */
    public synchronized void setDataDirectory(Filepath pluginDataDirectory)
    {
        this.pluginDataDirectory = pluginDataDirectory == null ? null : pluginDataDirectory.rooted();
    }

    /**
     * Reset de-duplication when Firebase is reconnected/switched. The first authoritative
     * snapshot after this call becomes the baseline and does not generate historical backups.
     */
    public synchronized void resetSession()
    {
        backedEventIds.clear();
        baselineEstablished = false;
    }

    public synchronized void onAuthoritativeSnapshotApplied(Collection<RollHistoryManager.RollEvent> events)
    {
        List<RollHistoryManager.RollEvent> snapshot = sanitiseEvents(events);

        if (!baselineEstablished)
        {
            for (RollHistoryManager.RollEvent event : snapshot)
            {
                backedEventIds.add(event.getEventId());
            }
            baselineEstablished = true;
            return;
        }

        for (RollHistoryManager.RollEvent event : snapshot)
        {
            String eventId = event.getEventId();
            if (eventId != null && !eventId.trim().isEmpty() && !backedEventIds.contains(eventId))
            {
                backupCompletedRoll(eventId);
            }
        }
    }

    private synchronized boolean backupCompletedRoll(String eventId)
    {
        String id = eventId == null ? "" : eventId.trim();
        if (id.isEmpty() || backedEventIds.contains(id))
        {
            return false;
        }

        Filepath folder = null;
        try
        {
            Filepath backupRoot = backupRoot();
            backupRoot.createDirectories();

            folder = uniqueBackupFolder(backupRoot, new Date());
            folder.createDirectory();

            LinkedHashSet<Integer> rolled = new LinkedHashSet<>(rolledItemsManager.getRolledItems());
            LinkedHashSet<Integer> obtained = new LinkedHashSet<>(obtainedItemsManager.getObtainedItems());
            Map<Integer, RolledByManager.RolledByEntry> rolledBy = rolledByManager.getSnapshot();
            List<RollHistoryManager.RollEvent> history = rollHistoryManager.getSnapshot();

            writeJsonNew(folder.joinSegment(ROLLED_FILE), rolled);
            writeJsonNew(folder.joinSegment(OBTAINED_FILE), obtained);
            writeJsonNew(folder.joinSegment(ROLLED_BY_FILE), rolledBy);
            writeJsonNew(folder.joinSegment(HISTORY_FILE), history);

            verifyCompleteBackup(folder);

            backedEventIds.add(id);
            pruneOldBackups(backupRoot);
            log.debug("RollBound local backup created: {}", folder);
            return true;
        }
        catch (Exception error)
        {
            if (folder != null)
            {
                try
                {
                    folder.deleteRecursively();
                }
                catch (Exception cleanupError)
                {
                    log.warn("Could not remove incomplete RollBound backup folder {}", folder, cleanupError);
                }
            }

            String destination;
            try
            {
                destination = folder == null ? backupRoot().toString() : folder.toString();
            }
            catch (Exception ignored)
            {
                destination = "plugin data directory";
            }
            log.error("Could not create RollBound local backup for roll {} at {}", id, destination, error);
            return false;
        }
    }

    private Filepath backupRoot() throws IOException
    {
        Filepath root = pluginDataDirectory;
        if (root == null)
        {
            throw new IOException("RollBound plugin data directory has not been initialised");
        }
        return root.joinSegment("Backups");
    }

    private Filepath uniqueBackupFolder(Filepath root, Date now) throws IOException
    {
        String base = new SimpleDateFormat(BACKUP_FOLDER_PATTERN).format(now);
        Filepath candidate = root.joinSegment(base);
        if (!candidate.exists())
        {
            return candidate;
        }

        for (int suffix = 2; suffix < 1000; suffix++)
        {
            candidate = root.joinSegment(base + " (" + suffix + ")");
            if (!candidate.exists())
            {
                return candidate;
            }
        }
        throw new IOException("Could not allocate a unique RollBound backup folder");
    }

    private void writeJsonNew(Filepath target, Object value) throws IOException
    {
        try (BufferedWriter writer = target.openBufferedWriter(
                StandardOpenOption.CREATE_NEW,
                StandardOpenOption.WRITE))
        {
            gson.toJson(value, writer);
        }
    }

    private void verifyCompleteBackup(Filepath folder) throws IOException
    {
        String[] names = {ROLLED_FILE, OBTAINED_FILE, ROLLED_BY_FILE, HISTORY_FILE};
        for (String name : names)
        {
            Filepath file = folder.joinSegment(name);
            if (!file.isFile() || file.size() <= 0L)
            {
                throw new IOException("Incomplete RollBound backup: " + file);
            }
        }
    }

    private void pruneOldBackups(Filepath root) throws IOException
    {
        List<Filepath> folders = new ArrayList<>();
        try (java.util.stream.Stream<Filepath> stream = root.walk(1))
        {
            stream.filter(path -> !path.equals(root))
                    .filter(Filepath::isDirectory)
                    .filter(path -> path.getFileName().startsWith("RB Backup ("))
                    .forEach(folders::add);
        }

        folders.sort(Comparator
                .comparingLong(LocalBackupManager::lastModifiedSafe)
                .reversed()
                .thenComparing(Filepath::getFileName, Comparator.reverseOrder()));

        for (int i = MAX_BACKUPS; i < folders.size(); i++)
        {
            folders.get(i).deleteRecursively();
        }
    }

    private static long lastModifiedSafe(Filepath path)
    {
        try
        {
            return path.getLastModifiedTime().toMillis();
        }
        catch (IOException ignored)
        {
            return 0L;
        }
    }

    private static List<RollHistoryManager.RollEvent> sanitiseEvents(Collection<RollHistoryManager.RollEvent> events)
    {
        List<RollHistoryManager.RollEvent> result = new ArrayList<>();
        if (events == null)
        {
            return result;
        }
        for (RollHistoryManager.RollEvent event : events)
        {
            if (event != null && event.getEventId() != null && !event.getEventId().trim().isEmpty())
            {
                result.add(event);
            }
        }
        result.sort(Comparator.comparingLong(RollHistoryManager.RollEvent::getAt));
        return result;
    }
}

package com.rollbound.drops;

import com.google.common.util.concurrent.ThreadFactoryBuilder;
import com.google.gson.Gson;
import com.rollbound.account.AccountManager;
import com.rollbound.tracker.TrackerTelemetryService;
import net.runelite.client.util.Filepath;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.BufferedReader;
import java.io.IOException;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.CompletionException;
import java.util.concurrent.Executors;
import java.util.stream.Collectors;
import java.util.stream.Stream;

/**
 * Persistent drop-table cache backed by JSON files in RuneLite's plugin-data directory.
 * All file access goes through {@link Filepath}; stale cache data is disposable and rebuilt
 * from the Old School RuneScape Wiki when needed.
 */
@Singleton
public class DropCache
{
    private static final Logger log = LoggerFactory.getLogger(DropCache.class);
    private static final Duration MAX_AGE = Duration.ofDays(7);

    private final Gson gson;
    private final AccountManager accountManager;
    private final DropFetcher dropFetcher;
    private final TrackerTelemetryService trackerTelemetryService;

    private final Map<Filepath, Object> writeLocks = new ConcurrentHashMap<>();
    private final Map<Filepath, NpcDropData> cache = new ConcurrentHashMap<>();
    private final Map<String, Filepath> nameIndex = new ConcurrentHashMap<>();
    private volatile boolean indexLoaded;
    private volatile Filepath pluginDataDirectory;

    // Dedicated IO executor so file operations never run on the RuneLite client thread.
    private ExecutorService ioExecutor;

    @Inject
    public DropCache(Gson gson, AccountManager accountManager, DropFetcher dropFetcher,
                     TrackerTelemetryService trackerTelemetryService)
    {
        this.gson = gson;
        this.accountManager = accountManager;
        this.dropFetcher = dropFetcher;
        this.trackerTelemetryService = trackerTelemetryService;
    }

    /** Called by RollBoundPlugin after RuneLite provides the plugin-scoped data directory. */
    public synchronized void setDataDirectory(Filepath pluginDataDirectory)
    {
        this.pluginDataDirectory = pluginDataDirectory == null ? null : pluginDataDirectory.rooted();
        resetIndex();
    }

    /** Preload on-disk index and prune stale cache entries off the RuneLite UI/client threads. */
    public void startUp()
    {
        ExecutorService executor = ensureExecutor();
        String player = accountManager.getPlayerName();
        if (player == null || player.isEmpty())
        {
            return;
        }

        executor.execute(() ->
        {
            loadIndex();
            pruneOldCaches();
        });
    }

    /** Reset the in-memory cache when the RuneScape account changes. */
    public synchronized void reloadForAccount()
    {
        resetIndex();
        startUp();
    }

    private void resetIndex()
    {
        cache.clear();
        nameIndex.clear();
        writeLocks.clear();
        indexLoaded = false;
    }

    /**
     * Load from disk if possible; otherwise fetch from the wiki, write JSON, and return the data.
     * Results without drop-table sections are discarded and never cached.
     */
    public CompletableFuture<NpcDropData> get(int npcId, String name, int level)
    {
        final String safeName = safeFilePart(name);
        ExecutorService executor = ensureExecutor();

        return CompletableFuture.supplyAsync(() ->
        {
            loadIndex();

            final Filepath file;
            try
            {
                file = npcId == 0
                        ? findExistingCacheFile(safeName, level)
                        : getCacheFile(npcId, name, level);
            }
            catch (IOException ex)
            {
                throw new CompletionException(ex);
            }

            if (file != null)
            {
                NpcDropData cached = cache.get(file);
                if (cached != null && file.exists() && isFresh(file))
                {
                    return cached;
                }

                try
                {
                    file.deleteIfExists();
                }
                catch (IOException ignored) { }
                removeIndex(file);
            }
            return null;
        }, executor).thenComposeAsync(cached ->
        {
            if (cached != null)
            {
                trackerTelemetryService.publishNpcDropData(cached);
                return CompletableFuture.completedFuture(cached);
            }

            return dropFetcher.fetch(npcId, name, level)
                    .thenApplyAsync(data ->
                    {
                        if (data == null || data.getDropTableSections() == null || data.getDropTableSections().isEmpty())
                        {
                            return null;
                        }

                        try
                        {
                            Filepath out = getCacheFile(data.getNpcId(), data.getName(), data.getLevel());
                            out.getParent().createDirectories();
                            String json = gson.toJson(data);

                            Object lock = writeLocks.computeIfAbsent(out, ignored -> new Object());
                            synchronized (lock)
                            {
                                Filepath tmp = out.getParent().createTempFile("rb-drop-", ".tmp");
                                try
                                {
                                    tmp.write(json,
                                            StandardOpenOption.CREATE,
                                            StandardOpenOption.TRUNCATE_EXISTING,
                                            StandardOpenOption.WRITE);
                                    try
                                    {
                                        tmp.moveTo(out,
                                                StandardCopyOption.REPLACE_EXISTING,
                                                StandardCopyOption.ATOMIC_MOVE);
                                    }
                                    catch (AtomicMoveNotSupportedException unsupported)
                                    {
                                        tmp.moveTo(out, StandardCopyOption.REPLACE_EXISTING);
                                    }
                                }
                                finally
                                {
                                    writeLocks.remove(out);
                                    try { tmp.deleteIfExists(); } catch (IOException ignored) { }
                                }
                            }

                            cache.put(out, data);
                            nameIndex.put(buildNameKey(data.getName(), data.getLevel()), out);

                            if (npcId == 0 && data.getNpcId() != 0)
                            {
                                Filepath old = findExistingCacheFile(safeName, data.getLevel());
                                if (old != null && !old.equals(out))
                                {
                                    old.deleteIfExists();
                                    removeIndex(old);
                                }
                            }
                        }
                        catch (Exception e)
                        {
                            log.error("Failed to write cache file for {}", name, e);
                        }

                        trackerTelemetryService.publishNpcDropData(data);
                        return data;
                    }, executor);
        }, executor).exceptionally(ex ->
        {
            log.error("Error loading drop data for NPC {}", npcId, ex);
            return null;
        });
    }

    /** Fetch all exact Wiki NPC variants for a name and optional combat level. */
    public CompletableFuture<List<NpcDropData>> searchNpcVariants(String name, int level)
    {
        return dropFetcher.fetchVariants(name, level)
                .thenApply(results ->
                {
                    if (results != null)
                    {
                        for (NpcDropData data : results)
                        {
                            trackerTelemetryService.publishNpcDropData(data);
                        }
                    }
                    return results == null ? new ArrayList<NpcDropData>() : results;
                })
                .exceptionally(ex ->
                {
                    log.error("Error fetching NPC variants for {} (lvl {})", name, level, ex);
                    return new ArrayList<NpcDropData>();
                });
    }

    public CompletableFuture<Collection<NpcDropData>> getAllNpcDataAsync()
    {
        ExecutorService executor = ensureExecutor();
        return CompletableFuture.supplyAsync(() ->
        {
            loadIndex();
            return new ArrayList<>(cache.values());
        }, executor);
    }

    public CompletableFuture<List<String>> searchNpcNames(String query)
    {
        ExecutorService executor = ensureExecutor();
        return CompletableFuture.supplyAsync(() ->
        {
            String lc = query == null ? "" : query.toLowerCase(Locale.ROOT).trim();
            loadIndex();

            Set<String> names = cache.values().stream()
                    .map(NpcDropData::getName)
                    .filter(Objects::nonNull)
                    .filter(name -> name.toLowerCase(Locale.ROOT).contains(lc))
                    .collect(Collectors.toCollection(LinkedHashSet::new));

            try
            {
                names.addAll(dropFetcher.searchNpcNames(query));
            }
            catch (Exception ex)
            {
                log.debug("Wiki search failed for {}", query, ex);
            }

            return new ArrayList<>(names);
        }, executor);
    }

    private boolean isFresh(Filepath file)
    {
        try
        {
            Instant cutoff = Instant.now().minus(MAX_AGE);
            return file.getLastModifiedTime().toInstant().isAfter(cutoff);
        }
        catch (IOException e)
        {
            return false;
        }
    }

    private Filepath findExistingCacheFile(String safeName, int level) throws IOException
    {
        String key = safeName + "_" + level;
        Filepath file = nameIndex.get(key);
        if (file != null && file.exists())
        {
            if (isFresh(file))
            {
                return file;
            }
            file.deleteIfExists();
            removeIndex(file);
        }
        return null;
    }

    private Filepath getCacheDir() throws IOException
    {
        Filepath root = pluginDataDirectory;
        if (root == null)
        {
            throw new IOException("RollBound plugin data directory has not been initialised");
        }

        String player = accountManager.getPlayerName();
        if (player == null || player.trim().isEmpty())
        {
            throw new IOException("Player name is not available");
        }

        Filepath dir = root.joinSegment("drops-v2").joinSegment(safeSegment(player));
        dir.createDirectories();
        return dir;
    }

    private Filepath getCacheFile(int npcId, String name, int level) throws IOException
    {
        Filepath dir = getCacheDir();
        String fileName = npcId + "_" + safeFilePart(name) + "_" + level + ".json";
        return dir.joinSegment(fileName);
    }

    private void pruneOldCaches()
    {
        final Filepath dir;
        try
        {
            dir = getCacheDir();
        }
        catch (IOException ignored)
        {
            return;
        }

        Instant cutoff = Instant.now().minus(MAX_AGE);
        try (Stream<Filepath> files = dir.walk(1))
        {
            files.filter(path -> !path.equals(dir))
                    .filter(Filepath::isFile)
                    .forEach(path ->
                    {
                        try
                        {
                            if (path.getLastModifiedTime().toInstant().isBefore(cutoff))
                            {
                                path.deleteIfExists();
                                removeIndex(path);
                            }
                        }
                        catch (IOException ex)
                        {
                            log.debug("Failed to delete old drop cache {}", path, ex);
                        }
                    });
        }
        catch (IOException ex)
        {
            log.debug("Error pruning drop cache directory {}", dir, ex);
        }
    }

    public CompletableFuture<Void> clearAllCachesAsync()
    {
        return CompletableFuture.runAsync(this::clearAllCaches, ensureExecutor());
    }

    private void clearAllCaches()
    {
        final Filepath dir;
        try
        {
            dir = getCacheDir();
        }
        catch (IOException ignored)
        {
            resetIndex();
            indexLoaded = true;
            return;
        }

        try (Stream<Filepath> files = dir.walk(1))
        {
            files.filter(path -> !path.equals(dir))
                    .filter(Filepath::isFile)
                    .forEach(path ->
                    {
                        try
                        {
                            path.deleteIfExists();
                        }
                        catch (IOException ex)
                        {
                            log.debug("Failed to delete drop cache {}", path, ex);
                        }
                    });
        }
        catch (IOException ex)
        {
            log.debug("Error clearing drop cache directory {}", dir, ex);
        }

        resetIndex();
        indexLoaded = true;
    }

    private void removeIndex(Filepath path)
    {
        NpcDropData data = cache.remove(path);
        if (data != null)
        {
            nameIndex.remove(buildNameKey(data.getName(), data.getLevel()));
        }
    }

    private void loadIndex()
    {
        if (indexLoaded)
        {
            return;
        }

        synchronized (this)
        {
            if (indexLoaded)
            {
                return;
            }

            try
            {
                Filepath dir = getCacheDir();
                try (Stream<Filepath> files = dir.walk(1))
                {
                    for (Filepath path : files
                            .filter(file -> !file.equals(dir))
                            .filter(Filepath::isFile)
                            .collect(Collectors.toList()))
                    {
                        if (!isFresh(path))
                        {
                            path.deleteIfExists();
                            continue;
                        }

                        try (BufferedReader reader = path.openBufferedReader())
                        {
                            NpcDropData data = gson.fromJson(reader, NpcDropData.class);
                            if (data != null && data.getDropTableSections() != null && !data.getDropTableSections().isEmpty())
                            {
                                cache.put(path, data);
                                nameIndex.put(buildNameKey(data.getName(), data.getLevel()), path);
                            }
                            else
                            {
                                path.deleteIfExists();
                            }
                        }
                        catch (Exception e)
                        {
                            log.warn("Skipping bad cache file {}", path, e);
                            path.deleteIfExists();
                        }
                    }
                }
            }
            catch (IOException e)
            {
                log.debug("Error loading cache index", e);
            }

            indexLoaded = true;
        }
    }

    public synchronized void shutdown()
    {
        ExecutorService executor = ioExecutor;
        if (executor != null)
        {
            executor.shutdownNow();
            ioExecutor = null;
        }
        resetIndex();
    }

    private synchronized ExecutorService ensureExecutor()
    {
        if (ioExecutor == null || ioExecutor.isShutdown() || ioExecutor.isTerminated())
        {
            ioExecutor = Executors.newFixedThreadPool(
                    2,
                    new ThreadFactoryBuilder().setNameFormat("rollbound-dropcache-%d").setDaemon(true).build());
        }
        return ioExecutor;
    }

    private static String buildNameKey(String name, int level)
    {
        return safeFilePart(name) + "_" + level;
    }

    private static String safeFilePart(String value)
    {
        String safe = value == null ? "" : value.replaceAll("[^A-Za-z0-9]", "_");
        safe = safe.replaceAll("_+", "_");
        return safe.isEmpty() ? "unknown" : safe;
    }

    private static String safeSegment(String value)
    {
        String safe = value == null ? "" : value.replaceAll("[^A-Za-z0-9 _-]", "_").trim();
        return safe.isEmpty() ? "unknown" : safe;
    }
}

package com.rollbound.drops;

import com.google.common.util.concurrent.ThreadFactoryBuilder;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import net.runelite.api.ItemComposition;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.http.api.item.ItemPrice;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.StringJoiner;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/**
 * Retrieves exact NPC drop data from the OSRS Wiki Bucket API.
 *
 * Unlike the old HTML scraper, this resolves the concrete NPC variant first and
 * then selects only the Bucket drop rows that belong to that variant. This avoids
 * hidden/alternate Wiki tables leaking into the displayed drop table.
 */
@Singleton
public class DropFetcher
{
    private static final Logger log = LoggerFactory.getLogger(DropFetcher.class);
    private static final String USER_AGENT = "RuneLite-RollBound/5.1.8";
    private static final String WIKI_API = "https://oldschool.runescape.wiki/api.php";
    private static final int NPC_SEARCH_LIMIT = 50;

    private final OkHttpClient httpClient;
    private final ItemManager itemManager;
    private final ClientThread clientThread;

    private final Map<String, WikiPageMetadata> metadataCache = new ConcurrentHashMap<>();
    private final Map<String, List<WikiDropBucketParser.BucketDrop>> dropRowsCache = new ConcurrentHashMap<>();
    private final Map<String, Integer> itemIdByName = new ConcurrentHashMap<>();

    private ExecutorService fetchExecutor;

    @Inject
    public DropFetcher(OkHttpClient httpClient, ItemManager itemManager, ClientThread clientThread)
    {
        this.httpClient = httpClient;
        this.itemManager = itemManager;
        this.clientThread = clientThread;
    }

    public CompletableFuture<NpcDropData> fetch(int npcId, String name, int level)
    {
        return CompletableFuture.supplyAsync(() -> fetchDropData(npcId, name, level), ensureExecutor())
                .thenCompose(this::resolveForDisplay);
    }

    /** Return all exact Wiki NPC variants for a search result page. */
    public CompletableFuture<List<NpcDropData>> fetchVariants(String name, int level)
    {
        return CompletableFuture.supplyAsync(() -> fetchVariantDropData(name, level), ensureExecutor())
                .thenCompose(this::resolveAllForDisplay);
    }

    private List<NpcDropData> fetchVariantDropData(String name, int level)
    {
        NpcPageReference page = resolveNpcPage(0, name);
        if (page == null || page.pageName.isEmpty())
        {
            return Collections.emptyList();
        }

        WikiPageMetadata metadata = loadMetadata(page.pageName);
        List<WikiMonsterMetadataParser.Variant> variants = metadata.monster.selectVariants(level);
        if (variants.isEmpty())
        {
            if (level > 0)
            {
                return Collections.emptyList();
            }

            NpcDropData fallback = fetchDropDataRaw(0, page.pageName, 0);
            return fallback == null ? Collections.emptyList() : Collections.singletonList(fallback);
        }

        List<WikiDropBucketParser.BucketDrop> rows = loadDropRows(page.pageName);
        Map<String, NpcDropData> distinct = new LinkedHashMap<>();

        for (WikiMonsterMetadataParser.Variant variant : variants)
        {
            int resolvedLevel = variant.getCombatLevel() > 0 ? variant.getCombatLevel() : level;
            if (level > 0 && resolvedLevel != level)
            {
                continue;
            }

            int resolvedNpcId = firstNpcId(variant);
            NpcDropData data = buildDropData(page.pageName, metadata, rows, variant, resolvedNpcId, resolvedLevel);
            if (data != null)
            {
                distinct.putIfAbsent(variantIdentity(variant, resolvedNpcId, resolvedLevel), data);
            }
        }

        return new ArrayList<>(distinct.values());
    }

    private NpcDropData fetchDropData(int npcId, String name, int level)
    {
        return fetchDropDataRaw(npcId, name, level);
    }

    private NpcDropData fetchDropDataRaw(int npcId, String name, int level)
    {
        NpcPageReference page = resolveNpcPage(npcId, name);
        if (page == null || page.pageName.isEmpty())
        {
            return null;
        }

        WikiPageMetadata metadata = loadMetadata(page.pageName);
        WikiMonsterMetadataParser.Variant variant = metadata.monster.selectVariant(npcId, level, page.pageSub);

        if (npcId <= 0 && level > 0)
        {
            if (variant == null || (variant.getCombatLevel() > 0 && variant.getCombatLevel() != level))
            {
                return null;
            }
        }

        return buildDropData(page.pageName, metadata, loadDropRows(page.pageName), variant, npcId, level);
    }

    private NpcDropData buildDropData(String pageName,
                                      WikiPageMetadata metadata,
                                      List<WikiDropBucketParser.BucketDrop> rows,
                                      WikiMonsterMetadataParser.Variant variant,
                                      int npcId,
                                      int level)
    {
        int resolvedLevel = level > 0 ? level : variant == null ? 0 : variant.getCombatLevel();
        int resolvedNpcId = npcId > 0 ? npcId : firstNpcId(variant);
        List<String> dropVersions = new ArrayList<>(effectiveDropVersions(variant));

        Set<String> locationVersions = metadata.locationDropVersionsByLevel
                .getOrDefault(resolvedLevel, Collections.emptySet());
        if (locationVersions.size() == 1)
        {
            dropVersions.add(locationVersions.iterator().next());
        }

        List<DropTableSection> sections = WikiDropBucketParser.selectSections(
                rows, dropVersions, resolvedLevel, metadata.dropTableClassification, false);

        return sections.isEmpty() ? null : new NpcDropData(resolvedNpcId, pageName, resolvedLevel, sections);
    }

    private CompletableFuture<NpcDropData> resolveForDisplay(NpcDropData data)
    {
        if (data == null)
        {
            return CompletableFuture.completedFuture(null);
        }

        CompletableFuture<NpcDropData> future = new CompletableFuture<>();
        clientThread.invoke(() ->
        {
            try
            {
                for (DropTableSection section : data.getDropTableSections())
                {
                    for (DropItem item : section.getItems())
                    {
                        item.setItemId(resolveItemId(item.getName()));
                    }
                    section.getItems().removeIf(item -> item.getItemId() <= 0);
                }
                data.getDropTableSections().removeIf(section -> section.getItems().isEmpty());
                future.complete(data.getDropTableSections().isEmpty() ? null : data);
            }
            catch (Throwable ex)
            {
                future.completeExceptionally(ex);
            }
        });
        return future;
    }

    private CompletableFuture<List<NpcDropData>> resolveAllForDisplay(List<NpcDropData> raw)
    {
        if (raw == null || raw.isEmpty())
        {
            return CompletableFuture.completedFuture(Collections.emptyList());
        }

        CompletableFuture<List<NpcDropData>> future = new CompletableFuture<>();
        clientThread.invoke(() ->
        {
            try
            {
                List<NpcDropData> output = new ArrayList<>();
                for (NpcDropData data : raw)
                {
                    if (data == null) continue;
                    for (DropTableSection section : data.getDropTableSections())
                    {
                        for (DropItem item : section.getItems())
                        {
                            item.setItemId(resolveItemId(item.getName()));
                        }
                        section.getItems().removeIf(item -> item.getItemId() <= 0);
                    }
                    data.getDropTableSections().removeIf(section -> section.getItems().isEmpty());
                    if (!data.getDropTableSections().isEmpty())
                    {
                        output.add(data);
                    }
                }
                future.complete(output);
            }
            catch (Throwable ex)
            {
                future.completeExceptionally(ex);
            }
        });
        return future;
    }

    private int resolveItemId(String wikiName)
    {
        for (String candidate : itemNameCandidates(wikiName))
        {
            String key = normalizeItemName(candidate);
            Integer cached = itemIdByName.get(key);
            if (cached != null)
            {
                return cached;
            }

            try
            {
                List<ItemPrice> results = itemManager.search(candidate);
                if (results == null) continue;

                for (ItemPrice result : results)
                {
                    ItemComposition item = itemManager.getItemComposition(result.getId());
                    if (item == null) continue;

                    String displayName = item.getMembersName();
                    if (displayName == null || displayName.trim().isEmpty())
                    {
                        displayName = item.getName();
                    }
                    if (key.equals(normalizeItemName(displayName)))
                    {
                        int id = itemManager.canonicalize(result.getId());
                        itemIdByName.put(key, id);
                        return id;
                    }
                }
            }
            catch (RuntimeException ex)
            {
                log.debug("Could not resolve Wiki drop item {}", candidate, ex);
            }
        }
        return 0;
    }

    private static List<String> itemNameCandidates(String wikiName)
    {
        String exact = wikiName == null ? "" : wikiName.trim();
        if (exact.isEmpty()) return Collections.emptyList();

        Map<String, String> candidates = new LinkedHashMap<>();
        candidates.put(normalizeItemName(exact), exact);
        int anchor = exact.indexOf('#');
        if (anchor >= 0)
        {
            String withoutAnchor = exact.replace("#", "");
            String spacedAnchor = exact.replace("#", " ");
            String beforeAnchor = exact.substring(0, anchor).trim();
            candidates.putIfAbsent(normalizeItemName(withoutAnchor), withoutAnchor);
            candidates.putIfAbsent(normalizeItemName(spacedAnchor), spacedAnchor);
            candidates.putIfAbsent(normalizeItemName(beforeAnchor), beforeAnchor);
        }
        candidates.remove("");
        return new ArrayList<>(candidates.values());
    }

    private static String normalizeItemName(String itemName)
    {
        return itemName == null ? "" : itemName
                .replace('\u00A0', ' ')
                .replace('\u2018', '\'')
                .replace('\u2019', '\'')
                .replace('_', ' ')
                .replaceAll("\\s+", " ")
                .trim()
                .toLowerCase(Locale.ROOT);
    }

    private WikiPageMetadata loadMetadata(String pageName)
    {
        try
        {
            return metadataCache.computeIfAbsent(pageName, key ->
            {
                String wikitext = fetchRawWikitext(key);
                return new WikiPageMetadata(
                        WikiMonsterMetadataParser.parse(wikitext),
                        WikiDropTableClassifier.parse(wikitext),
                        locationDropVersionsByLevel(wikitext));
            });
        }
        catch (RuntimeException ex)
        {
            log.warn("Could not load monster metadata for {}", pageName, ex);
            return WikiPageMetadata.empty();
        }
    }

    private List<WikiDropBucketParser.BucketDrop> loadDropRows(String pageName)
    {
        return dropRowsCache.computeIfAbsent(pageName, key ->
        {
            String query = "bucket('dropsline')"
                    + ".select('page_name','page_name_sub','drop_json','rare_drop_table')"
                    + ".where('page_name'," + luaString(key) + ")"
                    + ".limit(5000).run()";
            return Collections.unmodifiableList(new ArrayList<>(
                    WikiDropBucketParser.parseResponse(executeBucketQuery(query))));
        });
    }

    private NpcPageReference resolveNpcPage(int npcId, String suppliedName)
    {
        String name = sanitizeName(suppliedName);
        if (npcId > 0)
        {
            try
            {
                NpcPageReference page = resolveNpcPageFromBucket(npcId, name);
                if (page != null) return page;
            }
            catch (RuntimeException ex)
            {
                log.warn("NPC ID Bucket lookup failed for {}", npcId, ex);
            }
        }
        return name.isEmpty() ? null : new NpcPageReference(resolveCanonicalTitle(name), "");
    }

    private NpcPageReference resolveNpcPageFromBucket(int npcId, String suppliedName)
    {
        String query = "bucket('npc_id')"
                + ".select('page_name','page_name_sub')"
                + ".where('id'," + npcId + ")"
                + ".limit(20).run()";

        NpcPageReference first = null;
        for (JsonElement element : bucketRows(executeBucketQuery(query)))
        {
            if (!element.isJsonObject()) continue;
            JsonObject row = element.getAsJsonObject();
            String pageName = WikiDropBucketParser.stringValue(row.get("page_name"));
            if (pageName.isEmpty()) continue;

            NpcPageReference candidate = new NpcPageReference(pageName,
                    WikiDropBucketParser.extractPageSub(pageName,
                            WikiDropBucketParser.stringValue(row.get("page_name_sub"))));
            if (first == null) first = candidate;
            if (!suppliedName.isEmpty() && sameWikiName(pageName, suppliedName)) return candidate;
        }
        return first;
    }

    private String resolveCanonicalTitle(String title)
    {
        JsonObject page = firstQueryPage(executeGet(apiUrl(
                "action", "query", "redirects", "1", "titles", title)));
        String canonical = page == null ? "" : WikiDropBucketParser.stringValue(page.get("title"));
        return canonical.isEmpty() ? title : canonical;
    }

    private String fetchRawWikitext(String pageName)
    {
        JsonObject page = firstQueryPage(executeGet(apiUrl(
                "action", "query", "redirects", "1", "prop", "revisions", "titles", pageName,
                "rvprop", "content", "rvslots", "main")));
        if (page == null) return "";

        JsonArray revisions = page.getAsJsonArray("revisions");
        if (revisions == null || revisions.size() == 0 || !revisions.get(0).isJsonObject()) return "";

        JsonObject revision = revisions.get(0).getAsJsonObject();
        JsonObject slots = revision.getAsJsonObject("slots");
        JsonObject main = slots == null ? null : slots.getAsJsonObject("main");
        if (main != null)
        {
            String content = WikiDropBucketParser.stringValue(main.get("content"));
            return content.isEmpty() ? WikiDropBucketParser.stringValue(main.get("*")) : content;
        }
        return WikiDropBucketParser.stringValue(revision.get("*"));
    }

    public List<String> searchNpcNames(String query)
    {
        JsonArray response = new JsonParser().parse(executeGet(apiUrl(
                "action", "opensearch", "limit", String.valueOf(NPC_SEARCH_LIMIT), "namespace", "0",
                "search", query == null ? "" : query))).getAsJsonArray();
        if (response.size() < 2 || !response.get(1).isJsonArray())
        {
            return Collections.emptyList();
        }

        List<String> names = new ArrayList<>();
        for (JsonElement title : response.get(1).getAsJsonArray())
        {
            names.add(title.getAsString());
        }
        return names;
    }

    private String executeBucketQuery(String query)
    {
        return executeGet(apiUrl("action", "bucket", "query", query));
    }

    private String executeGet(String url)
    {
        Request request = new Request.Builder().url(url).header("User-Agent", USER_AGENT).build();
        try (Response response = httpClient.newCall(request).execute())
        {
            if (!response.isSuccessful())
            {
                throw new IOException("HTTP " + response.code() + " for " + response.request().url());
            }
            ResponseBody body = response.body();
            if (body == null)
            {
                throw new IOException("Empty response body for " + response.request().url());
            }
            return body.string();
        }
        catch (IOException ex)
        {
            throw new UncheckedIOException(ex);
        }
    }

    private static JsonObject firstQueryPage(String responseBody)
    {
        JsonElement parsed = new JsonParser().parse(responseBody);
        if (!parsed.isJsonObject()) return null;
        JsonObject query = parsed.getAsJsonObject().getAsJsonObject("query");
        JsonArray pages = query == null ? null : query.getAsJsonArray("pages");
        return pages == null || pages.size() == 0 || !pages.get(0).isJsonObject()
                ? null : pages.get(0).getAsJsonObject();
    }

    private static JsonArray bucketRows(String responseBody)
    {
        JsonElement parsed = new JsonParser().parse(responseBody);
        if (!parsed.isJsonObject()) return new JsonArray();
        JsonObject root = parsed.getAsJsonObject();
        String error = WikiDropBucketParser.stringValue(root.get("error"));
        if (!error.isEmpty()) throw new IllegalArgumentException("Wiki Bucket query failed: " + error);
        JsonElement bucket = root.get("bucket");
        return bucket != null && bucket.isJsonArray() ? bucket.getAsJsonArray() : new JsonArray();
    }

    private static String apiUrl(String... parameters)
    {
        if (parameters.length % 2 != 0) throw new IllegalArgumentException("API parameters must be key/value pairs");
        StringJoiner query = new StringJoiner("&", WIKI_API + "?", "");
        query.add(parameter("format", "json"));
        query.add(parameter("formatversion", "2"));
        for (int i = 0; i < parameters.length; i += 2)
        {
            query.add(parameter(parameters[i], parameters[i + 1]));
        }
        return query.toString();
    }

    private static String parameter(String key, String value)
    {
        return URLEncoder.encode(key, StandardCharsets.UTF_8) + "="
                + URLEncoder.encode(Objects.toString(value, ""), StandardCharsets.UTF_8);
    }

    private static String luaString(String value)
    {
        String escaped = Objects.toString(value, "")
                .replace("\\", "\\\\").replace("\"", "\\\"")
                .replace("\r", "\\r").replace("\n", "\\n");
        return "\"" + escaped + "\"";
    }

    private static String variantIdentity(WikiMonsterMetadataParser.Variant variant, int npcId, int level)
    {
        if (npcId > 0) return "id:" + npcId;
        return "variant:" + WikiMonsterMetadataParser.normalizeForComparison(variant.getVersion())
                + "|drops:" + String.join(",", effectiveDropVersions(variant)) + "|level:" + level;
    }

    private static List<String> effectiveDropVersions(WikiMonsterMetadataParser.Variant variant)
    {
        if (variant == null) return Collections.emptyList();
        List<String> versions = new ArrayList<>(variant.getDropVersions());
        versions.addAll(variant.getSubNames());
        return versions;
    }

    private static int firstNpcId(WikiMonsterMetadataParser.Variant variant)
    {
        return variant == null || variant.getNpcIds().isEmpty() ? 0 : variant.getNpcIds().iterator().next();
    }

    private static Map<Integer, Set<String>> locationDropVersionsByLevel(String wikitext)
    {
        Map<Integer, Set<String>> byLevel = new LinkedHashMap<>();
        for (WikiTemplateParser.Template location : WikiTemplateParser.findAll(wikitext, "LocLine"))
        {
            String version = sanitizeName(location.get("dropversion"));
            if (version.isEmpty()) continue;
            String levels = location.get("levels");
            if (levels.isEmpty()) levels = location.get("level");
            for (int level : WikiMonsterMetadataParser.parseIntegers(levels))
            {
                byLevel.computeIfAbsent(level, ignored -> new LinkedHashSet<>()).add(version);
            }
        }
        return byLevel;
    }

    private static boolean sameWikiName(String left, String right)
    {
        return normalizeWikiName(left).equals(normalizeWikiName(right));
    }

    private static String normalizeWikiName(String value)
    {
        return sanitizeName(value).replace('_', ' ').replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    private static String sanitizeName(String value)
    {
        return value == null ? "" : value.trim();
    }

    public void startUp()
    {
        ensureExecutor();
    }

    private synchronized ExecutorService ensureExecutor()
    {
        if (fetchExecutor == null || fetchExecutor.isShutdown() || fetchExecutor.isTerminated())
        {
            fetchExecutor = Executors.newFixedThreadPool(4,
                    new ThreadFactoryBuilder().setNameFormat("rollbound-dropfetch-%d").setDaemon(true).build());
        }
        return fetchExecutor;
    }

    public synchronized void shutdown()
    {
        if (fetchExecutor != null)
        {
            fetchExecutor.shutdownNow();
            fetchExecutor = null;
        }
        metadataCache.clear();
        dropRowsCache.clear();
        itemIdByName.clear();
    }

    private static final class WikiPageMetadata
    {
        private final WikiMonsterMetadataParser.ParsedMonster monster;
        private final WikiDropTableClassifier.Classification dropTableClassification;
        private final Map<Integer, Set<String>> locationDropVersionsByLevel;

        private WikiPageMetadata(WikiMonsterMetadataParser.ParsedMonster monster,
                                 WikiDropTableClassifier.Classification dropTableClassification,
                                 Map<Integer, Set<String>> locationDropVersionsByLevel)
        {
            this.monster = monster;
            this.dropTableClassification = dropTableClassification;
            this.locationDropVersionsByLevel = locationDropVersionsByLevel;
        }

        private static WikiPageMetadata empty()
        {
            return new WikiPageMetadata(WikiMonsterMetadataParser.ParsedMonster.empty(),
                    WikiDropTableClassifier.Classification.empty(), Collections.emptyMap());
        }
    }

    private static final class NpcPageReference
    {
        private final String pageName;
        private final String pageSub;

        private NpcPageReference(String pageName, String pageSub)
        {
            this.pageName = sanitizeName(pageName);
            this.pageSub = sanitizeName(pageSub);
        }
    }
}

package com.rollbound.drops;

import lombok.Getter;
import lombok.Setter;

import java.util.Arrays;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

@Setter
@Getter
public class DropItem
{
    private int itemId;
    private String name;
    private String rarity;

    // Anchored patterns for correctness & speed
    private static final Pattern PCT       = Pattern.compile("^(\\d+(?:\\.\\d+)?)%$");
    private static final Pattern MULT      = Pattern.compile("^(\\d+(?:\\.\\d+)?)\\s*[xX]\\s*(\\d+(?:\\.\\d+)?)\\s*/\\s*(\\d+(?:\\.\\d+)?)$");
    private static final Pattern FRAC      = Pattern.compile("^(\\d+(?:\\.\\d+)?)\\s*/\\s*(\\d+(?:\\.\\d+)?)$");
    private static final Pattern PAREN     = Pattern.compile("\\s*\\([^)]*\\)$", Pattern.UNICODE_CASE);
    private static final Pattern IN_SYNT   = Pattern.compile("\\bin\\b", Pattern.CASE_INSENSITIVE);
    private static final Pattern BRACKETS  = Pattern.compile("\\[[^\\]]*\\]");
    private static final Pattern ONE_OVER  = Pattern.compile("1/(\\d+(?:\\.\\d+)?)");

    public DropItem(int itemId, String name, String rarity)
    {
        this.itemId = itemId;
        this.name = name;
        this.rarity = rarity;
    }

    /** Convert raw rarity to normalized one-over form (preserves ranges like “1/64–1/32”). */
    public String getOneOverRarity()
    {
        if (rarity == null) return "";
        String[] parts = rarity.split("\\s*;\\s*|,\\s+");
        return Arrays.stream(parts)
                .map(this::normalizeSegment)
                .collect(Collectors.joining("; "));
    }

    /**
     * Parse rarity and return the denominator (e.g., “1/128” -> 128).
     * Unknown values sort as rarest (POSITIVE_INFINITY). “Always” -> 0.
     */
    public double getRarityValue()
    {
        String oneOver = getOneOverRarity();
        if (oneOver.isEmpty())
        {
            return Double.POSITIVE_INFINITY;
        }

        Matcher m = ONE_OVER.matcher(oneOver);
        if (m.find())
        {
            try { return Double.parseDouble(m.group(1)); }
            catch (NumberFormatException ignored) { return Double.POSITIVE_INFINITY; }
        }

        if (oneOver.equalsIgnoreCase("Always"))
        {
            return 0d;
        }

        return Double.POSITIVE_INFINITY;
    }

    private String normalizeSegment(String raw)
    {
        String cleaned = raw == null ? "" : raw;
        cleaned = BRACKETS.matcher(cleaned).replaceAll("");
        cleaned = cleaned
                .replace("×", "x")
                .replace(",", "")
                .replace("≈", "")
                .replace("~", "")
                .replaceAll(PAREN.pattern(), "")
                .replaceAll(IN_SYNT.pattern(), "/")
                .trim();

        // Handle ranges like "1/128 – 1/64"
        String[] range = cleaned.split("\\s*[–—-]\\s*");
        if (range.length > 1)
        {
            return Arrays.stream(range)
                    .map(this::simplifySingle)
                    .collect(Collectors.joining("–"));
        }

        return simplifySingle(cleaned);
    }

    private String simplifySingle(String s)
    {
        if (s == null || s.isEmpty())
        {
            return "";
        }

        Matcher m;

        // 12.5%
        m = PCT.matcher(s);
        if (m.matches())
        {
            double pct = safeDouble(m.group(1));
            if (pct == 0) return "0";
            return formatOneOver(100.0 / pct);
        }

        // 2 x 1 / 128
        m = MULT.matcher(s);
        if (m.matches())
        {
            double factor = safeDouble(m.group(1));
            double a = safeDouble(m.group(2));
            double b = safeDouble(m.group(3));
            if (factor != 0 && a != 0)
            {
                return formatOneOver(b / (a * factor));
            }
        }

        // 1/128
        m = FRAC.matcher(s);
        if (m.matches())
        {
            double a = safeDouble(m.group(1));
            double b = safeDouble(m.group(2));
            if (a != 0)
            {
                return formatOneOver(b / a);
            }
        }

        // fallback to cleaned input
        return s;
    }

    private double safeDouble(String s)
    {
        try { return Double.parseDouble(s); }
        catch (Exception e) { return Double.NaN; }
    }

    private String formatOneOver(double val)
    {
        if (Double.isNaN(val) || Double.isInfinite(val))
        {
            return "";
        }
        if (Math.abs(val - Math.round(val)) < 0.01)
        {
            return "1/" + Math.round(val);
        }
        return String.format(Locale.ROOT, "1/%.2f", val);
    }
}

