package com.rollbound.drops;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.google.gson.JsonPrimitive;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Converts OSRS Wiki Bucket:dropsline API results into RollBound drop-table models. */
final class WikiDropBucketParser
{
    private static final Pattern INTEGER = Pattern.compile("\\d+");
    private static final String NORMAL_SECTION = "Drops";
    private static final String RARE_SECTION = "Rare drop table";
    private static final String GEM_SECTION = "Gem drop table";
    private static final String COMBINED_SECTION = "Rare and Gem drop table";

    private WikiDropBucketParser() { }

    static List<BucketDrop> parseResponse(String responseBody)
    {
        JsonElement parsed = new JsonParser().parse(responseBody);
        if (!parsed.isJsonObject())
        {
            return Collections.emptyList();
        }

        JsonObject root = parsed.getAsJsonObject();
        String error = stringValue(root.get("error"));
        if (!error.isEmpty())
        {
            throw new IllegalArgumentException("Wiki Bucket query failed: " + error);
        }

        JsonElement bucket = root.get("bucket");
        if (bucket == null || !bucket.isJsonArray())
        {
            return Collections.emptyList();
        }

        List<BucketDrop> drops = new ArrayList<>();
        for (JsonElement element : bucket.getAsJsonArray())
        {
            if (!element.isJsonObject())
            {
                continue;
            }

            JsonObject row = element.getAsJsonObject();
            addRowDrops(row.get("drop_json"), row.get("rare_drop_table"),
                    stringValue(row.get("page_name")), row.get("page_name_sub"), drops);
        }
        return drops;
    }

    private static void addRowDrops(JsonElement dropJson, JsonElement rareDropTable,
                                    String pageName, JsonElement pageSub, List<BucketDrop> output)
    {
        if (dropJson == null || dropJson.isJsonNull())
        {
            return;
        }

        if (dropJson.isJsonArray())
        {
            JsonArray drops = dropJson.getAsJsonArray();
            for (int i = 0; i < drops.size(); i++)
            {
                addEmbeddedDrops(drops.get(i), booleanValue(elementAt(rareDropTable, i)),
                        pageName, stringValue(elementAt(pageSub, i)), output);
            }
            return;
        }

        addEmbeddedDrops(dropJson, booleanValue(rareDropTable), pageName, stringValue(pageSub), output);
    }

    private static void addEmbeddedDrops(JsonElement dropJson, boolean rareDropTable,
                                         String pageName, String pageSub, List<BucketDrop> output)
    {
        if (dropJson == null || dropJson.isJsonNull())
        {
            return;
        }
        if (dropJson.isJsonArray())
        {
            for (JsonElement element : dropJson.getAsJsonArray())
            {
                addEmbeddedDrops(element, rareDropTable, pageName, pageSub, output);
            }
            return;
        }

        JsonObject data = parseEmbeddedObject(dropJson);
        if (data == null)
        {
            return;
        }

        String itemName = stringValue(data.get("Dropped item")).trim();
        if (itemName.isEmpty())
        {
            itemName = stringValue(data.get("Dropped item from RDT")).trim();
        }
        if (itemName.isEmpty() || itemName.equalsIgnoreCase("nothing")
                || itemName.equalsIgnoreCase("coin") || itemName.equalsIgnoreCase("coins"))
        {
            return;
        }

        String sourceVersion = extractPageSub(pageName, pageSub);
        if (sourceVersion.isEmpty())
        {
            sourceVersion = extractSourceVersion(stringValue(data.get("Dropped from")));
        }

        output.add(new BucketDrop(itemName, buildRarity(data), sourceVersion,
                parseLevels(data.get("Drop level")), rareDropTable));
    }

    private static JsonObject parseEmbeddedObject(JsonElement element)
    {
        if (element.isJsonObject())
        {
            return element.getAsJsonObject();
        }
        if (!element.isJsonPrimitive())
        {
            return null;
        }

        String raw = element.getAsString();
        JsonObject direct = tryParseObject(raw);
        return direct == null ? tryParseObject(unescapeJsonEntities(raw)) : direct;
    }

    private static JsonObject tryParseObject(String value)
    {
        try
        {
            JsonElement parsed = new JsonParser().parse(value);
            return parsed.isJsonObject() ? parsed.getAsJsonObject() : null;
        }
        catch (RuntimeException ignored)
        {
            return null;
        }
    }

    private static String unescapeJsonEntities(String value)
    {
        return value.replace("&#123;", "{").replace("&#125;", "}")
                .replace("&#91;", "[").replace("&#93;", "]")
                .replace("&#34;", "\"").replace("&quot;", "\"")
                .replace("&#39;", "'").replace("&apos;", "'")
                .replace("&amp;", "&");
    }

    private static String buildRarity(JsonObject data)
    {
        String primary = cleanRarity(stringValue(data.get("Rarity")));
        String alternate = cleanRarity(stringValue(data.get("Alt Rarity")));
        boolean approximate = booleanValue(data.get("Approx"));
        int rolls = intValue(data.get("Rolls"), 1);

        if (approximate)
        {
            primary = approximate(primary);
            alternate = approximate(alternate);
        }
        if (rolls > 1 && !primary.isEmpty())
        {
            primary = rolls + " x " + primary;
        }
        if (primary.isEmpty() || alternate.isEmpty())
        {
            return primary.isEmpty() ? alternate : primary;
        }
        return primary + (hasContent(data.get("Alt Rarity Dash")) ? "–" : "; ") + alternate;
    }

    private static String approximate(String value)
    {
        return value.isEmpty() || value.startsWith("~") ? value : "~" + value;
    }

    private static String cleanRarity(String value)
    {
        return value.replace(",", "").trim();
    }

    static List<DropTableSection> selectSections(List<BucketDrop> allDrops,
                                                  List<String> targetDropVersions,
                                                  int combatLevel,
                                                  WikiDropTableClassifier.Classification classification,
                                                  boolean freeToPlay)
    {
        if (allDrops == null || allDrops.isEmpty())
        {
            return Collections.emptyList();
        }

        WikiDropTableClassifier.Classification tables = classification == null
                ? WikiDropTableClassifier.Classification.empty() : classification;
        List<String> selectedDropVersions = selectMembershipDropVersions(targetDropVersions, allDrops, freeToPlay);
        Map<String, DropItem> normal = new LinkedHashMap<>();
        Map<String, DropItem> rare = new LinkedHashMap<>();
        Map<String, DropItem> gem = new LinkedHashMap<>();
        Map<String, DropItem> combined = new LinkedHashMap<>();

        for (BucketDrop drop : selectRows(allDrops, selectedDropVersions, combatLevel, freeToPlay))
        {
            DropItem item = new DropItem(0, drop.getItemName(), drop.getRarity());
            if (!drop.isRareDropTable())
            {
                mergeMostCommon(normal, item);
                continue;
            }

            routeSpecialTableDrop(item, tables.resolve(drop.getSourceVersion(), selectedDropVersions),
                    rare, gem, combined);
        }

        List<DropTableSection> sections = new ArrayList<>();
        addSection(sections, NORMAL_SECTION, normal);
        addSection(sections, RARE_SECTION, rare);
        addSection(sections, GEM_SECTION, gem);
        addSection(sections, COMBINED_SECTION, combined);
        return sections;
    }

    private static void routeSpecialTableDrop(DropItem item, WikiDropTableClassifier.Access access,
                                               Map<String, DropItem> rare, Map<String, DropItem> gem,
                                               Map<String, DropItem> combined)
    {
        if (access.isGem() && !access.isRare())
        {
            mergeMostCommon(gem, item);
            return;
        }
        if (access.isRare() && !access.isGem())
        {
            mergeMostCommon(rare, item);
            return;
        }
        mergeMostCommon(combined, item);
    }

    static boolean isSpecialSection(String header)
    {
        return RARE_SECTION.equals(header) || GEM_SECTION.equals(header) || COMBINED_SECTION.equals(header);
    }

    private static void addSection(List<DropTableSection> sections, String header, Map<String, DropItem> items)
    {
        if (!items.isEmpty())
        {
            sections.add(new DropTableSection(header, new ArrayList<>(items.values())));
        }
    }

    private static List<BucketDrop> selectRows(List<BucketDrop> allDrops,
                                                List<String> targetDropVersions,
                                                int combatLevel,
                                                boolean freeToPlay)
    {
        Set<String> targets = normalizeVersions(targetDropVersions);
        Set<String> availableVersions = sourceVersions(allDrops);
        boolean membershipSplit = hasMembershipSplit(availableVersions);
        String selectedMembership = freeToPlay ? "free-to-play" : "members";
        List<BucketDrop> matches = new ArrayList<>();

        for (BucketDrop drop : allDrops)
        {
            Set<String> versions = normalizeVersions(
                    WikiMonsterMetadataParser.splitValues(drop.getSourceVersion(), "[,¦]"));
            if (membershipSplit
                    && (versions.contains("free-to-play") || versions.contains("members"))
                    && !versions.contains(selectedMembership))
            {
                continue;
            }

            if (!targets.isEmpty() && !versions.isEmpty() && Collections.disjoint(versions, targets))
            {
                continue;
            }

            if (combatLevel > 0 && !drop.getLevels().isEmpty() && !drop.getLevels().contains(combatLevel))
            {
                continue;
            }

            matches.add(drop);
        }
        return matches;
    }

    private static void mergeMostCommon(Map<String, DropItem> items, DropItem candidate)
    {
        String key = normalizeItemName(candidate.getName());
        DropItem existing = items.get(key);
        if (existing == null || candidate.getRarityValue() < existing.getRarityValue())
        {
            items.put(key, candidate);
        }
    }

    private static String normalizeItemName(String name)
    {
        return name == null ? "" : name.trim().replace('_', ' ').replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    private static Set<String> normalizeVersions(List<String> versions)
    {
        Set<String> normalized = new LinkedHashSet<>();
        if (versions != null)
        {
            for (String version : versions)
            {
                String value = normalizeDropVersion(version);
                if (!value.isEmpty() && !"default".equals(value))
                {
                    normalized.add(value);
                }
            }
        }
        return normalized;
    }

    private static List<String> selectMembershipDropVersions(List<String> versions,
                                                              List<BucketDrop> allDrops,
                                                              boolean freeToPlay)
    {
        Set<String> normalizedTargets = normalizeVersions(versions);
        boolean membershipSplit = hasMembershipSplit(normalizedTargets) || hasMembershipSplit(sourceVersions(allDrops));
        if (!membershipSplit)
        {
            return versions;
        }

        List<String> selected = new ArrayList<>();
        if (versions != null)
        {
            for (String version : versions)
            {
                String normalizedVersion = normalizeDropVersion(version);
                if (!"free-to-play".equals(normalizedVersion) && !"members".equals(normalizedVersion))
                {
                    selected.add(version);
                }
            }
        }
        selected.add(freeToPlay ? "Free-to-play" : "Members");
        return selected;
    }

    private static Set<String> sourceVersions(List<BucketDrop> drops)
    {
        Set<String> versions = new LinkedHashSet<>();
        if (drops != null)
        {
            for (BucketDrop drop : drops)
            {
                versions.addAll(normalizeVersions(
                        WikiMonsterMetadataParser.splitValues(drop.getSourceVersion(), "[,¦]")));
            }
        }
        return versions;
    }

    private static boolean hasMembershipSplit(Set<String> versions)
    {
        return versions.contains("free-to-play") && versions.contains("members");
    }

    private static String normalizeDropVersion(String value)
    {
        String normalized = WikiMonsterMetadataParser.normalizeForComparison(value);
        if (normalized.startsWith("drops (") && normalized.endsWith(")"))
        {
            normalized = normalized.substring(7, normalized.length() - 1).trim();
        }
        if (normalized.contains("free-to-play") || normalized.contains("free to play") || "f2p".equals(normalized))
        {
            return "free-to-play";
        }
        if (normalized.contains("member"))
        {
            return "members";
        }
        return normalized;
    }

    private static String extractSourceVersion(String source)
    {
        int hash = source == null ? -1 : source.indexOf('#');
        return hash < 0 ? "" : source.substring(hash + 1).trim();
    }

    static String extractPageSub(String pageName, String pageSub)
    {
        if (pageSub == null || pageSub.trim().isEmpty())
        {
            return "";
        }
        String value = pageSub.trim();
        int hash = value.indexOf('#');
        if (hash >= 0)
        {
            return value.substring(hash + 1).trim();
        }
        return WikiMonsterMetadataParser.normalizeForComparison(value)
                .equals(WikiMonsterMetadataParser.normalizeForComparison(pageName)) ? "" : value;
    }

    private static Set<Integer> parseLevels(JsonElement value)
    {
        return WikiMonsterMetadataParser.parseIntegers(stringValue(value));
    }

    static String stringValue(JsonElement value)
    {
        if (value == null || value.isJsonNull())
        {
            return "";
        }
        if (value.isJsonArray())
        {
            List<String> values = new ArrayList<>();
            for (JsonElement child : value.getAsJsonArray())
            {
                String childValue = stringValue(child);
                if (!childValue.isEmpty())
                {
                    values.add(childValue);
                }
            }
            return String.join(",", values);
        }
        return value.isJsonObject() ? value.toString() : value.getAsString();
    }

    private static boolean booleanValue(JsonElement value)
    {
        if (value == null || value.isJsonNull())
        {
            return false;
        }
        if (value.isJsonArray())
        {
            for (JsonElement child : value.getAsJsonArray())
            {
                if (booleanValue(child))
                {
                    return true;
                }
            }
            return false;
        }
        if (value.isJsonPrimitive())
        {
            JsonPrimitive primitive = value.getAsJsonPrimitive();
            if (primitive.isBoolean()) return primitive.getAsBoolean();
            if (primitive.isNumber()) return primitive.getAsDouble() != 0d;
        }
        String text = stringValue(value).trim().toLowerCase(Locale.ROOT);
        return "true".equals(text) || "yes".equals(text) || "1".equals(text);
    }

    private static JsonElement elementAt(JsonElement value, int index)
    {
        if (value == null || value.isJsonNull() || !value.isJsonArray())
        {
            return value;
        }
        JsonArray array = value.getAsJsonArray();
        return index >= 0 && index < array.size() ? array.get(index) : null;
    }

    private static boolean hasContent(JsonElement value)
    {
        return !stringValue(value).trim().isEmpty();
    }

    private static int intValue(JsonElement value, int fallback)
    {
        if (value == null || value.isJsonNull())
        {
            return fallback;
        }
        try
        {
            return value.getAsInt();
        }
        catch (RuntimeException ignored)
        {
            Matcher matcher = INTEGER.matcher(value.getAsString());
            if (!matcher.find()) return fallback;
            try { return Integer.parseInt(matcher.group()); }
            catch (NumberFormatException ignoredAgain) { return fallback; }
        }
    }

    static final class BucketDrop
    {
        private final String itemName;
        private final String rarity;
        private final String sourceVersion;
        private final Set<Integer> levels;
        private final boolean rareDropTable;

        BucketDrop(String itemName, String rarity, String sourceVersion, Set<Integer> levels, boolean rareDropTable)
        {
            this.itemName = itemName;
            this.rarity = rarity;
            this.sourceVersion = sourceVersion == null ? "" : sourceVersion;
            this.levels = Collections.unmodifiableSet(new LinkedHashSet<>(levels));
            this.rareDropTable = rareDropTable;
        }

        String getItemName() { return itemName; }
        String getRarity() { return rarity; }
        String getSourceVersion() { return sourceVersion; }
        Set<Integer> getLevels() { return levels; }
        boolean isRareDropTable() { return rareDropTable; }
    }
}

package com.rollbound.drops;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;

/** Classifies Wiki generated Rare and Gem drop table rows by drop version. */
final class WikiDropTableClassifier
{
    private static final Pattern ZERO_RATE = Pattern.compile("^0+(?:\\.0+)?(?:/[^/]+)?$");
    private static final Access NONE = new Access(false, false);

    private WikiDropTableClassifier() { }

    static Classification parse(String wikitext)
    {
        Map<String, Access> byVersion = new LinkedHashMap<>();
        for (WikiTemplateParser.Template template : WikiTemplateParser.findAll(
                wikitext, "RareDropTable", "RareDropLines", "GemDropTable", "GemDropLines"))
        {
            boolean rare = template.getName().startsWith("rare");
            boolean gem = template.getName().startsWith("gem") || (rare && hasRate(template.getPositional(), 1));
            Access access = new Access(rare, gem);

            List<String> versions = WikiMonsterMetadataParser.splitValues(template.get("dropversion"), "[,¦]");
            if (versions.isEmpty())
            {
                versions = WikiMonsterMetadataParser.splitValues(template.get("version"), "[,¦]");
            }
            if (versions.isEmpty())
            {
                versions = Collections.singletonList("");
            }

            for (String version : versions)
            {
                String key = WikiMonsterMetadataParser.normalizeForComparison(version);
                Access existing = byVersion.get(key);
                byVersion.put(key, existing == null ? access : existing.merge(access));
            }
        }
        return new Classification(byVersion);
    }

    private static boolean hasRate(List<String> positional, int index)
    {
        if (index >= positional.size())
        {
            return false;
        }
        String value = positional.get(index).replaceAll("\\s+", "");
        return !value.isEmpty() && !ZERO_RATE.matcher(value).matches();
    }

    static final class Access
    {
        private final boolean rare;
        private final boolean gem;

        Access(boolean rare, boolean gem) { this.rare = rare; this.gem = gem; }
        boolean isRare() { return rare; }
        boolean isGem() { return gem; }
        Access merge(Access other) { return other == null ? this : new Access(rare || other.rare, gem || other.gem); }
    }

    static final class Classification
    {
        private final Map<String, Access> byVersion;

        Classification(Map<String, Access> byVersion)
        {
            this.byVersion = Collections.unmodifiableMap(new LinkedHashMap<>(byVersion));
        }

        static Classification empty() { return new Classification(Collections.emptyMap()); }

        Access resolve(String sourceVersion, List<String> targetVersions)
        {
            Access resolved = byVersion.getOrDefault("", NONE);
            boolean found = false;

            for (String version : WikiMonsterMetadataParser.splitValues(sourceVersion, "[,¦]"))
            {
                Access access = byVersion.get(WikiMonsterMetadataParser.normalizeForComparison(version));
                if (access != null)
                {
                    resolved = resolved.merge(access);
                    found = true;
                }
            }

            if (!found && targetVersions != null)
            {
                for (String version : targetVersions)
                {
                    Access access = byVersion.get(WikiMonsterMetadataParser.normalizeForComparison(version));
                    if (access != null)
                    {
                        resolved = resolved.merge(access);
                    }
                }
            }
            return resolved;
        }
    }
}

package com.rollbound.drops;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

/** Parses NPC IDs, combat levels, variants, and drop versions from Infobox Monster. */
final class WikiMonsterMetadataParser
{
    private static final Pattern INDEXED_KEY = Pattern.compile(
            "^(version|bucketname|name|combat|id|dropversion)(\\d+)$", Pattern.CASE_INSENSITIVE);
    private static final Pattern INTEGER = Pattern.compile("\\d+");
    private static final Pattern WIKI_LINK = Pattern.compile("\\[\\[([^]\\|]+)(?:\\|([^]]+))?]]");

    private WikiMonsterMetadataParser() { }

    static ParsedMonster parse(String wikitext)
    {
        WikiTemplateParser.Template infobox = WikiTemplateParser.findFirst(wikitext, "Infobox Monster");
        if (infobox == null)
        {
            return ParsedMonster.empty();
        }

        Map<String, String> parameters = infobox.getNamed();
        int maximumIndex = 0;
        for (String key : parameters.keySet())
        {
            Matcher matcher = INDEXED_KEY.matcher(key);
            if (matcher.matches())
            {
                maximumIndex = Math.max(maximumIndex, Integer.parseInt(matcher.group(2)));
            }
        }

        int defaultIndex = parseFirstInteger(parameters.get("defver"));
        if (defaultIndex <= 0)
        {
            defaultIndex = maximumIndex > 0 ? 1 : 0;
        }

        List<Variant> variants = new ArrayList<>();
        if (maximumIndex == 0)
        {
            variants.add(buildVariant(parameters, 0, true));
        }
        else
        {
            for (int index = 1; index <= maximumIndex; index++)
            {
                Variant variant = buildVariant(parameters, index, index == defaultIndex);
                if (!variant.isEmpty())
                {
                    variants.add(variant);
                }
            }
        }
        return new ParsedMonster(variants);
    }

    private static Variant buildVariant(Map<String, String> parameters, int index, boolean defaultVariant)
    {
        String version = cleanDisplayValue(valueFor(parameters, "version", index));
        String bucketName = cleanDisplayValue(valueFor(parameters, "bucketname", index));
        String name = cleanDisplayValue(valueFor(parameters, "name", index));
        int combatLevel = parseFirstInteger(valueFor(parameters, "combat", index));
        Set<Integer> npcIds = parseIntegers(valueFor(parameters, "id", index));
        List<String> dropVersions = splitValues(cleanDisplayValue(valueFor(parameters, "dropversion", index)), "[,¦]");

        List<String> subNames = new ArrayList<>();
        subNames.addAll(splitValues(bucketName, "¦"));
        if (!version.isEmpty())
        {
            subNames.add(version);
        }

        return new Variant(version, name, combatLevel, npcIds, deduplicate(dropVersions), deduplicate(subNames), defaultVariant);
    }

    private static String valueFor(Map<String, String> parameters, String key, int index)
    {
        return index > 0 && parameters.containsKey(key + index)
                ? parameters.get(key + index)
                : parameters.getOrDefault(key, "");
    }

    private static String cleanDisplayValue(String value)
    {
        if (value == null)
        {
            return "";
        }

        Matcher matcher = WIKI_LINK.matcher(value.trim());
        StringBuffer output = new StringBuffer();
        while (matcher.find())
        {
            String replacement = matcher.group(2) == null ? matcher.group(1) : matcher.group(2);
            matcher.appendReplacement(output, Matcher.quoteReplacement(replacement));
        }
        matcher.appendTail(output);
        return output.toString().trim();
    }

    static int parseFirstInteger(String value)
    {
        Matcher matcher = INTEGER.matcher(value == null ? "" : value);
        if (!matcher.find())
        {
            return 0;
        }
        try
        {
            return Integer.parseInt(matcher.group());
        }
        catch (NumberFormatException ignored)
        {
            return 0;
        }
    }

    static Set<Integer> parseIntegers(String value)
    {
        Set<Integer> values = new LinkedHashSet<>();
        Matcher matcher = INTEGER.matcher(value == null ? "" : value);
        while (matcher.find())
        {
            try
            {
                values.add(Integer.parseInt(matcher.group()));
            }
            catch (NumberFormatException ignored) { }
        }
        return values;
    }

    static List<String> splitValues(String value, String delimiterRegex)
    {
        if (value == null || value.trim().isEmpty())
        {
            return Collections.emptyList();
        }

        List<String> values = new ArrayList<>();
        for (String part : value.split(delimiterRegex))
        {
            String cleaned = part.trim();
            if (!cleaned.isEmpty())
            {
                values.add(cleaned);
            }
        }
        return values;
    }

    private static List<String> deduplicate(List<String> values)
    {
        Map<String, String> unique = new LinkedHashMap<>();
        for (String value : values)
        {
            unique.putIfAbsent(normalizeForComparison(value), value);
        }
        return new ArrayList<>(unique.values());
    }

    static String normalizeForComparison(String value)
    {
        return value == null ? "" : value.trim().replace('_', ' ').replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    static final class ParsedMonster
    {
        private final List<Variant> variants;

        ParsedMonster(List<Variant> variants)
        {
            this.variants = Collections.unmodifiableList(new ArrayList<>(variants));
        }

        static ParsedMonster empty() { return new ParsedMonster(Collections.emptyList()); }
        List<Variant> getVariants() { return variants; }

        Variant selectVariant(int npcId, int combatLevel, String pageSub)
        {
            if (npcId > 0)
            {
                for (Variant variant : variants)
                {
                    if (variant.getNpcIds().contains(npcId))
                    {
                        return variant;
                    }
                }
            }

            String normalizedSub = normalizeForComparison(pageSub);
            if (!normalizedSub.isEmpty() && !"default".equals(normalizedSub))
            {
                for (Variant variant : variants)
                {
                    if (variant.matchesSubName(normalizedSub))
                    {
                        return variant;
                    }
                }
            }

            if (combatLevel > 0)
            {
                List<Variant> matchingLevel = selectVariants(combatLevel);
                if (matchingLevel.size() == 1)
                {
                    return matchingLevel.get(0);
                }
                if (matchingLevel.size() > 1)
                {
                    return null;
                }
            }

            for (Variant variant : variants)
            {
                if (variant.isDefaultVariant())
                {
                    return variant;
                }
            }
            return variants.isEmpty() ? null : variants.get(0);
        }

        List<Variant> selectVariants(int combatLevel)
        {
            if (combatLevel <= 0)
            {
                return new ArrayList<>(variants);
            }
            return variants.stream()
                    .filter(variant -> variant.getCombatLevel() == combatLevel)
                    .collect(Collectors.toList());
        }
    }

    static final class Variant
    {
        private final String version;
        private final String name;
        private final int combatLevel;
        private final Set<Integer> npcIds;
        private final List<String> dropVersions;
        private final List<String> subNames;
        private final boolean defaultVariant;

        Variant(String version, String name, int combatLevel, Set<Integer> npcIds,
                List<String> dropVersions, List<String> subNames, boolean defaultVariant)
        {
            this.version = version;
            this.name = name;
            this.combatLevel = combatLevel;
            this.npcIds = Collections.unmodifiableSet(new LinkedHashSet<>(npcIds));
            this.dropVersions = Collections.unmodifiableList(new ArrayList<>(dropVersions));
            this.subNames = Collections.unmodifiableList(new ArrayList<>(subNames));
            this.defaultVariant = defaultVariant;
        }

        String getVersion() { return version; }
        String getName() { return name; }
        int getCombatLevel() { return combatLevel; }
        Set<Integer> getNpcIds() { return npcIds; }
        List<String> getDropVersions() { return dropVersions; }
        List<String> getSubNames() { return subNames; }
        boolean isDefaultVariant() { return defaultVariant; }

        private boolean isEmpty()
        {
            return version.isEmpty() && name.isEmpty() && combatLevel == 0 && npcIds.isEmpty()
                    && dropVersions.isEmpty() && subNames.isEmpty();
        }

        private boolean matchesSubName(String normalizedSub)
        {
            return normalizeForComparison(version).equals(normalizedSub)
                    || subNames.stream().anyMatch(name -> normalizeForComparison(name).equals(normalizedSub));
        }
    }
}

package com.rollbound.drops;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;

/** Minimal parser for the OSRS Wiki templates used by drop metadata. */
final class WikiTemplateParser
{
    private static final Pattern COMMENT = Pattern.compile("<!--.*?-->", Pattern.DOTALL);

    private WikiTemplateParser() { }

    static Template findFirst(String wikitext, String name)
    {
        List<Template> matches = findAll(wikitext, name);
        return matches.isEmpty() ? null : matches.get(0);
    }

    static List<Template> findAll(String wikitext, String... names)
    {
        if (wikitext == null || wikitext.isEmpty() || names.length == 0)
        {
            return Collections.emptyList();
        }

        Set<String> wanted = new LinkedHashSet<>();
        Arrays.stream(names).map(WikiTemplateParser::normalizeName).forEach(wanted::add);

        String source = COMMENT.matcher(wikitext).replaceAll("");
        List<Template> matches = new ArrayList<>();
        for (int start = source.indexOf("{{"); start >= 0; start = source.indexOf("{{", start + 2))
        {
            int nameEnd = findNameEnd(source, start + 2);
            if (!wanted.contains(normalizeName(source.substring(start + 2, nameEnd))))
            {
                continue;
            }

            int end = findTemplateEnd(source, start);
            if (end < 0)
            {
                break;
            }

            Template template = parse(source.substring(start + 2, end - 2));
            if (template != null)
            {
                matches.add(template);
            }
        }
        return matches;
    }

    private static Template parse(String body)
    {
        List<String> parts = splitTopLevel(body, '|');
        if (parts.isEmpty())
        {
            return null;
        }

        Map<String, String> named = new LinkedHashMap<>();
        List<String> positional = new ArrayList<>();
        for (int i = 1; i < parts.size(); i++)
        {
            String part = parts.get(i).trim();
            int equals = findTopLevelEquals(part);
            if (equals < 0)
            {
                positional.add(part);
            }
            else
            {
                named.put(normalizeParameterName(part.substring(0, equals)), part.substring(equals + 1).trim());
            }
        }
        return new Template(normalizeName(parts.get(0)), named, positional);
    }

    private static int findNameEnd(String source, int start)
    {
        int cursor = start;
        while (cursor < source.length())
        {
            char c = source.charAt(cursor);
            if (c == '|' || c == '}' || c == '\n' || c == '\r')
            {
                break;
            }
            cursor++;
        }
        return cursor;
    }

    private static int findTemplateEnd(String source, int start)
    {
        int depth = 0;
        for (int i = start; i < source.length() - 1; i++)
        {
            char current = source.charAt(i);
            char next = source.charAt(i + 1);
            if (current == '{' && next == '{')
            {
                depth++;
                i++;
            }
            else if (current == '}' && next == '}')
            {
                depth--;
                i++;
                if (depth == 0)
                {
                    return i + 1;
                }
            }
        }
        return -1;
    }

    private static List<String> splitTopLevel(String input, char delimiter)
    {
        List<String> parts = new ArrayList<>();
        int start = 0;
        int end;
        while ((end = findTopLevelChar(input, delimiter, start)) >= 0)
        {
            parts.add(input.substring(start, end));
            start = end + 1;
        }
        parts.add(input.substring(start));
        return parts;
    }

    private static int findTopLevelEquals(String input)
    {
        return findTopLevelChar(input, '=', 0);
    }

    private static int findTopLevelChar(String input, char target, int start)
    {
        int templateDepth = 0;
        int linkDepth = 0;
        for (int i = start; i < input.length(); i++)
        {
            if (i + 1 < input.length())
            {
                char current = input.charAt(i);
                char next = input.charAt(i + 1);
                if (current == '{' && next == '{')
                {
                    templateDepth++;
                    i++;
                    continue;
                }
                if (current == '}' && next == '}' && templateDepth > 0)
                {
                    templateDepth--;
                    i++;
                    continue;
                }
                if (current == '[' && next == '[')
                {
                    linkDepth++;
                    i++;
                    continue;
                }
                if (current == ']' && next == ']' && linkDepth > 0)
                {
                    linkDepth--;
                    i++;
                    continue;
                }
            }
            if (input.charAt(i) == target && templateDepth == 0 && linkDepth == 0)
            {
                return i;
            }
        }
        return -1;
    }

    private static String normalizeName(String value)
    {
        String normalized = value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
        if (normalized.startsWith("template:"))
        {
            normalized = normalized.substring("template:".length());
        }
        return normalized.replace("_", "").replace(" ", "");
    }

    private static String normalizeParameterName(String value)
    {
        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT).replace("_", "").replace(" ", "");
    }

    static final class Template
    {
        private final String name;
        private final Map<String, String> named;
        private final List<String> positional;

        Template(String name, Map<String, String> named, List<String> positional)
        {
            this.name = name;
            this.named = Collections.unmodifiableMap(new LinkedHashMap<>(named));
            this.positional = Collections.unmodifiableList(new ArrayList<>(positional));
        }

        String getName() { return name; }
        Map<String, String> getNamed() { return named; }
        List<String> getPositional() { return positional; }
        String get(String key) { return named.getOrDefault(normalizeParameterName(key), ""); }
    }
}

package com.rollbound.filters;

import lombok.Getter;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

import net.runelite.api.gameval.ItemID;

/**
 * Maps ensouled head item IDs (including untradeable drop IDs) to their tradeable IDs.
 * Non-ensouled or unknown IDs are returned unchanged by {@link #toTradeableId(int)}.
 */
public final class EnsouledHeadMapping {

    @Getter
    public static final Map<Integer, Integer> ENSOULED_CANONICAL_ID;

    static {
        Map<Integer, Integer> idMap = new HashMap<>();

        java.util.function.BiConsumer<Integer, Integer> pair = (untradeable, tradeable) -> {
            idMap.put(untradeable, tradeable);
            idMap.put(tradeable, tradeable);
        };

        pair.accept(ItemID.ARCEUUS_CORPSE_GOBLIN_INITIAL, ItemID.ARCEUUS_CORPSE_GOBLIN); // Goblin
        pair.accept(ItemID.ARCEUUS_CORPSE_MONKEY_INITIAL, ItemID.ARCEUUS_CORPSE_MONKEY); // Monkey
        pair.accept(ItemID.ARCEUUS_CORPSE_IMP_INITIAL, ItemID.ARCEUUS_CORPSE_IMP); // Imp
        pair.accept(ItemID.ARCEUUS_CORPSE_MINOTAUR_INITIAL, ItemID.ARCEUUS_CORPSE_MINOTAUR); // Minotaur
        pair.accept(ItemID.ARCEUUS_CORPSE_SCORPION_INITIAL, ItemID.ARCEUUS_CORPSE_SCORPION); // Scorpion
        pair.accept(ItemID.ARCEUUS_CORPSE_BEAR_INITIAL, ItemID.ARCEUUS_CORPSE_BEAR); // Bear
        pair.accept(ItemID.ARCEUUS_CORPSE_UNICORN_INITIAL, ItemID.ARCEUUS_CORPSE_UNICORN ); // Unicorn
        pair.accept(ItemID.ARCEUUS_CORPSE_DOG_INITIAL, ItemID.ARCEUUS_CORPSE_DOG); // Dog
        pair.accept(ItemID.ARCEUUS_CORPSE_CHAOSDRUID_INITIAL, ItemID.ARCEUUS_CORPSE_CHAOSDRUID); // Chaos Druid
        pair.accept(ItemID.ARCEUUS_CORPSE_GIANT_INITIAL, ItemID.ARCEUUS_CORPSE_GIANT); // Giant
        pair.accept(ItemID.ARCEUUS_CORPSE_OGRE_INITIAL, ItemID.ARCEUUS_CORPSE_OGRE); // Ogre
        pair.accept(ItemID.ARCEUUS_CORPSE_ELF_INITIAL, ItemID.ARCEUUS_CORPSE_ELF); // Elf
        pair.accept(ItemID.ARCEUUS_CORPSE_TROLL_INITIAL, ItemID.ARCEUUS_CORPSE_TROLL); // Troll
        pair.accept(ItemID.ARCEUUS_CORPSE_HORROR_INITIAL, ItemID.ARCEUUS_CORPSE_HORROR); // Horror
        pair.accept(ItemID.ARCEUUS_CORPSE_KALPHITE_INITIAL, ItemID.ARCEUUS_CORPSE_KALPHITE); // Kalphite
        pair.accept(ItemID.ARCEUUS_CORPSE_DAGANNOTH_INITIAL, ItemID.ARCEUUS_CORPSE_DAGANNOTH); // Dagannoth
        pair.accept(ItemID.ARCEUUS_CORPSE_BLOODVELD_INITIAL, ItemID.ARCEUUS_CORPSE_BLOODVELD); // Bloodveld
        pair.accept(ItemID.ARCEUUS_CORPSE_TZHAAR_INITIAL, ItemID.ARCEUUS_CORPSE_TZHAAR); // TzHaar
        pair.accept(ItemID.ARCEUUS_CORPSE_DEMON_INITIAL, ItemID.ARCEUUS_CORPSE_DEMON); // Demon
        pair.accept(ItemID.ARCEUUS_CORPSE_AVIANSIE_INITIAL, ItemID.ARCEUUS_CORPSE_AVIANSIE); //Aviansie
        pair.accept(ItemID.ARCEUUS_CORPSE_ABYSSAL_INITIAL, ItemID.ARCEUUS_CORPSE_ABYSSAL); // Abyssal
        pair.accept(ItemID.ARCEUUS_CORPSE_DRAGON_INITIAL, ItemID.ARCEUUS_CORPSE_DRAGON); // Dragon
        pair.accept(ItemID.ARCEUUS_CORPSE_HELLHOUND_INITIAL, ItemID.ARCEUUS_CORPSE_HELLHOUND); // Hellhound

        ENSOULED_CANONICAL_ID = Collections.unmodifiableMap(idMap);
    }

    private EnsouledHeadMapping() { /* utility class, no instances */ }

    /**
     * Returns the tradeable ID for any ensouled head item ID.
     * If the ID is already tradeable or not recognized as an ensouled head, it's returned unchanged.
     */
    public static int toTradeableId(int itemId) {
        return ENSOULED_CANONICAL_ID.getOrDefault(itemId, itemId);
    }
}

