package com.rollbound.filters;

/**
 * Hard-coded RollBound item exclusions.
 *
 * Item sets and flatpacks are permanently outside the RollBound roll pool.
 * These rules are intentionally not configurable or synchronised through Firebase.
 */
public final class ItemsFilter
{
    private ItemsFilter()
    {
    }

    /**
     * Returns true when an item must never participate in RollBound progression.
     */
    public static boolean isBlocked(int itemId)
    {
        return Flatpacks.isFlatpack(itemId)
                || ItemSets.isItemSet(itemId)
                || BlockedItems.getBLOCKED_ITEMS().contains(itemId);
    }
}

package com.rollbound.firebase;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonNull;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.io.Reader;
import java.net.URI;
import java.util.Locale;
import java.util.concurrent.CompletableFuture;

/** REST + realtime-stream access to a user-provided Firebase Realtime Database. */
@Singleton
public final class FirebaseDatabaseClient
{
    static final String USER_AGENT = "RuneLite-RollBound/5.1.8";
    private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

    private final OkHttpClient httpClient;
    private final Gson gson;

    @Inject
    public FirebaseDatabaseClient(OkHttpClient httpClient, Gson gson)
    {
        this.httpClient = httpClient;
        this.gson = gson;
    }

    public String normaliseDatabaseUrl(String raw)
    {
        if (raw == null)
        {
            return null;
        }
        String value = raw.trim();
        if (value.isEmpty())
        {
            return null;
        }
        while (value.endsWith("/"))
        {
            value = value.substring(0, value.length() - 1);
        }

        try
        {
            URI uri = URI.create(value);
            String scheme = uri.getScheme();
            String host = uri.getHost();
            if (!"https".equalsIgnoreCase(scheme) || host == null)
            {
                return null;
            }
            String lowerHost = host.toLowerCase(Locale.ROOT);
            if (!lowerHost.endsWith(".firebaseio.com") && !lowerHost.endsWith(".firebasedatabase.app"))
            {
                return null;
            }
            String path = uri.getPath();
            if (uri.getQuery() != null || uri.getFragment() != null
                    || (path != null && !path.isEmpty() && !"/".equals(path)))
            {
                return null;
            }
            return value;
        }
        catch (Exception ignored)
        {
            return null;
        }
    }

    public CompletableFuture<JsonElement> get(String databaseUrl, String path)
    {
        Request request = requestBuilder(databaseUrl, path).get().build();
        return executeJson(request);
    }

    public CompletableFuture<JsonElement> patch(String databaseUrl, String path, JsonElement data)
    {
        return write(databaseUrl, path, "PATCH", data);
    }

    public CompletableFuture<Void> delete(String databaseUrl, String path)
    {
        Request request = requestBuilder(databaseUrl, path).delete().build();
        CompletableFuture<Void> future = new CompletableFuture<>();
        Call call = httpClient.newCall(request);
        call.enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException e)
            {
                future.completeExceptionally(e);
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (Response ignored = response)
                {
                    if (!response.isSuccessful())
                    {
                        future.completeExceptionally(httpException(request, response));
                        return;
                    }
                    future.complete(null);
                }
            }
        });
        return future;
    }

    public FirebaseSseStream stream(String databaseUrl, FirebaseSseStream.EventListener eventListener,
                                    Runnable connected, Runnable disconnected)
    {
        String url = pathUrl(databaseUrl, "/");
        return new FirebaseSseStream(httpClient, url, eventListener, connected, disconnected);
    }

    private CompletableFuture<JsonElement> write(String databaseUrl, String path, String method, JsonElement data)
    {
        String payload = gson.toJson(data);
        RequestBody body = RequestBody.create(JSON, payload);

        // None of RollBound's writes need Firebase to echo the written JSON back. Suppressing the
        // response avoids paying download bandwidth for data the SSE stream will deliver anyway.
        HttpUrl baseUrl = HttpUrl.parse(pathUrl(databaseUrl, path));
        if (baseUrl == null)
        {
            CompletableFuture<JsonElement> failed = new CompletableFuture<>();
            failed.completeExceptionally(new IllegalArgumentException("Invalid Firebase Realtime Database URL"));
            return failed;
        }
        HttpUrl silentUrl = baseUrl.newBuilder().addQueryParameter("print", "silent").build();
        Request request = new Request.Builder()
                .url(silentUrl)
                .header("User-Agent", USER_AGENT)
                .header("Content-Type", "application/json")
                .method(method, body)
                .build();
        return executeJson(request);
    }

    private CompletableFuture<JsonElement> executeJson(Request request)
    {
        CompletableFuture<JsonElement> future = new CompletableFuture<>();
        Call call = httpClient.newCall(request);
        call.enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException e)
            {
                future.completeExceptionally(e);
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (Response ignored = response)
                {
                    if (!response.isSuccessful())
                    {
                        future.completeExceptionally(httpException(request, response));
                        return;
                    }
                    if (response.code() == 204)
                    {
                        future.complete(JsonNull.INSTANCE);
                        return;
                    }
                    ResponseBody body = response.body();
                    if (body == null)
                    {
                        future.completeExceptionally(new IOException("Firebase returned an empty response"));
                        return;
                    }
                    try (Reader reader = body.charStream())
                    {
                        future.complete(gson.fromJson(reader, JsonElement.class));
                    }
                    catch (Exception error)
                    {
                        future.completeExceptionally(error);
                    }
                }
            }
        });
        return future;
    }

    private Request.Builder requestBuilder(String databaseUrl, String path)
    {
        return new Request.Builder()
                .url(pathUrl(databaseUrl, path))
                .header("User-Agent", USER_AGENT);
    }

    private String pathUrl(String databaseUrl, String path)
    {
        String base = normaliseDatabaseUrl(databaseUrl);
        if (base == null)
        {
            throw new IllegalArgumentException("Invalid Firebase Realtime Database URL");
        }

        HttpUrl parsed = HttpUrl.parse(base);
        if (parsed == null)
        {
            throw new IllegalArgumentException("Invalid Firebase Realtime Database URL");
        }

        HttpUrl.Builder builder = parsed.newBuilder();
        String clean = path == null ? "" : path.trim();
        if (clean.startsWith("/"))
        {
            clean = clean.substring(1);
        }

        if (clean.isEmpty())
        {
            builder.addPathSegment(".json");
        }
        else
        {
            String[] segments = clean.split("/");
            for (int i = 0; i < segments.length; i++)
            {
                String segment = segments[i];
                if (segment.isEmpty())
                {
                    continue;
                }
                if (i == segments.length - 1)
                {
                    builder.addPathSegment(segment + ".json");
                }
                else
                {
                    builder.addPathSegment(segment);
                }
            }
        }
        return builder.build().toString();
    }

    private IOException httpException(Request request, Response response)
    {
        String detail = "";
        ResponseBody body = response.body();
        if (body != null)
        {
            try
            {
                String text = body.string();
                if (text != null && !text.isEmpty())
                {
                    detail = ": " + text;
                }
            }
            catch (IOException ignored) {}
        }
        return new IOException(request.method() + " " + request.url() + " -> HTTP "
                + response.code() + " " + response.message() + detail);
    }
}

package com.rollbound.firebase;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.rollbound.RollBoundConfig;

/**
 * Shared gameplay rules for one RollBound Firebase database.
 *
 * Roll item sets, flatpacks, F2P mode/trade-only handling and poison unlock
 * requirements are intentionally hard-coded and are not remote-configurable.
 */
public final class FirebaseGameRules
{
    public static final int SCHEMA_VERSION = 2;

    private static final String LEGACY_FREE_TO_PLAY = "freeToPlay";
    private static final String LEGACY_INCLUDE_F2P_TRADE_ONLY = "includeF2PTradeOnlyItems";
    private static final String LEGACY_ENABLE_ITEM_SETS = "enableItemSets";
    private static final String LEGACY_ENABLE_FLATPACKS = "enableFlatpacks";
    private static final String LEGACY_REQUIRE_WEAPON_POISON = "requireWeaponPoison";

    public static final String REQUIRE_ROLLED_UNLOCKED_FOR_GE = "requireRolledUnlockedForGe";

    private final int schemaVersion;
    private final boolean requireRolledUnlockedForGe;
    private final long updatedAt;

    public FirebaseGameRules(int schemaVersion, boolean requireRolledUnlockedForGe, long updatedAt)
    {
        this.schemaVersion = schemaVersion;
        this.requireRolledUnlockedForGe = requireRolledUnlockedForGe;
        this.updatedAt = updatedAt;
    }

    public static FirebaseGameRules fromConfig(RollBoundConfig config)
    {
        return new FirebaseGameRules(
                SCHEMA_VERSION,
                config.requireRolledUnlockedForGe(),
                System.currentTimeMillis());
    }

    /** Parse remote rules while ignoring legacy rule fields from schema v1. */
    public static FirebaseGameRules fromJson(JsonElement element)
    {
        if (element == null || !element.isJsonObject())
        {
            return null;
        }

        JsonObject object = element.getAsJsonObject();
        return new FirebaseGameRules(
                readInt(object, "schemaVersion", SCHEMA_VERSION),
                readBoolean(object, REQUIRE_ROLLED_UNLOCKED_FOR_GE, true),
                readLong(object, "updatedAt", 0L));
    }

    public JsonObject toJson()
    {
        JsonObject object = new JsonObject();
        object.addProperty("schemaVersion", SCHEMA_VERSION);
        // Keep retired v1 keys explicitly false so older clients cannot interpret a missing key
        // as an enabled/default-on rule while a group upgrades. New RollBound clients ignore them.
        object.addProperty(LEGACY_FREE_TO_PLAY, false);
        object.addProperty(LEGACY_INCLUDE_F2P_TRADE_ONLY, false);
        object.addProperty(LEGACY_ENABLE_ITEM_SETS, false);
        object.addProperty(LEGACY_ENABLE_FLATPACKS, false);
        object.addProperty(LEGACY_REQUIRE_WEAPON_POISON, false);
        object.addProperty(REQUIRE_ROLLED_UNLOCKED_FOR_GE, requireRolledUnlockedForGe);
        object.addProperty("updatedAt", updatedAt);
        return object;
    }

    public static JsonObject legacyRulesOffPatch(JsonElement element)
    {
        JsonObject updates = new JsonObject();
        JsonObject current = element != null && element.isJsonObject()
                ? element.getAsJsonObject()
                : new JsonObject();

        addLegacyFalseIfNeeded(updates, current, LEGACY_FREE_TO_PLAY);
        addLegacyFalseIfNeeded(updates, current, LEGACY_INCLUDE_F2P_TRADE_ONLY);
        addLegacyFalseIfNeeded(updates, current, LEGACY_ENABLE_ITEM_SETS);
        addLegacyFalseIfNeeded(updates, current, LEGACY_ENABLE_FLATPACKS);
        addLegacyFalseIfNeeded(updates, current, LEGACY_REQUIRE_WEAPON_POISON);
        return updates;
    }

    private static void addLegacyFalseIfNeeded(JsonObject updates, JsonObject current, String key)
    {
        if (!current.has(key) || readBoolean(current, key, true))
        {
            updates.addProperty("gameRules/" + key, false);
        }
    }

    public static boolean isSharedKey(String key)
    {
        return REQUIRE_ROLLED_UNLOCKED_FOR_GE.equals(key);
    }

    public static boolean configValue(RollBoundConfig config, String key)
    {
        if (REQUIRE_ROLLED_UNLOCKED_FOR_GE.equals(key))
        {
            return config.requireRolledUnlockedForGe();
        }
        throw new IllegalArgumentException("Not a shared RollBound rule: " + key);
    }

    public boolean value(String key)
    {
        if (REQUIRE_ROLLED_UNLOCKED_FOR_GE.equals(key))
        {
            return requireRolledUnlockedForGe;
        }
        throw new IllegalArgumentException("Not a shared RollBound rule: " + key);
    }

    public int getSchemaVersion() { return schemaVersion; }
    public boolean isRequireRolledUnlockedForGe() { return requireRolledUnlockedForGe; }
    public long getUpdatedAt() { return updatedAt; }

    private static boolean readBoolean(JsonObject object, String key, boolean fallback)
    {
        try
        {
            JsonElement value = object.get(key);
            return value == null || value.isJsonNull() ? fallback : value.getAsBoolean();
        }
        catch (Exception ignored)
        {
            return fallback;
        }
    }

    private static int readInt(JsonObject object, String key, int fallback)
    {
        try
        {
            JsonElement value = object.get(key);
            return value == null || value.isJsonNull() ? fallback : value.getAsInt();
        }
        catch (Exception ignored)
        {
            return fallback;
        }
    }

    private static long readLong(JsonObject object, String key, long fallback)
    {
        try
        {
            JsonElement value = object.get(key);
            return value == null || value.isJsonNull() ? fallback : value.getAsLong();
        }
        catch (Exception ignored)
        {
            return fallback;
        }
    }
}

package com.rollbound.firebase;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/**
 * In-memory mirror of the Firebase root fed by REST streaming put/patch events.
 *
 * Keeping this mirror means realtime changes can be applied from the SSE payload itself instead of
 * issuing a second GET of the entire database after every event.
 */
final class FirebaseRealtimeState
{
    static final class ApplyResult
    {
        private final JsonObject snapshot;
        private final boolean rollBoundStateChanged;

        ApplyResult(JsonObject snapshot, boolean rollBoundStateChanged)
        {
            this.snapshot = snapshot;
            this.rollBoundStateChanged = rollBoundStateChanged;
        }

        JsonObject getSnapshot()
        {
            return snapshot;
        }

        boolean isRollBoundStateChanged()
        {
            return rollBoundStateChanged;
        }
    }

    private static final Set<String> ROLLBOUND_TOP_LEVEL_KEYS = new HashSet<>(Arrays.asList(
            "gameRules", "obtainedItems", "rolledItems", "rolledBy", "rollHistory", "liveRolls"));

    private final Gson gson;
    private JsonObject root = new JsonObject();
    private boolean initialised;

    FirebaseRealtimeState(Gson gson)
    {
        this.gson = gson;
    }

    synchronized void reset()
    {
        root = new JsonObject();
        initialised = false;
    }

    synchronized boolean isInitialised()
    {
        return initialised;
    }

    synchronized JsonObject snapshot()
    {
        return root.deepCopy();
    }

    synchronized ApplyResult apply(String eventType, String payload)
    {
        if (!"put".equals(eventType) && !"patch".equals(eventType))
        {
            throw new IllegalArgumentException("Unsupported Firebase event type: " + eventType);
        }

        JsonElement parsed = gson.fromJson(payload, JsonElement.class);
        if (parsed == null || !parsed.isJsonObject())
        {
            throw new IllegalArgumentException("Firebase stream payload is not an object");
        }

        JsonObject envelope = parsed.getAsJsonObject();
        JsonElement pathElement = envelope.get("path");
        String path = pathElement == null || pathElement.isJsonNull() ? "/" : pathElement.getAsString();
        JsonElement data = envelope.has("data") ? envelope.get("data") : JsonNull.INSTANCE;

        boolean relevant;
        if ("put".equals(eventType))
        {
            relevant = putAffectsRollBoundState(path);
            applyPut(path, data);
        }
        else
        {
            relevant = patchAffectsRollBoundState(path, data);
            applyPatch(path, data);
        }

        initialised = true;
        return new ApplyResult(relevant ? root.deepCopy() : null, relevant);
    }

    private void applyPatch(String basePath, JsonElement data)
    {
        if (data == null || data.isJsonNull())
        {
            return;
        }
        if (!data.isJsonObject())
        {
            // Firebase patch payloads are objects. Treat an unexpected scalar defensively as a put.
            applyPut(basePath, data);
            return;
        }

        for (Map.Entry<String, JsonElement> entry : data.getAsJsonObject().entrySet())
        {
            applyPut(joinPath(basePath, entry.getKey()), entry.getValue());
        }
    }

    private void applyPut(String path, JsonElement data)
    {
        String[] parts = pathParts(path);
        if (parts.length == 0)
        {
            if (data != null && data.isJsonObject())
            {
                root = data.getAsJsonObject().deepCopy();
            }
            else
            {
                // RTDB root for RollBound is object-shaped. A null/scalar root means no usable state.
                root = new JsonObject();
            }
            return;
        }

        JsonObject node = root;
        for (int i = 0; i < parts.length - 1; i++)
        {
            String key = parts[i];
            JsonElement existing = node.get(key);
            if (existing == null || !existing.isJsonObject())
            {
                JsonObject child = new JsonObject();
                node.add(key, child);
                node = child;
            }
            else
            {
                node = existing.getAsJsonObject();
            }
        }

        String key = parts[parts.length - 1];
        if (data == null || data.isJsonNull())
        {
            node.remove(key);
        }
        else
        {
            node.add(key, data.deepCopy());
        }
    }

    private boolean putAffectsRollBoundState(String path)
    {
        String[] parts = pathParts(path);
        return parts.length == 0 || ROLLBOUND_TOP_LEVEL_KEYS.contains(parts[0]);
    }

    private boolean patchAffectsRollBoundState(String path, JsonElement data)
    {
        String[] base = pathParts(path);
        if (base.length > 0)
        {
            return ROLLBOUND_TOP_LEVEL_KEYS.contains(base[0]);
        }
        if (data == null || !data.isJsonObject())
        {
            return true;
        }
        for (String relative : data.getAsJsonObject().keySet())
        {
            String[] parts = pathParts(relative);
            if (parts.length == 0 || ROLLBOUND_TOP_LEVEL_KEYS.contains(parts[0]))
            {
                return true;
            }
        }
        return false;
    }

    private static String joinPath(String basePath, String relativePath)
    {
        String base = basePath == null ? "" : basePath.trim();
        String relative = relativePath == null ? "" : relativePath.trim();
        if (base.isEmpty() || "/".equals(base))
        {
            return "/" + stripLeadingSlash(relative);
        }
        if (relative.isEmpty())
        {
            return base;
        }
        return stripTrailingSlash(base) + "/" + stripLeadingSlash(relative);
    }

    private static String[] pathParts(String path)
    {
        if (path == null || path.trim().isEmpty() || "/".equals(path.trim()))
        {
            return new String[0];
        }
        String clean = path.trim();
        clean = stripLeadingSlash(clean);
        clean = stripTrailingSlash(clean);
        if (clean.isEmpty())
        {
            return new String[0];
        }
        return clean.split("/+");
    }

    private static String stripLeadingSlash(String value)
    {
        String result = value == null ? "" : value;
        while (result.startsWith("/"))
        {
            result = result.substring(1);
        }
        return result;
    }

    private static String stripTrailingSlash(String value)
    {
        String result = value == null ? "" : value;
        while (result.endsWith("/") && !result.isEmpty())
        {
            result = result.substring(0, result.length() - 1);
        }
        return result;
    }
}

package com.rollbound.firebase;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** A live group roll persisted briefly in Firebase so every connected client can animate it. */
public final class FirebaseRollEvent
{
    private String eventId;
    private long createdAt;
    private String rollerName;
    private int obtainedItemId;
    private boolean manual;
    private List<Integer> options;
    private int chosenItemId;
    private long pickedAt;

    // Ordered-batch metadata. Legacy events simply omit these fields.
    private String batchId;
    private int sequence;
    private int batchSize;

    public FirebaseRollEvent() {}

    /** Backwards-compatible constructor for legacy/single roll callers. */
    public FirebaseRollEvent(String eventId, long createdAt, String rollerName, int obtainedItemId,
                             boolean manual, List<Integer> options)
    {
        this(eventId, createdAt, rollerName, obtainedItemId, manual, options,
                null, 0, 1, 0, 0L);
    }

    /** Creates a roll that belongs to an explicitly ordered simultaneous-roll batch. */
    public FirebaseRollEvent(String eventId, long createdAt, String rollerName, int obtainedItemId,
                             boolean manual, List<Integer> options,
                             String batchId, int sequence, int batchSize)
    {
        this(eventId, createdAt, rollerName, obtainedItemId, manual, options,
                batchId, sequence, batchSize, 0, 0L);
    }

    private FirebaseRollEvent(String eventId, long createdAt, String rollerName, int obtainedItemId,
                              boolean manual, List<Integer> options,
                              String batchId, int sequence, int batchSize,
                              int chosenItemId, long pickedAt)
    {
        this.eventId = eventId;
        this.createdAt = createdAt;
        this.rollerName = rollerName;
        this.obtainedItemId = obtainedItemId;
        this.manual = manual;
        this.options = options == null ? Collections.emptyList() : new ArrayList<>(options);
        this.batchId = batchId;
        this.sequence = Math.max(0, sequence);
        this.batchSize = Math.max(1, batchSize);
        this.chosenItemId = chosenItemId;
        this.pickedAt = pickedAt;
    }

    public FirebaseRollEvent withPick(int chosenItemId, long pickedAt)
    {
        return new FirebaseRollEvent(eventId, createdAt, rollerName, obtainedItemId, manual, options,
                batchId, sequence, batchSize, chosenItemId, pickedAt);
    }

    /**
     * Stable playback ordering shared by Firebase reconstruction and local animation queues.
     *
     * New simultaneous rolls share createdAt + batchId and are ordered by sequence. Legacy events
     * have no batchId, so eventId provides a deterministic tie-breaker when timestamps match.
     */
    public static int compareForPlayback(FirebaseRollEvent left, FirebaseRollEvent right)
    {
        if (left == right) return 0;
        if (left == null) return 1;
        if (right == null) return -1;

        int byTime = Long.compare(left.getCreatedAt(), right.getCreatedAt());
        if (byTime != 0) return byTime;

        String leftGroup = left.orderingGroupId();
        String rightGroup = right.orderingGroupId();
        int byGroup = leftGroup.compareTo(rightGroup);
        if (byGroup != 0) return byGroup;

        int bySequence = Integer.compare(left.getSequence(), right.getSequence());
        if (bySequence != 0) return bySequence;

        return safe(left.getEventId()).compareTo(safe(right.getEventId()));
    }

    private String orderingGroupId()
    {
        return isBlank(batchId) ? safe(eventId) : batchId;
    }

    private static String safe(String value)
    {
        return value == null ? "" : value;
    }

    private static boolean isBlank(String value)
    {
        return value == null || value.trim().isEmpty();
    }

    public String getEventId() { return eventId; }
    public long getCreatedAt() { return createdAt; }
    public String getRollerName() { return rollerName; }
    public int getObtainedItemId() { return obtainedItemId; }
    public boolean isManual() { return manual; }
    public List<Integer> getOptions()
    {
        return options == null ? Collections.emptyList() : Collections.unmodifiableList(options);
    }
    public int getChosenItemId() { return chosenItemId; }
    public long getPickedAt() { return pickedAt; }
    public String getBatchId() { return batchId; }
    public int getSequence() { return Math.max(0, sequence); }
    public int getBatchSize() { return batchSize > 0 ? batchSize : 1; }
}

package com.rollbound.firebase;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import okhttp3.Call;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;

/** Maintains Firebase's Server-Sent Events stream and forwards put/patch payloads. */
final class FirebaseSseStream
{
    interface EventListener
    {
        void onEvent(String eventType, String data);
    }

    private static final Logger log = LoggerFactory.getLogger(FirebaseSseStream.class);
    private final OkHttpClient client;
    private final String streamUrl;
    private final EventListener eventListener;
    private final Runnable connectedListener;
    private final Runnable disconnectedListener;

    volatile boolean running;
    private volatile Call currentCall;
    private volatile int backoffSeconds = 1;
    private ScheduledExecutorService executor;
    private ScheduledFuture<?> reconnectFuture;

    FirebaseSseStream(OkHttpClient httpClient, String streamUrl, EventListener eventListener,
                      Runnable connectedListener, Runnable disconnectedListener)
    {
        this.client = httpClient.newBuilder()
                .retryOnConnectionFailure(true)
                .readTimeout(90, TimeUnit.SECONDS)
                .build();
        this.streamUrl = streamUrl;
        this.eventListener = eventListener;
        this.connectedListener = connectedListener;
        this.disconnectedListener = disconnectedListener;
    }

    synchronized void start()
    {
        if (running)
        {
            return;
        }

        running = true;
        backoffSeconds = 1;
        executor = Executors.newSingleThreadScheduledExecutor(r ->
        {
            Thread thread = new Thread(r, "RollBound-Firebase-SSE");
            thread.setDaemon(true);
            return thread;
        });
        executor.execute(this::connectOnce);
    }

    synchronized void stop()
    {
        running = false;
        Call call = currentCall;
        if (call != null)
        {
            call.cancel();
        }
        ScheduledFuture<?> reconnect = reconnectFuture;
        reconnectFuture = null;
        if (reconnect != null)
        {
            reconnect.cancel(false);
        }
        if (executor != null)
        {
            executor.shutdownNow();
            executor = null;
        }
    }

    /**
     * Perform one blocking SSE connection on the dedicated SSE worker. A disconnect schedules
     * the next attempt instead of sleeping the worker thread, which keeps shutdown immediate.
     */
    private void connectOnce()
    {
        if (!running)
        {
            return;
        }

        Request request = new Request.Builder()
                .url(streamUrl)
                .header("User-Agent", FirebaseDatabaseClient.USER_AGENT)
                .header("Accept", "text/event-stream")
                .header("Cache-Control", "no-cache")
                .build();

        boolean connected = false;
        try
        {
            currentCall = client.newCall(request);
            try (Response response = currentCall.execute())
            {
                if (!response.isSuccessful())
                {
                    throw new IllegalStateException("Firebase stream HTTP " + response.code());
                }

                connected = true;
                backoffSeconds = 1;
                if (connectedListener != null)
                {
                    connectedListener.run();
                }

                ResponseBody body = response.body();
                if (body == null)
                {
                    throw new IllegalStateException("Firebase stream returned no body");
                }

                try (BufferedReader reader = new BufferedReader(new InputStreamReader(body.byteStream())))
                {
                    readEvents(reader);
                }
            }
        }
        catch (Exception error)
        {
            if (running)
            {
                log.warn("Firebase realtime stream disconnected; retrying", error);
            }
        }
        finally
        {
            currentCall = null;
            if (connected && disconnectedListener != null)
            {
                disconnectedListener.run();
            }
        }

        scheduleReconnect();
    }

    private void scheduleReconnect()
    {
        ScheduledExecutorService current = executor;
        if (!running || current == null || current.isShutdown())
        {
            return;
        }

        int delayBase = backoffSeconds;
        backoffSeconds = Math.min(backoffSeconds * 2, 30);
        long delayMs = delayBase * 1000L + ThreadLocalRandom.current().nextLong(250L, 1000L);
        reconnectFuture = current.schedule(this::connectOnce, delayMs, TimeUnit.MILLISECONDS);
    }

    /**
     * Parse SSE according to the event framing rules. Firebase normally emits one JSON data line,
     * but joining repeated data fields keeps this correct if a proxy/server ever splits a payload.
     */
    void readEvents(BufferedReader reader) throws Exception
    {
        String eventType = null;
        StringBuilder data = new StringBuilder();
        String line;
        while (running && (line = reader.readLine()) != null)
        {
            if (line.isEmpty())
            {
                dispatchEvent(eventType, data);
                eventType = null;
                data.setLength(0);
                continue;
            }
            if (line.startsWith(":"))
            {
                continue;
            }
            if (line.startsWith("event:"))
            {
                eventType = line.substring("event:".length()).trim();
                continue;
            }
            if (line.startsWith("data:"))
            {
                if (data.length() > 0)
                {
                    data.append('\n');
                }
                String value = line.substring("data:".length());
                if (value.startsWith(" "))
                {
                    value = value.substring(1);
                }
                data.append(value);
            }
        }

        dispatchEvent(eventType, data);
    }

    private void dispatchEvent(String eventType, StringBuilder data)
    {
        if (eventType == null || "keep-alive".equals(eventType))
        {
            return;
        }
        if ("cancel".equals(eventType) || "auth_revoked".equals(eventType))
        {
            throw new IllegalStateException("Firebase stream event: " + eventType);
        }
        if (("put".equals(eventType) || "patch".equals(eventType)) && eventListener != null)
        {
            eventListener.onEvent(eventType, data.toString());
        }
    }
}

package com.rollbound.firebase;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.rollbound.RollBoundConfig;
import com.rollbound.backup.LocalBackupManager;
import net.runelite.client.config.ConfigManager;
import com.rollbound.managers.ObtainedItemsManager;
import com.rollbound.managers.RollHistoryManager;
import com.rollbound.managers.RolledByManager;
import com.rollbound.managers.RolledItemsManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * Firebase is RollBound's single shared source of truth.
 *
 * Persistent state:
 *   /obtainedItems/{itemId} = recorded epoch millis
 *   /rolledItems/{itemId} = unlock epoch millis
 *   /rolledBy/{itemId} = { by, at }
 *   /rollHistory/{eventId} = RollEvent
 *
 * Short-lived live animation state:
 *   /liveRolls/{eventId} = FirebaseRollEvent
 *
 * The REST API performs idempotent writes while an SSE stream tells every connected
 * RuneLite client to refresh immediately when another player changes the database.
 */
@Singleton
public final class FirebaseSyncService
{
    private static final Logger log = LoggerFactory.getLogger(FirebaseSyncService.class);
    public enum Status
    {
        NOT_CONFIGURED,
        CONNECTING,
        CONNECTED,
        ERROR
    }

    public interface RollListener
    {
        void onRollStarted(FirebaseRollEvent event);
        void onRollPicked(FirebaseRollEvent event);
    }

    private static final int SCHEMA_VERSION = 1;
    private static final long LIVE_EVENT_MAX_AGE_MS = TimeUnit.MINUTES.toMillis(2);
    private static final long LIVE_EVENT_DELETE_DELAY_SECONDS = 90L;
    private static final long REFRESH_DEBOUNCE_MS = 100L;
    private static final int MAX_SEEN_LIVE_EVENTS = 1000;

    private final FirebaseDatabaseClient databaseClient;
    private final Gson gson;
    private final RollBoundConfig config;
    private final ConfigManager configManager;
    private final ObtainedItemsManager obtainedItemsManager;
    private final RolledItemsManager rolledItemsManager;
    private final RolledByManager rolledByManager;
    private final RollHistoryManager rollHistoryManager;
    private final LocalBackupManager localBackupManager;

    private final Set<String> observedStarts = Collections.newSetFromMap(new ConcurrentHashMap<>());
    private final Set<String> observedPicks = Collections.newSetFromMap(new ConcurrentHashMap<>());
    private final Map<String, Boolean> pendingRuleWrites = new ConcurrentHashMap<>();
    private final AtomicBoolean refreshQueued = new AtomicBoolean(false);
    private final Set<ScheduledFuture<?>> scheduledTasks = ConcurrentHashMap.newKeySet();
    private final FirebaseRealtimeState realtimeState;

    private volatile Status status = Status.NOT_CONFIGURED;
    private volatile String lastError;
    private volatile String activeDatabaseUrl;
    private volatile boolean running;
    private volatile long generation;

    private volatile ScheduledExecutorService executor;
    private volatile FirebaseSseStream stream;
    private volatile RollListener rollListener;
    private volatile Runnable statusListener;
    private volatile FirebaseGameRules gameRules;

    @Inject
    public FirebaseSyncService(
            FirebaseDatabaseClient databaseClient,
            Gson gson,
            RollBoundConfig config,
            ConfigManager configManager,
            ObtainedItemsManager obtainedItemsManager,
            RolledItemsManager rolledItemsManager,
            RolledByManager rolledByManager,
            RollHistoryManager rollHistoryManager,
            LocalBackupManager localBackupManager)
    {
        this.databaseClient = databaseClient;
        this.gson = gson;
        this.config = config;
        this.configManager = configManager;
        this.obtainedItemsManager = obtainedItemsManager;
        this.rolledItemsManager = rolledItemsManager;
        this.rolledByManager = rolledByManager;
        this.rollHistoryManager = rollHistoryManager;
        this.localBackupManager = localBackupManager;
        this.realtimeState = new FirebaseRealtimeState(gson);
    }

    public synchronized void setRollListener(RollListener rollListener)
    {
        this.rollListener = rollListener;
    }

    public synchronized void setStatusListener(Runnable statusListener)
    {
        this.statusListener = statusListener;
    }

    public Status getStatus()
    {
        return status;
    }

    public String getLastError()
    {
        return lastError;
    }

    public String getActiveDatabaseUrl()
    {
        return activeDatabaseUrl;
    }

    public boolean isConfigured()
    {
        return databaseClient.normaliseDatabaseUrl(config.firebaseDatabaseUrl()) != null;
    }

    public synchronized void start()
    {
        // Reset backup de-duplication. The first authoritative snapshot becomes the baseline.
        localBackupManager.resetSession();
        // Never show or act on state from a previously configured database while reconnecting.
        stopInternal(true);

        String databaseUrl = databaseClient.normaliseDatabaseUrl(config.firebaseDatabaseUrl());
        activeDatabaseUrl = databaseUrl;
        generation++;
        long currentGeneration = generation;

        if (databaseUrl == null)
        {
            running = false;
            clearSharedState();
            setStatus(Status.NOT_CONFIGURED, null);
            return;
        }

        running = true;
        executor = Executors.newSingleThreadScheduledExecutor(r -> {
            Thread thread = new Thread(r, "RollBound-Firebase-Sync");
            thread.setDaemon(true);
            return thread;
        });

        setStatus(Status.CONNECTING, null);

        // The root SSE subscription sends an initial put containing the current database state,
        // followed by put/patch deltas. Apply those payloads directly instead of performing a
        // second GET of /.json for every event. Reconnecting the stream naturally delivers a
        // fresh initial root put, so no periodic full-state polling is required.
        stream = databaseClient.stream(
                databaseUrl,
                (eventType, payload) -> handleStreamEvent(currentGeneration, eventType, payload),
                () -> {
                    if (running && generation == currentGeneration && status != Status.CONNECTED)
                    {
                        setStatus(Status.CONNECTING, null);
                    }
                },
                () -> {
                    if (running && generation == currentGeneration && status == Status.CONNECTED)
                    {
                        setStatus(Status.CONNECTING, null);
                    }
                });
        stream.start();
    }

    public synchronized void restart()
    {
        start();
    }

    public synchronized void stop()
    {
        stopInternal(false);
        setStatus(Status.NOT_CONFIGURED, null);
    }

    private synchronized void stopInternal(boolean clearState)
    {
        running = false;
        generation++;
        refreshQueued.set(false);

        if (stream != null)
        {
            stream.stop();
            stream = null;
        }
        cancelScheduledTasks();
        if (executor != null)
        {
            executor.shutdownNow();
            executor = null;
        }

        observedStarts.clear();
        observedPicks.clear();
        pendingRuleWrites.clear();
        gameRules = null;
        realtimeState.reset();
        activeDatabaseUrl = null;

        if (clearState)
        {
            clearSharedState();
        }
    }

    /**
     * Re-apply the latest in-memory realtime snapshot. This is intentionally local-only: the SSE
     * stream is authoritative and automatically sends a full root snapshot on (re)connect.
     */
    public void requestRefresh()
    {
        ScheduledExecutorService current = executor;
        long currentGeneration = generation;
        if (!running || current == null || current.isShutdown() || !realtimeState.isInitialised())
        {
            return;
        }
        if (!refreshQueued.compareAndSet(false, true))
        {
            return;
        }

        schedule(current, () -> {
            refreshQueued.set(false);
            if (!running || currentGeneration != generation)
            {
                return;
            }
            try
            {
                applySnapshot(realtimeState.snapshot());
            }
            catch (Exception error)
            {
                log.error("Failed to re-apply cached Firebase RollBound state", error);
                setStatus(Status.ERROR, "Invalid database data");
            }
        }, REFRESH_DEBOUNCE_MS, TimeUnit.MILLISECONDS);
    }


    /**
     * Publish one gameplay-affecting RuneLite config value as a shared Firebase rule.
     * Remote rule application updates the cached snapshot before ConfigManager, so echoed
     * ConfigChanged events are ignored instead of causing write loops.
     */
    public void publishGameRule(String key)
    {
        if (!FirebaseGameRules.isSharedKey(key))
        {
            return;
        }

        boolean value = FirebaseGameRules.configValue(config, key);
        FirebaseGameRules currentRules = gameRules;
        if (currentRules != null && currentRules.value(key) == value)
        {
            return;
        }

        pendingRuleWrites.put(key, value);

        JsonObject updates = new JsonObject();
        updates.addProperty("gameRules/schemaVersion", FirebaseGameRules.SCHEMA_VERSION);
        updates.addProperty("gameRules/" + key, value);
        updates.addProperty("gameRules/updatedAt", System.currentTimeMillis());
        submitPersistentPatch("shared game rule " + key, updates, generation, 0);
    }

    /** Persist an obtained trigger item immediately. Safe to retry because the write is idempotent. */
    public void publishObtained(int itemId)
    {
        if (itemId <= 0)
        {
            return;
        }
        JsonObject updates = new JsonObject();
        updates.addProperty("schemaVersion", SCHEMA_VERSION);
        updates.addProperty("obtainedItems/" + itemId, System.currentTimeMillis());
        submitPersistentPatch("obtained item " + itemId, updates, generation, 0);
    }

    /** Publish one live roll. Kept for compatibility; ordered batches use publishRollStarts. */
    public void publishRollStart(FirebaseRollEvent event)
    {
        if (event == null)
        {
            return;
        }
        publishRollStarts(Collections.singletonList(event));
    }

    /**
     * Publish every start event from one simultaneous roll batch in a single Firebase PATCH.
     *
     * Teammates therefore observe the complete batch and reconstruct the same sequence instead of
     * relying on the order in which independent network requests happen to arrive.
     */
    public void publishRollStarts(Collection<FirebaseRollEvent> events)
    {
        if (events == null || events.isEmpty() || !running || activeDatabaseUrl == null)
        {
            return;
        }

        JsonObject updates = new JsonObject();
        updates.addProperty("schemaVersion", SCHEMA_VERSION);
        int validEvents = 0;
        for (FirebaseRollEvent event : events)
        {
            if (event == null || isBlank(event.getEventId()))
            {
                continue;
            }
            if (event.getObtainedItemId() > 0)
            {
                updates.addProperty("obtainedItems/" + event.getObtainedItemId(), event.getCreatedAt());
            }
            updates.add("liveRolls/" + event.getEventId(), gson.toJsonTree(event));
            validEvents++;
        }
        if (validEvents == 0)
        {
            return;
        }

        final int publishedCount = validEvents;
        databaseClient.patch(activeDatabaseUrl, "/", updates).whenComplete((ignored, error) -> {
            if (error != null && running)
            {
                log.warn("Could not publish RollBound roll batch ({} events)", publishedCount, error);
            }
        });
    }

    /** Persist several obtained items together when no rolls remain to be generated. */
    public void publishObtainedBatch(Collection<Integer> itemIds, long recordedAt)
    {
        if (itemIds == null || itemIds.isEmpty() || !running || activeDatabaseUrl == null)
        {
            return;
        }

        long at = recordedAt > 0 ? recordedAt : System.currentTimeMillis();
        JsonObject updates = new JsonObject();
        updates.addProperty("schemaVersion", SCHEMA_VERSION);
        int count = 0;
        for (Integer itemId : itemIds)
        {
            if (itemId == null || itemId <= 0)
            {
                continue;
            }
            updates.addProperty("obtainedItems/" + itemId, at);
            count++;
        }
        if (count == 0)
        {
            return;
        }
        submitPersistentPatch("obtained item batch", updates, generation, 0);
    }

    /**
     * Atomically publish the final result and all shared state affected by it.
     * A multi-location Firebase PATCH prevents one player from overwriting another player's progress.
     */
    public void publishRollPick(FirebaseRollEvent startEvent, int chosenItemId, long pickedAt)
    {
        if (startEvent == null || isBlank(startEvent.getEventId()) || chosenItemId <= 0)
        {
            return;
        }

        long at = pickedAt > 0 ? pickedAt : System.currentTimeMillis();
        String roller = normalisePlayerName(startEvent.getRollerName());

        FirebaseRollEvent completed = new FirebaseRollEvent(
                startEvent.getEventId(),
                startEvent.getCreatedAt(),
                roller,
                startEvent.getObtainedItemId(),
                startEvent.isManual(),
                startEvent.getOptions(),
                startEvent.getBatchId(),
                startEvent.getSequence(),
                startEvent.getBatchSize()).withPick(chosenItemId, at);
        JsonObject liveJson = gson.toJsonTree(completed).getAsJsonObject();

        RollHistoryManager.RollEvent historyEvent = new RollHistoryManager.RollEvent(
                startEvent.getEventId(), at, roller,
                startEvent.getObtainedItemId(), chosenItemId, startEvent.isManual());
        RolledByManager.RolledByEntry rolledByEntry = new RolledByManager.RolledByEntry(roller, at);

        JsonObject updates = new JsonObject();
        updates.addProperty("schemaVersion", SCHEMA_VERSION);
        if (startEvent.getObtainedItemId() > 0)
        {
            updates.addProperty("obtainedItems/" + startEvent.getObtainedItemId(), startEvent.getCreatedAt());
        }
        updates.addProperty("rolledItems/" + chosenItemId, at);
        updates.add("rolledBy/" + chosenItemId, gson.toJsonTree(rolledByEntry));
        updates.add("rollHistory/" + startEvent.getEventId(), gson.toJsonTree(historyEvent));
        updates.add("liveRolls/" + startEvent.getEventId(), liveJson);

        long writeGeneration = generation;
        submitPersistentPatch("roll result " + startEvent.getEventId(), updates, writeGeneration, 0);

        ScheduledExecutorService current = executor;
        if (current != null && !current.isShutdown())
        {
            schedule(current, () -> deleteLiveRoll(startEvent.getEventId(), writeGeneration),
                    LIVE_EVENT_DELETE_DELAY_SECONDS, TimeUnit.SECONDS);
        }
    }

    private void handleStreamEvent(long expectedGeneration, String eventType, String payload)
    {
        ScheduledExecutorService current = executor;
        if (!running || expectedGeneration != generation || current == null || current.isShutdown())
        {
            return;
        }

        // Serialise state-cache mutation and manager updates on the Firebase sync executor.
        current.execute(() -> {
            if (!running || expectedGeneration != generation)
            {
                return;
            }
            try
            {
                FirebaseRealtimeState.ApplyResult result = realtimeState.apply(eventType, payload);
                if (result.isRollBoundStateChanged())
                {
                    applySnapshot(result.getSnapshot());
                }
                setStatus(Status.CONNECTED, null);
            }
            catch (Exception parseError)
            {
                log.error("Failed to apply Firebase realtime event", parseError);
                setStatus(Status.ERROR, "Invalid realtime database data");
            }
        });
    }

    private void applySnapshot(JsonElement rootElement)
    {
        JsonObject root = rootElement != null && rootElement.isJsonObject()
                ? rootElement.getAsJsonObject()
                : new JsonObject();

        synchroniseGameRules(root.get("gameRules"));

        obtainedItemsManager.replaceAll(readItemSet(root.get("obtainedItems")));
        rolledItemsManager.replaceAll(readItemSet(root.get("rolledItems")));
        rolledByManager.replaceAll(readRolledBy(root.get("rolledBy")));
        rollHistoryManager.replaceAll(readRollHistory(root.get("rollHistory")));

        // First snapshot establishes the local backup baseline. Later unseen history events
        // create one complete backup per roll after all four managers are in sync.
        localBackupManager.onAuthoritativeSnapshotApplied(rollHistoryManager.getSnapshot());

        processLiveRolls(root.get("liveRolls"));
        // Fallback: if a client saw the live start but missed the short-lived live pick update,
        // the persistent roll-history record still resolves the on-screen choice.
        processResolvedHistory(root.get("rollHistory"));
        pruneRemoteHistory(root.get("rollHistory"));
    }


    private void synchroniseGameRules(JsonElement element)
    {
        FirebaseGameRules remote = FirebaseGameRules.fromJson(element);
        if (remote == null)
        {
            // First RollBound client on a new database defines the group's initial rules.
            FirebaseGameRules initial = FirebaseGameRules.fromConfig(config);
            gameRules = initial;
            JsonObject updates = new JsonObject();
            updates.add("gameRules", initial.toJson());
            submitPersistentPatch("initial shared game rules", updates, generation, 0);
            return;
        }

        gameRules = remote;

        JsonObject legacyRuleReset = FirebaseGameRules.legacyRulesOffPatch(element);
        if (legacyRuleReset.size() > 0)
        {
            legacyRuleReset.addProperty("gameRules/schemaVersion", FirebaseGameRules.SCHEMA_VERSION);
            legacyRuleReset.addProperty("gameRules/updatedAt", System.currentTimeMillis());
            submitPersistentPatch("retired shared game rules", legacyRuleReset, generation, 0);
        }

        applyRemoteRuleUnlessPending(FirebaseGameRules.REQUIRE_ROLLED_UNLOCKED_FOR_GE,
                remote.isRequireRolledUnlockedForGe());
    }

    private void applyRemoteRuleUnlessPending(String key, boolean remoteValue)
    {
        Boolean pendingValue = pendingRuleWrites.get(key);
        if (pendingValue != null)
        {
            if (pendingValue == remoteValue)
            {
                pendingRuleWrites.remove(key, pendingValue);
            }
            else
            {
                // A GET that started before our write completed can contain the old value.
                // Keep the user's local choice until Firebase reflects the pending write.
                return;
            }
        }
        applyRemoteRule(key, remoteValue);
    }

    private void applyRemoteRule(String key, boolean value)
    {
        try
        {
            if (FirebaseGameRules.configValue(config, key) != value)
            {
                // Updating ConfigManager also updates RuneLite's settings UI and emits ConfigChanged,
                // so the normal local refresh path is reused on every client.
                configManager.setConfiguration("rollbound", key, value);
            }
        }
        catch (Exception error)
        {
            log.warn("Could not apply shared RollBound rule {}", key, error);
        }
    }

    private Set<Integer> readItemSet(JsonElement element)
    {
        class TimedItem
        {
            final int id;
            final long at;
            TimedItem(int id, long at) { this.id = id; this.at = at; }
        }

        List<TimedItem> items = new ArrayList<>();
        if (element == null || !element.isJsonObject())
        {
            return new LinkedHashSet<>();
        }

        for (Map.Entry<String, JsonElement> entry : element.getAsJsonObject().entrySet())
        {
            try
            {
                int id = Integer.parseInt(entry.getKey());
                if (id <= 0 || entry.getValue() == null || entry.getValue().isJsonNull())
                {
                    continue;
                }

                JsonElement value = entry.getValue();
                long timestamp = 0L;
                boolean present = true;
                if (value.isJsonPrimitive())
                {
                    if (value.getAsJsonPrimitive().isBoolean())
                    {
                        present = value.getAsBoolean();
                    }
                    else if (value.getAsJsonPrimitive().isNumber())
                    {
                        timestamp = value.getAsLong();
                    }
                }
                if (present)
                {
                    items.add(new TimedItem(id, timestamp));
                }
            }
            catch (Exception ignored) {}
        }

        items.sort(Comparator.comparingLong((TimedItem item) -> item.at).thenComparingInt(item -> item.id));
        Set<Integer> ids = new LinkedHashSet<>();
        for (TimedItem item : items)
        {
            ids.add(item.id);
        }
        return ids;
    }

    private Map<Integer, RolledByManager.RolledByEntry> readRolledBy(JsonElement element)
    {
        Map<Integer, RolledByManager.RolledByEntry> entries = new HashMap<>();
        if (element == null || !element.isJsonObject())
        {
            return entries;
        }
        for (Map.Entry<String, JsonElement> entry : element.getAsJsonObject().entrySet())
        {
            try
            {
                int id = Integer.parseInt(entry.getKey());
                RolledByManager.RolledByEntry value = gson.fromJson(entry.getValue(), RolledByManager.RolledByEntry.class);
                if (id > 0 && value != null)
                {
                    entries.put(id, value);
                }
            }
            catch (Exception ignored) {}
        }
        return entries;
    }

    private Collection<RollHistoryManager.RollEvent> readRollHistory(JsonElement element)
    {
        List<RollHistoryManager.RollEvent> events = new ArrayList<>();
        if (element == null || !element.isJsonObject())
        {
            return events;
        }
        for (Map.Entry<String, JsonElement> entry : element.getAsJsonObject().entrySet())
        {
            try
            {
                RollHistoryManager.RollEvent event = gson.fromJson(entry.getValue(), RollHistoryManager.RollEvent.class);
                if (event != null && event.getEventId() != null && event.getRolledItemId() > 0)
                {
                    events.add(event);
                }
            }
            catch (Exception ignored) {}
        }
        events.sort(Comparator.comparingLong(RollHistoryManager.RollEvent::getAt));
        if (events.size() > RollHistoryManager.MAX_EVENTS)
        {
            return new ArrayList<>(events.subList(events.size() - RollHistoryManager.MAX_EVENTS, events.size()));
        }
        return events;
    }

    private void processLiveRolls(JsonElement element)
    {
        if (element == null || !element.isJsonObject())
        {
            return;
        }

        List<FirebaseRollEvent> events = new ArrayList<>();
        for (Map.Entry<String, JsonElement> entry : element.getAsJsonObject().entrySet())
        {
            try
            {
                FirebaseRollEvent event = gson.fromJson(entry.getValue(), FirebaseRollEvent.class);
                if (event != null && !isBlank(event.getEventId()))
                {
                    events.add(event);
                }
            }
            catch (Exception ignored) {}
        }
        events.sort(FirebaseRollEvent::compareForPlayback);

        long now = System.currentTimeMillis();
        RollListener listener = rollListener;
        for (FirebaseRollEvent event : events)
        {
            boolean recent = event.getCreatedAt() > 0 && now - event.getCreatedAt() <= LIVE_EVENT_MAX_AGE_MS;
            String id = event.getEventId();

            if (event.getChosenItemId() <= 0)
            {
                if (recent && remember(observedStarts, id) && listener != null)
                {
                    listener.onRollStarted(event);
                }
                else if (!recent)
                {
                    deleteLiveRoll(id, generation);
                }
                continue;
            }

            // A client can miss the short-lived start update and first observe the completed event.
            // Reconstruct the animation from the completed payload, then deliver the pick. The overlay
            // queues early picks until this event reaches the front of its local animation queue.
            if (recent && listener != null && !observedStarts.contains(id) && remember(observedStarts, id))
            {
                listener.onRollStarted(event);
            }
            if (recent && remember(observedPicks, id) && listener != null)
            {
                listener.onRollPicked(event);
            }
            else if (!recent)
            {
                remember(observedPicks, id);
            }

            long pickedAt = event.getPickedAt();
            if (pickedAt > 0 && now - pickedAt > LIVE_EVENT_MAX_AGE_MS)
            {
                deleteLiveRoll(id, generation);
            }
        }
    }

    private void processResolvedHistory(JsonElement element)
    {
        if (element == null || !element.isJsonObject())
        {
            return;
        }

        RollListener listener = rollListener;
        if (listener == null)
        {
            return;
        }

        long now = System.currentTimeMillis();
        for (Map.Entry<String, JsonElement> entry : element.getAsJsonObject().entrySet())
        {
            String id = entry.getKey();
            if (!observedStarts.contains(id) || observedPicks.contains(id))
            {
                continue;
            }

            try
            {
                RollHistoryManager.RollEvent history = gson.fromJson(entry.getValue(), RollHistoryManager.RollEvent.class);
                if (history == null || history.getRolledItemId() <= 0)
                {
                    continue;
                }
                // Only use recent history as a live-UI recovery path. Old history must never replay.
                if (history.getAt() <= 0 || now - history.getAt() > LIVE_EVENT_MAX_AGE_MS)
                {
                    continue;
                }
                if (!remember(observedPicks, id))
                {
                    continue;
                }

                FirebaseRollEvent resolved = new FirebaseRollEvent(
                        id,
                        history.getAt(),
                        history.getBy(),
                        history.getObtainedItemId(),
                        history.isManual(),
                        Collections.emptyList())
                        .withPick(history.getRolledItemId(), history.getAt());
                listener.onRollPicked(resolved);
            }
            catch (Exception ignored) {}
        }
    }

    private void pruneRemoteHistory(JsonElement element)
    {
        if (element == null || !element.isJsonObject())
        {
            return;
        }

        class HistoryKey
        {
            final String id;
            final long at;

            HistoryKey(String id, long at)
            {
                this.id = id;
                this.at = at;
            }
        }

        List<HistoryKey> history = new ArrayList<>();
        for (Map.Entry<String, JsonElement> entry : element.getAsJsonObject().entrySet())
        {
            try
            {
                RollHistoryManager.RollEvent event = gson.fromJson(entry.getValue(), RollHistoryManager.RollEvent.class);
                if (event != null)
                {
                    history.add(new HistoryKey(entry.getKey(), event.getAt()));
                }
            }
            catch (Exception ignored) {}
        }

        if (history.size() <= RollHistoryManager.MAX_EVENTS)
        {
            return;
        }

        history.sort(Comparator.comparingLong((HistoryKey key) -> key.at).thenComparing(key -> key.id));
        int removeCount = history.size() - RollHistoryManager.MAX_EVENTS;
        JsonObject deletions = new JsonObject();
        for (int i = 0; i < removeCount; i++)
        {
            deletions.add("rollHistory/" + history.get(i).id, com.google.gson.JsonNull.INSTANCE);
        }
        submitPersistentPatch("roll history pruning", deletions, generation, 0);
    }

    private boolean remember(Set<String> set, String value)
    {
        boolean added = set.add(value);
        if (set.size() > MAX_SEEN_LIVE_EVENTS)
        {
            // Exact ordering is unimportant; these are only short-lived de-duplication sets.
            int remove = set.size() - MAX_SEEN_LIVE_EVENTS;
            for (String existing : new ArrayList<>(set))
            {
                if (remove-- <= 0)
                {
                    break;
                }
                set.remove(existing);
            }
        }
        return added;
    }

    private void submitPersistentPatch(String description, JsonObject updates, long expectedGeneration, int attempt)
    {
        String url = activeDatabaseUrl;
        ScheduledExecutorService current = executor;
        if (!running || url == null || expectedGeneration != generation || current == null || current.isShutdown())
        {
            return;
        }

        databaseClient.patch(url, "/", updates).whenComplete((ignored, error) -> {
            if (!running || expectedGeneration != generation)
            {
                return;
            }
            if (error == null)
            {
                setStatus(Status.CONNECTED, null);
                // The SSE echo carries the authoritative delta back into the in-memory mirror.
                return;
            }

            String message = conciseMessage(error);
            setStatus(Status.ERROR, message);
            int nextAttempt = attempt + 1;
            long delaySeconds = Math.min(30L, 1L << Math.min(nextAttempt, 5));
            log.warn("Firebase write failed for {}; retrying in {}s", description, delaySeconds, error);

            ScheduledExecutorService retryExecutor = executor;
            if (retryExecutor != null && !retryExecutor.isShutdown())
            {
                schedule(retryExecutor,
                        () -> submitPersistentPatch(description, updates, expectedGeneration, nextAttempt),
                        delaySeconds,
                        TimeUnit.SECONDS);
            }
        });
    }


    private void schedule(ScheduledExecutorService current, Runnable task, long delay, TimeUnit unit)
    {
        ScheduledFuture<?> future = current.schedule(task, delay, unit);
        scheduledTasks.add(future);
        scheduledTasks.removeIf(done -> done.isDone() || done.isCancelled());
    }

    private void cancelScheduledTasks()
    {
        for (ScheduledFuture<?> future : scheduledTasks)
        {
            future.cancel(false);
        }
        scheduledTasks.clear();
    }

    private void deleteLiveRoll(String eventId, long expectedGeneration)
    {
        String url = activeDatabaseUrl;
        if (!running || url == null || expectedGeneration != generation || isBlank(eventId))
        {
            return;
        }
        databaseClient.delete(url, "/liveRolls/" + eventId).whenComplete((ignored, error) -> {
            if (error != null && running && expectedGeneration == generation)
            {
                log.debug("Could not clean up live roll {}", eventId, error);
            }
        });
    }

    private void clearSharedState()
    {
        obtainedItemsManager.clear();
        rolledItemsManager.clear();
        rolledByManager.clear();
        rollHistoryManager.clear();
    }

    private void setStatus(Status next, String error)
    {
        boolean changed = status != next || (lastError == null ? error != null : !lastError.equals(error));
        status = next;
        lastError = error;
        if (changed)
        {
            Runnable listener = statusListener;
            if (listener != null)
            {
                listener.run();
            }
        }
    }

    private static String normalisePlayerName(String name)
    {
        return name == null || name.trim().isEmpty() ? "Unknown" : name.trim();
    }

    private static boolean isBlank(String value)
    {
        return value == null || value.trim().isEmpty();
    }

    private static String conciseMessage(Throwable error)
    {
        Throwable current = error;
        while (current.getCause() != null)
        {
            current = current.getCause();
        }
        String message = current.getMessage();
        if (message == null || message.trim().isEmpty())
        {
            return current.getClass().getSimpleName();
        }
        return message.length() > 140 ? message.substring(0, 140) + "…" : message;
    }
}

package com.rollbound.managers;

import javax.inject.Singleton;
import java.util.Collection;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.Set;

/**
 * In-memory view of items obtained by the shared RollBound group.
 * Firebase is the authoritative persistence layer; this manager only owns local UI/game state.
 */
@Singleton
public class ObtainedItemsManager
{
    private final Set<Integer> obtainedItems = Collections.synchronizedSet(new LinkedHashSet<>());

    private volatile Runnable onChange;

    public void setOnChange(Runnable onChange)
    {
        this.onChange = onChange;
    }

    public boolean isObtained(int itemId)
    {
        return obtainedItems.contains(itemId);
    }

    public Set<Integer> getObtainedItems()
    {
        synchronized (obtainedItems)
        {
            return Collections.unmodifiableSet(new LinkedHashSet<>(obtainedItems));
        }
    }

    /**
     * Optimistically apply a local obtain. Returns true only when this changed local state.
     */
    public boolean markObtained(int itemId)
    {
        if (itemId <= 0)
        {
            return false;
        }

        boolean changed = obtainedItems.add(itemId);
        if (changed)
        {
            notifyChange();
        }
        return changed;
    }

    /** Replace local state with the authoritative Firebase snapshot. */
    public void replaceAll(Collection<Integer> itemIds)
    {
        LinkedHashSet<Integer> next = new LinkedHashSet<>();
        if (itemIds != null)
        {
            for (Integer id : itemIds)
            {
                if (id != null && id > 0)
                {
                    next.add(id);
                }
            }
        }

        boolean changed;
        synchronized (obtainedItems)
        {
            changed = !obtainedItems.equals(next);
            if (changed)
            {
                obtainedItems.clear();
                obtainedItems.addAll(next);
            }
        }

        if (changed)
        {
            notifyChange();
        }
    }

    public void clear()
    {
        replaceAll(Collections.emptySet());
    }

    private void notifyChange()
    {
        Runnable callback = onChange;
        if (callback != null)
        {
            callback.run();
        }
    }
}

package com.rollbound.managers;

import com.rollbound.RollBoundOverlay;
import com.rollbound.RollBoundPanel;
import com.rollbound.RollBoundConfig;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.*;
import java.util.*;
import java.util.concurrent.PriorityBlockingQueue;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;

/**
 * Manages roll animations and result announcements.
 *
 * Coordinates local and Firebase-synchronised roll animations.
 */
@Singleton
public class RollAnimationManager
{
    @Inject private ItemManager itemManager;
    @Inject private Client client;
    @Inject private ClientThread clientThread;

    @Inject private RolledItemsManager rolledManager;

    @Inject private RolledByManager rolledByManager;
    @Inject private RollHistoryManager rollHistoryManager;

    @Inject private RollBoundOverlay overlay;
    @Inject private RollBoundConfig config;

    private RollBoundPanel rollBoundPanel;

    public void setRollBoundPanel(RollBoundPanel rollBoundPanel)
    {
        this.rollBoundPanel = rollBoundPanel;
    }

    private Set<Integer> allTradeableItems = Collections.emptySet();

    private static final class RollRequest
    {
        final String eventId; // shared event id for history de-dupe
        final int obtainedItemId;
        final Integer forcedRolledItemId; // null for local RNG
        final java.util.List<Integer> forcedChoiceOptions; // null unless this is a RollBound selection roll
        final boolean choiceIsRoller;
        final java.util.function.IntConsumer onChoiceSelected;
        final boolean manual;
        final String rollerName;
        final long createdAt;
        final String batchId;
        final int sequence;

        RollRequest(String eventId,
                    int obtainedItemId,
                    Integer forcedRolledItemId,
                    java.util.List<Integer> forcedChoiceOptions,
                    boolean choiceIsRoller,
                    java.util.function.IntConsumer onChoiceSelected,
                    boolean manual,
                    String rollerName,
                    long createdAt,
                    String batchId,
                    int sequence)
        {
            this.eventId = eventId;
            this.obtainedItemId = obtainedItemId;
            this.forcedRolledItemId = forcedRolledItemId;
            this.forcedChoiceOptions = forcedChoiceOptions;
            this.choiceIsRoller = choiceIsRoller;
            this.onChoiceSelected = onChoiceSelected;
            this.manual = manual;
            this.rollerName = rollerName;
            this.createdAt = createdAt;
            this.batchId = batchId;
            this.sequence = Math.max(0, sequence);
        }

        String orderingGroupId()
        {
            if (batchId != null && !batchId.trim().isEmpty()) return batchId;
            return eventId == null ? "" : eventId;
        }
    }

    private static final Comparator<RollRequest> ROLL_REQUEST_ORDER =
            Comparator.comparingLong((RollRequest request) -> request.createdAt)
                    .thenComparing(RollRequest::orderingGroupId)
                    .thenComparingInt(request -> request.sequence)
                    .thenComparing(request -> request.eventId == null ? "" : request.eventId);

    private final Queue<RollRequest> rollQueue = new PriorityBlockingQueue<>(11, ROLL_REQUEST_ORDER);
    private final Set<ScheduledFuture<?>> scheduledTasks = ConcurrentHashMap.newKeySet();
    private ScheduledExecutorService executor = newExecutor();

    private volatile boolean isRolling = false;
    /** Incremented whenever the local roll UI is reset so interrupted workers cannot revive stale state. */
    private volatile long uiGeneration = 0L;

    // tradeables gating
    private volatile boolean tradeablesReady = false;

    private static final int SNAP_WINDOW_MS = 350;
    /** Small grace period after a RollBound selection so the exit animation can begin before the next roll starts. */
    private static final long CHOICE_EXIT_GRACE_MS = 150L;
    private final Random random = new Random();


    private String getLocalPlayerName()
    {
        try
        {
            if (client != null && client.getLocalPlayer() != null && client.getLocalPlayer().getName() != null)
            {
                return client.getLocalPlayer().getName();
            }
        }
        catch (Exception ignored) {}
        return "Someone";
    }


    private volatile boolean manualRoll = false;

    /** Called by plugin after building tradeables. */
    public void setAllTradeableItems(Set<Integer> allTradeableItems)
    {
        this.allTradeableItems = (allTradeableItems == null)
                ? Collections.emptySet()
                : Collections.unmodifiableSet(new LinkedHashSet<>(allTradeableItems));
        this.tradeablesReady = !this.allTradeableItems.isEmpty();
    }

    public boolean hasTradeablesReady()
    {
        return tradeablesReady && allTradeableItems != null && !allTradeableItems.isEmpty();
    }

    /**
     * Enqueue an obtained item that should trigger a roll.
     *
     * @param obtainedItemId item that caused the roll
     */
    public void enqueueRoll(int obtainedItemId)
    {
        rollQueue.offer(new RollRequest(null, obtainedItemId, null, null, false, null, manualRoll, getLocalPlayerName(), System.currentTimeMillis(), null, 0));
    }

    /** Enqueue a group-synchronised roll with a forced final rolled item id. */
    public void enqueueSyncedRoll(String eventId, int obtainedItemId, int rolledItemId, boolean manual, String rollerName, long createdAt)
    {
        rollQueue.offer(new RollRequest(eventId, obtainedItemId, rolledItemId, null, false, null, manual, rollerName, createdAt, null, 0));
    }

    /** Enqueue a group-synchronised RollBound selection roll (up to 5 duplicated strips). */
    public void enqueueSyncedChoiceRoll(String eventId,
                                        int obtainedItemId,
                                        java.util.List<Integer> optionIds,
                                        boolean manual,
                                        String rollerName,
                                        long createdAt,
                                        boolean isRoller,
                                        java.util.function.IntConsumer onSelected)
    {
        enqueueSyncedChoiceRoll(eventId, obtainedItemId, optionIds, manual, rollerName, createdAt,
                null, 0, isRoller, onSelected);
    }

    /** Enqueue an explicitly ordered RollBound batch member. */
    public void enqueueSyncedChoiceRoll(String eventId,
                                        int obtainedItemId,
                                        java.util.List<Integer> optionIds,
                                        boolean manual,
                                        String rollerName,
                                        long createdAt,
                                        String batchId,
                                        int sequence,
                                        boolean isRoller,
                                        java.util.function.IntConsumer onSelected)
    {
        java.util.List<Integer> safe = (optionIds == null) ? java.util.Collections.emptyList() : new java.util.ArrayList<>(optionIds);
        rollQueue.offer(new RollRequest(eventId, obtainedItemId, null, safe, isRoller, onSelected,
                manual, rollerName, createdAt, batchId, sequence));
    }

    /**
     * Process pending rolls if idle.
     *
     * Animation timing is implemented with scheduled continuations rather than blocking a
     * worker thread. This keeps RollBound compliant with Plugin Hub guidance and makes reset/
     * shutdown cancellation deterministic.
     */
    public void process()
    {
        if (!hasTradeablesReady())
        {
            return; // queue stays intact until tradeables are built
        }

        if (!isRolling && !rollQueue.isEmpty())
        {
            RollRequest req = rollQueue.poll();
            if (req == null)
            {
                return;
            }
            isRolling = true;
            final long runGeneration = uiGeneration;
            ScheduledExecutorService current = executor;
            if (current == null || current.isShutdown())
            {
                finishRoll(runGeneration);
                return;
            }
            current.execute(() -> beginRoll(req, runGeneration));
        }
    }

    private void beginRoll(RollRequest req, long runGeneration)
    {
        try
        {
            if (!isCurrent(runGeneration) || !hasTradeablesReady())
            {
                finishRoll(runGeneration);
                return;
            }

            final int obtainedItemId = req.obtainedItemId;
            final Integer forcedRolled = req.forcedRolledItemId;
            final java.util.List<Integer> forcedChoice = req.forcedChoiceOptions;
            final String rollerName = (req.rollerName != null && !req.rollerName.trim().isEmpty())
                    ? req.rollerName.trim() : "Someone";
            final long createdAt = req.createdAt > 0 ? req.createdAt : System.currentTimeMillis();

            if (forcedChoice != null)
            {
                final java.util.List<Integer> eligibleChoice = new java.util.ArrayList<>();
                for (Integer itemId : forcedChoice)
                {
                    if (itemId != null && allTradeableItems.contains(itemId))
                    {
                        eligibleChoice.add(itemId);
                    }
                }
                if (eligibleChoice.isEmpty())
                {
                    finishRoll(runGeneration);
                    return;
                }

                final int rollDuration = 3000;
                overlay.startChoiceAnimation(req.eventId, eligibleChoice, rollDuration,
                        this::getRandomLockedItem, req.choiceIsRoller, req.onChoiceSelected, rollerName);
                schedule(runGeneration,
                        () -> afterChoiceAnimation(req, runGeneration, System.currentTimeMillis()),
                        rollDuration + SNAP_WINDOW_MS);
                return;
            }

            final int rollDuration = 3000;
            if (forcedRolled != null && !allTradeableItems.contains(forcedRolled))
            {
                finishRoll(runGeneration);
                return;
            }
            final int winnerId = forcedRolled != null ? forcedRolled : getRandomLockedItem();
            overlay.startRollAnimation(winnerId, rollDuration, this::getRandomLockedItem);
            schedule(runGeneration,
                    () -> completeStandardRoll(req, winnerId, rollerName, createdAt, runGeneration,
                            Math.max(0, overlay.getHighlightDurationMs() - SNAP_WINDOW_MS)),
                    rollDuration + SNAP_WINDOW_MS);
        }
        catch (Exception error)
        {
            finishRoll(runGeneration);
        }
    }

    private void afterChoiceAnimation(RollRequest req, long runGeneration, long waitStartedAt)
    {
        if (!isCurrent(runGeneration))
        {
            return;
        }

        try
        {
            if (!req.choiceIsRoller)
            {
                overlay.applyPendingRemoteChoiceSelection(req.eventId);
            }
            waitForChoice(req, runGeneration, waitStartedAt);
        }
        catch (Exception error)
        {
            finishRoll(runGeneration);
        }
    }

    private void waitForChoice(RollRequest req, long runGeneration, long waitStartedAt)
    {
        if (!isCurrent(runGeneration))
        {
            return;
        }

        try
        {
            if (!req.choiceIsRoller)
            {
                overlay.applyPendingRemoteChoiceSelection(req.eventId);
            }

            if (!overlay.isChoicePending(req.eventId))
            {
                schedule(runGeneration, () -> finishRoll(runGeneration), CHOICE_EXIT_GRACE_MS);
                return;
            }

            final long maxWaitMs = req.choiceIsRoller
                    ? 10 * 60 * 1000L
                    : 2 * 60 * 1000L;
            if (System.currentTimeMillis() - waitStartedAt > maxWaitMs)
            {
                overlay.resetUiState();
                schedule(runGeneration, () -> finishRoll(runGeneration), CHOICE_EXIT_GRACE_MS);
                return;
            }

            schedule(runGeneration, () -> waitForChoice(req, runGeneration, waitStartedAt), 50L);
        }
        catch (Exception error)
        {
            finishRoll(runGeneration);
        }
    }

    private void completeStandardRoll(RollRequest req,
                                      int rolledItemId,
                                      String rollerName,
                                      long createdAt,
                                      long runGeneration,
                                      long remainingHighlight)
    {
        if (!isCurrent(runGeneration))
        {
            return;
        }

        try
        {
            if (req.forcedRolledItemId == null)
            {
                rolledManager.markRolled(rolledItemId);
            }

            if (rolledByManager != null)
            {
                rolledByManager.recordRoll(rolledItemId, rollerName, createdAt);
            }

            if (rollHistoryManager != null)
            {
                rollHistoryManager.recordEvent(req.eventId, rollerName, req.obtainedItemId,
                        rolledItemId, createdAt, req.manual);
            }

            announceRollToChat(rollerName, rolledItemId, req.obtainedItemId, req.manual);

            if (remainingHighlight > 0)
            {
                schedule(runGeneration, () -> finishRoll(runGeneration), remainingHighlight);
            }
            else
            {
                finishRoll(runGeneration);
            }
        }
        catch (Exception error)
        {
            finishRoll(runGeneration);
        }
    }

    private void schedule(long runGeneration, Runnable task, long delayMs)
    {
        ScheduledExecutorService current = executor;
        if (current == null || current.isShutdown() || !isCurrent(runGeneration))
        {
            return;
        }
        ScheduledFuture<?> future = current.schedule(() ->
        {
            if (isCurrent(runGeneration))
            {
                task.run();
            }
        }, Math.max(0L, delayMs), TimeUnit.MILLISECONDS);
        scheduledTasks.add(future);
        scheduledTasks.removeIf(done -> done.isDone() || done.isCancelled());
    }

    private boolean isCurrent(long runGeneration)
    {
        return runGeneration == uiGeneration;
    }

    private void finishRoll(long runGeneration)
    {
        if (runGeneration == uiGeneration)
        {
            manualRoll = false;
            isRolling = false;
        }
    }

    /**
     * Cancels the active/queued visual rolls without touching shared Firebase progress.
     * Used by the panel reset button and on logout/account transitions.
     */
    public synchronized void resetUiState()
    {
        uiGeneration++;
        rollQueue.clear();
        manualRoll = false;
        isRolling = false;
        if (overlay != null)
        {
            overlay.resetUiState();
        }

        cancelScheduledTasks();
        ScheduledExecutorService previous = executor;
        if (previous != null)
        {
            previous.shutdownNow();
        }
        executor = newExecutor();
    }

    public boolean isAwaitingLocalChoice()
    {
        return overlay != null && overlay.isAwaitingLocalChoice();
    }

    public boolean isRolling()
    {
        return isRolling;
    }

    /**
     * Pick a random locked item to display during the roll.
     */
    private int getRandomLockedItem()
    {
        if (!hasTradeablesReady())
        {
            return overlay.getFinalItem();
        }

        List<Integer> locked = new ArrayList<>();
        for (int id : allTradeableItems)
        {
            if (!rolledManager.isRolled(id))
            {
                locked.add(id);
            }
        }

        if (locked.isEmpty())
        {
            return overlay.getFinalItem();
        }

        return locked.get(random.nextInt(locked.size()));
    }


    private void announceRollToChat(String rollerName, int rolledItemId, int obtainedItemId, boolean wasManual)
    {
        final String who = (rollerName == null || rollerName.trim().isEmpty())
                ? "Someone"
                : Text.escapeJagex(rollerName.trim());

        clientThread.invoke(() ->
        {
            String rolledTag = ColorUtil.wrapWithColorTag(
                    getItemName(rolledItemId),
                    config.unlockedItemColor()
            );

            String message = who + " unlocked " + rolledTag;

            // For automatic rolls, include the trigger item in the message.
            if (!wasManual && obtainedItemId > 0)
            {
                String obtainedTag = ColorUtil.wrapWithColorTag(
                        getItemName(obtainedItemId),
                        config.rolledItemColor()
                );
                message += " by obtaining " + obtainedTag;
            }

            if (wasManual)
            {
                message += " (manual roll)";
            }

            client.addChatMessage(
                    ChatMessageType.GAMEMESSAGE,
                    "",
                    message,
                    null
            );

            if (rollBoundPanel != null)
            {
                SwingUtilities.invokeLater(rollBoundPanel::updatePanel);
            }
        });
    }

private String getItemName(int itemId)
    {
        ItemComposition comp = itemManager.getItemComposition(itemId);
        return comp.getName();
    }

    public synchronized void startUp()
    {
        if (executor == null || executor.isShutdown() || executor.isTerminated())
        {
            executor = newExecutor();
        }
    }

    private static ScheduledExecutorService newExecutor()
    {
        return Executors.newSingleThreadScheduledExecutor(r ->
        {
            Thread thread = new Thread(r, "RollBound-Roll-Animation");
            thread.setDaemon(true);
            return thread;
        });
    }

    public synchronized void shutdown()
    {
        uiGeneration++;
        rollQueue.clear();
        manualRoll = false;
        isRolling = false;
        if (overlay != null)
        {
            overlay.resetUiState();
        }
        cancelScheduledTasks();
        if (executor != null)
        {
            executor.shutdownNow();
        }
    }

    private void cancelScheduledTasks()
    {
        for (ScheduledFuture<?> future : scheduledTasks)
        {
            future.cancel(false);
        }
        scheduledTasks.clear();
    }
}

package com.rollbound.managers;

import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.UUID;

/** Shared roll history cached locally from Firebase. */
@Singleton
public class RollHistoryManager
{
    public static final int MAX_EVENTS = 500;

    public static final class RollEvent
    {
        private String eventId;
        private long at;
        private String by;
        private int obtainedItemId;
        private int rolledItemId;
        private boolean manual;

        public RollEvent() {}

        public RollEvent(String eventId, long at, String by, int obtainedItemId, int rolledItemId, boolean manual)
        {
            this.eventId = eventId;
            this.at = at;
            this.by = by;
            this.obtainedItemId = obtainedItemId;
            this.rolledItemId = rolledItemId;
            this.manual = manual;
        }

        public String getEventId() { return eventId; }
        public long getAt() { return at; }
        public String getBy() { return by; }
        public int getObtainedItemId() { return obtainedItemId; }
        public int getRolledItemId() { return rolledItemId; }
        public boolean isManual() { return manual; }
    }

    private final List<RollEvent> events = Collections.synchronizedList(new ArrayList<>());
    private final Set<String> seenIds = Collections.synchronizedSet(new HashSet<>());

    private volatile Runnable onChange;

    public void setOnChange(Runnable onChange)
    {
        this.onChange = onChange;
    }

    public List<RollEvent> getSnapshot()
    {
        synchronized (events)
        {
            return new ArrayList<>(events);
        }
    }

    public List<RollEvent> getRecent(int limit)
    {
        List<RollEvent> snapshot = getSnapshot();
        if (limit <= 0 || snapshot.isEmpty())
        {
            return Collections.emptyList();
        }
        int from = Math.max(0, snapshot.size() - limit);
        return new ArrayList<>(snapshot.subList(from, snapshot.size()));
    }

    public boolean recordEvent(String eventId, String by, int obtainedItemId, int rolledItemId, long atMillis, boolean manual)
    {
        if (rolledItemId <= 0)
        {
            return false;
        }

        String id = eventId == null || eventId.trim().isEmpty()
                ? UUID.randomUUID().toString()
                : eventId.trim();
        String who = by == null || by.trim().isEmpty() ? "Unknown" : by.trim();
        long at = atMillis > 0 ? atMillis : System.currentTimeMillis();

        boolean changed = false;
        synchronized (events)
        {
            if (seenIds.add(id))
            {
                events.add(new RollEvent(id, at, who, obtainedItemId, rolledItemId, manual));
                trimLocked();
                changed = true;
            }
        }

        if (changed)
        {
            notifyChange();
        }
        return changed;
    }

    public void replaceAll(Collection<RollEvent> incoming)
    {
        List<RollEvent> next = new ArrayList<>();
        Set<String> nextIds = new HashSet<>();
        if (incoming != null)
        {
            for (RollEvent event : incoming)
            {
                if (event == null || event.getRolledItemId() <= 0 || event.getEventId() == null)
                {
                    continue;
                }
                String id = event.getEventId().trim();
                if (!id.isEmpty() && nextIds.add(id))
                {
                    next.add(event);
                }
            }
        }
        next.sort(Comparator.comparingLong(RollEvent::getAt));
        if (next.size() > MAX_EVENTS)
        {
            next = new ArrayList<>(next.subList(next.size() - MAX_EVENTS, next.size()));
            nextIds.clear();
            for (RollEvent event : next)
            {
                nextIds.add(event.getEventId());
            }
        }

        boolean changed;
        synchronized (events)
        {
            changed = !sameEvents(events, next);
            if (changed)
            {
                events.clear();
                events.addAll(next);
                seenIds.clear();
                seenIds.addAll(nextIds);
            }
        }

        if (changed)
        {
            notifyChange();
        }
    }

    public void clear()
    {
        replaceAll(Collections.emptyList());
    }

    private void trimLocked()
    {
        while (events.size() > MAX_EVENTS)
        {
            RollEvent removed = events.remove(0);
            if (removed != null && removed.getEventId() != null)
            {
                seenIds.remove(removed.getEventId());
            }
        }
    }

    private static boolean sameEvents(List<RollEvent> a, List<RollEvent> b)
    {
        if (a.size() != b.size())
        {
            return false;
        }
        for (int i = 0; i < a.size(); i++)
        {
            RollEvent left = a.get(i);
            RollEvent right = b.get(i);
            if (!left.getEventId().equals(right.getEventId())
                    || left.getAt() != right.getAt()
                    || left.getObtainedItemId() != right.getObtainedItemId()
                    || left.getRolledItemId() != right.getRolledItemId()
                    || left.isManual() != right.isManual())
            {
                return false;
            }
            String lb = left.getBy();
            String rb = right.getBy();
            if (lb == null ? rb != null : !lb.equals(rb))
            {
                return false;
            }
        }
        return true;
    }

    private void notifyChange()
    {
        Runnable callback = onChange;
        if (callback != null)
        {
            callback.run();
        }
    }
}

package com.rollbound.managers;

import javax.inject.Singleton;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/** Tracks the first player/time associated with each group unlock. */
@Singleton
public class RolledByManager
{
    public static final class RolledByEntry
    {
        private String by;
        private long at;

        public RolledByEntry() {}

        public RolledByEntry(String by, long at)
        {
            this.by = by;
            this.at = at;
        }

        public String getBy() { return by; }
        public long getAt() { return at; }
    }

    private final Map<Integer, RolledByEntry> rolledBy = Collections.synchronizedMap(new HashMap<>());

    private volatile Runnable onChange;

    public void setOnChange(Runnable onChange)
    {
        this.onChange = onChange;
    }

    public RolledByEntry getEntry(int itemId)
    {
        return rolledBy.get(itemId);
    }

    public Map<Integer, RolledByEntry> getSnapshot()
    {
        synchronized (rolledBy)
        {
            return new HashMap<>(rolledBy);
        }
    }

    /** Keep the earliest attribution for an item. */
    public boolean recordRoll(int itemId, String by, long atMillis)
    {
        if (itemId <= 0)
        {
            return false;
        }

        String who = by == null || by.trim().isEmpty() ? "Unknown" : by.trim();
        long at = atMillis > 0 ? atMillis : System.currentTimeMillis();
        boolean changed = false;

        synchronized (rolledBy)
        {
            RolledByEntry existing = rolledBy.get(itemId);
            if (existing == null || existing.getAt() <= 0 || at < existing.getAt())
            {
                rolledBy.put(itemId, new RolledByEntry(who, at));
                changed = true;
            }
        }

        if (changed)
        {
            notifyChange();
        }
        return changed;
    }

    public void replaceAll(Map<Integer, RolledByEntry> entries)
    {
        Map<Integer, RolledByEntry> next = new HashMap<>();
        if (entries != null)
        {
            for (Map.Entry<Integer, RolledByEntry> entry : entries.entrySet())
            {
                Integer id = entry.getKey();
                RolledByEntry value = entry.getValue();
                if (id != null && id > 0 && value != null)
                {
                    next.put(id, value);
                }
            }
        }

        boolean changed;
        synchronized (rolledBy)
        {
            changed = !sameEntries(rolledBy, next);
            if (changed)
            {
                rolledBy.clear();
                rolledBy.putAll(next);
            }
        }

        if (changed)
        {
            notifyChange();
        }
    }

    public void clear()
    {
        replaceAll(Collections.emptyMap());
    }

    private static boolean sameEntries(Map<Integer, RolledByEntry> a, Map<Integer, RolledByEntry> b)
    {
        if (a.size() != b.size())
        {
            return false;
        }
        for (Map.Entry<Integer, RolledByEntry> entry : a.entrySet())
        {
            RolledByEntry other = b.get(entry.getKey());
            RolledByEntry value = entry.getValue();
            if (other == null || value == null)
            {
                return false;
            }
            if (value.getAt() != other.getAt())
            {
                return false;
            }
            String left = value.getBy();
            String right = other.getBy();
            if (left == null ? right != null : !left.equals(right))
            {
                return false;
            }
        }
        return true;
    }

    private void notifyChange()
    {
        Runnable callback = onChange;
        if (callback != null)
        {
            callback.run();
        }
    }
}

package com.rollbound.managers;

import javax.inject.Singleton;
import java.util.Collection;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.Set;

/**
 * In-memory view of items unlocked by shared RollBound rolls.
 * Firebase is the authoritative persistence layer.
 */
@Singleton
public class RolledItemsManager
{
    private final Set<Integer> rolledItems = Collections.synchronizedSet(new LinkedHashSet<>());

    private volatile Runnable onChange;

    public void setOnChange(Runnable onChange)
    {
        this.onChange = onChange;
    }

    public boolean isRolled(int itemId)
    {
        return rolledItems.contains(itemId);
    }

    public Set<Integer> getRolledItems()
    {
        synchronized (rolledItems)
        {
            return Collections.unmodifiableSet(new LinkedHashSet<>(rolledItems));
        }
    }

    public boolean markRolled(int itemId)
    {
        if (itemId <= 0)
        {
            return false;
        }

        boolean changed = rolledItems.add(itemId);
        if (changed)
        {
            notifyChange();
        }
        return changed;
    }

    public void replaceAll(Collection<Integer> itemIds)
    {
        LinkedHashSet<Integer> next = new LinkedHashSet<>();
        if (itemIds != null)
        {
            for (Integer id : itemIds)
            {
                if (id != null && id > 0)
                {
                    next.add(id);
                }
            }
        }

        boolean changed;
        synchronized (rolledItems)
        {
            changed = !rolledItems.equals(next);
            if (changed)
            {
                rolledItems.clear();
                rolledItems.addAll(next);
            }
        }

        if (changed)
        {
            notifyChange();
        }
    }

    public void clear()
    {
        replaceAll(Collections.emptySet());
    }

    private void notifyChange()
    {
        Runnable callback = onChange;
        if (callback != null)
        {
            callback.run();
        }
    }
}

package com.rollbound.menus;

import com.rollbound.RollBoundConfig;
import com.rollbound.RollBoundPlugin;
import com.rollbound.filters.EnsouledHeadMapping;
import com.rollbound.filters.ItemSets;
import com.rollbound.firebase.FirebaseSyncService;
import com.rollbound.managers.RolledItemsManager;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.WorldType;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.Set;
import java.util.function.Consumer;

@Singleton
public class ActionHandler {

	private static final Set<MenuAction> disabledActions = EnumSet.of(
			MenuAction.CC_OP,               // inventory “Use” on locked
			MenuAction.WIDGET_TARGET,       // “Use” on widgets
			MenuAction.WIDGET_TARGET_ON_WIDGET  // “Use” on widget -> widget
	);

	private static final Set<MenuAction> GROUND_ACTIONS = EnumSet.of(
			MenuAction.GROUND_ITEM_FIRST_OPTION,
			MenuAction.GROUND_ITEM_SECOND_OPTION,
			MenuAction.GROUND_ITEM_THIRD_OPTION,
			MenuAction.GROUND_ITEM_FOURTH_OPTION,
			MenuAction.GROUND_ITEM_FIFTH_OPTION
	);

	private static final Set<Integer> ALWAYS_ALLOW_OBJECT_IDS = new HashSet<>();

	private static final EnumSet<MenuAction> GAME_OBJECT_ACTIONS = EnumSet.of(
			MenuAction.GAME_OBJECT_FIRST_OPTION,
			MenuAction.GAME_OBJECT_SECOND_OPTION,
			MenuAction.GAME_OBJECT_THIRD_OPTION,
			MenuAction.GAME_OBJECT_FOURTH_OPTION,
			MenuAction.GAME_OBJECT_FIFTH_OPTION
	);

	static
	{
		ALWAYS_ALLOW_OBJECT_IDS.add(net.runelite.api.gameval.ObjectID.CATABOW);
	}

	private static final int ORBS_GROUP = (InterfaceID.Orbs.UNIVERSE >>> 16);

	/**
	 * Normalize a MenuEntryAdded into the base item ID.
	 */
	private int getItemId(MenuEntryAdded event, MenuEntry entry) {
		MenuAction type = entry.getType();
		boolean hasItemId = entry.getItemId() > 0 || event.getItemId() > 0;
		if (!GROUND_ACTIONS.contains(type) && !hasItemId) {
			return -1;
		}
		int raw = GROUND_ACTIONS.contains(type)
				? event.getIdentifier()
				: Math.max(event.getItemId(), entry.getItemId());
		int mapped = EnsouledHeadMapping.toTradeableId(raw);
		return plugin.getItemManager().canonicalize(mapped);
	}

	private final HashSet<Integer> enabledUIs = new HashSet<>() {{
		for (EnabledUI ui : EnabledUI.values()) add(ui.getId());
	}};

	@Inject
	private Client client;
	@Inject
	private EventBus eventBus;
	@Inject
	private RollBoundConfig config;
	@Inject
	private RollBoundPlugin plugin;
	@Inject
	private Restrictions restrictions;
	@Inject
	private RolledItemsManager rolledItemsManager;
	@Inject
	private FirebaseSyncService firebaseSyncService;
	private int enabledUIOpen = -1;

	// A no-op click handler that marks a menu entry as disabled.
	private final Consumer<MenuEntry> DISABLED = e -> { };

	public void startUp() {
		eventBus.register(this);
		eventBus.register(restrictions);
	}

	public void shutDown() {
		eventBus.unregister(this);
		eventBus.unregister(restrictions);
	}

	private boolean enabledUiOpen() {
		return enabledUIOpen != -1;
	}

	private EnabledUI currentEnabledUi()
	{
		return enabledUIOpen == -1 ? null : EnabledUI.fromGroupId(enabledUIOpen);
	}

	private boolean inactive() {
		if (!plugin.isCurrentAccountEnabledForRollBound()) return true;
		if (firebaseSyncService.getStatus() != FirebaseSyncService.Status.CONNECTED) return true;
		if (isPvpContext()) return true;
		return client.getGameState().getState() < GameState.LOADING.getState();
	}

	/**
	 * RollBound never alters menu entries in PvP contexts. This deliberately fails open so
	 * item/spell restrictions cannot remove or deprioritise combat options in PvP.
	 */
	private boolean isPvpContext()
	{
		EnumSet<WorldType> worldTypes = client.getWorldType();
		if (WorldType.isPvpWorld(worldTypes)
				|| worldTypes.contains(WorldType.BOUNTY)
				|| worldTypes.contains(WorldType.HIGH_RISK)
				|| worldTypes.contains(WorldType.LAST_MAN_STANDING)
				|| worldTypes.contains(WorldType.PVP_ARENA))
		{
			return true;
		}

		return client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) > 0;
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event) {
		if (event.getGroupId() == enabledUIOpen) enabledUIOpen = -1;
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event) {
		if (enabledUIs.contains(event.getGroupId()))
			enabledUIOpen = event.getGroupId();
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event) {
		if (inactive()) return;

		EnabledUI ui = currentEnabledUi();
		if (ui != null && !ui.isGreyLockedItems())
		{
			return;
		}

		MenuEntry entry = event.getMenuEntry();
		MenuAction action = entry.getType();
		int id = getItemId(event, entry);
		boolean enabled;
		// Check if the entry looks like it's for a ground item.
		if (isGroundItem(entry)) {
			enabled = !isLockedGroundItem(id);
		} else {
			enabled = isEnabled(id, entry, action);
		}
		// If not enabled, grey out the text and set the click handler to DISABLED.
		if (!enabled) {
			String option = Text.removeTags(entry.getOption());
			String target = Text.removeTags(entry.getTarget());
			entry.setOption("<col=808080>" + option);
			entry.setTarget("<col=808080>" + target);
			entry.onClick(DISABLED);
			if (config.deprioritizeLockedOptions()) {
				entry.setDeprioritized(true);
			}
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event) {
		if (inactive()) return;

		MenuEntry entry = event.getMenuEntry();
		int rawItemId = entry.getItemId();
		int canonicalItemId = rawItemId > 0
				? plugin.getItemManager().canonicalize(EnsouledHeadMapping.toTradeableId(rawItemId))
				: -1;
		if (isItemSetCreationAction(canonicalItemId, entry))
		{
			event.consume();
			return;
		}

		// If the entry is disabled, consume the event.
		if (event.getMenuEntry().onClick() == DISABLED) {
			event.consume();
			return;
		}
		// Extra safeguard for ground items.
		handleGroundItems(plugin.getItemManager(), rolledItemsManager, event, plugin);
	}

	/**
	 * Returns true if the entry appears to be for a ground item.
	 */
	private boolean isGroundItem(MenuEntry entry)
	{
		return GROUND_ACTIONS.contains(entry.getType());
	}

	/**
	 * @param itemId canonicalized item ID of a ground item
	 * @return true if it’s tradeable, tracked, and still locked
	 */
	private boolean isLockedGroundItem(int itemId)
	{
		return plugin.isGeTradeable(itemId)
				&& !plugin.isNotTracked(itemId)
				&& !rolledItemsManager.isRolled(itemId);
	}

	private boolean isItemSetCreationAction(int id, MenuEntry entry)
	{
		String option = Text.removeTags(entry.getOption());
		boolean exchangeAction = "exchange".equalsIgnoreCase(option)
				|| "pack".equalsIgnoreCase(option)
				|| "make-set".equalsIgnoreCase(option)
				|| "create-set".equalsIgnoreCase(option);
		if (!exchangeAction)
		{
			return false;
		}

		// Only block packing from the Grand Exchange Item Sets list. The side inventory
		// uses a separate interface, so existing set boxes can still be unpacked.
		int widgetGroup = entry.getParam1() >>> 16;
		int itemSetsGroup = InterfaceID.Itemsets.UNIVERSE >>> 16;
		if (widgetGroup != itemSetsGroup)
		{
			return false;
		}

		if (ItemSets.isItemSet(id))
		{
			return true;
		}

		String target = Text.removeTags(entry.getTarget());
		if (target == null || target.isEmpty())
		{
			return false;
		}

		String normalizedTarget = target.toLowerCase(java.util.Locale.ROOT);
		for (int itemSetId : ItemSets.getAllItemSetIds())
		{
			String itemSetName = plugin.getItemManager().getItemComposition(itemSetId).getName();
			if (itemSetName != null && !itemSetName.isEmpty()
					&& normalizedTarget.contains(itemSetName.toLowerCase(java.util.Locale.ROOT)))
			{
				return true;
			}
		}

		return false;
	}

	private boolean isHealthOrbCure(MenuEntry entry)
	{
		if (entry.getType() != MenuAction.CC_OP)
			return false;

		if (!"cure".equalsIgnoreCase(Text.removeTags(entry.getOption())))
			return false;

		int w1 = entry.getParam1();
		int w0 = entry.getParam0();

		return (w1 >>> 16) == ORBS_GROUP || (w0 >>> 16) == ORBS_GROUP;
	}

	/**
	 * This method handles non-ground items (or any other cases) by checking if the item is enabled.
	 * It returns true if the action should be allowed.
	 */
	private boolean isEnabled(int id, MenuEntry entry, MenuAction action) {
		if (isItemSetCreationAction(id, entry))
		{
			return false;
		}

		if (isHealthOrbCure(entry))
		{
			return true;
		}

		String option = Text.removeTags(entry.getOption());
		String target = Text.removeTags(entry.getTarget());

		EnabledUI ui = currentEnabledUi();
		if (ui != null && ui.isAllowAllActions())
		{
			return true;
		}

		// Allowlisted world objects bypass all restrictions
		if (GAME_OBJECT_ACTIONS.contains(action) && ALWAYS_ALLOW_OBJECT_IDS.contains(entry.getIdentifier()))
		{
			return true;
		}

		// Always allow "Drop" / "Check"
		if (option.equalsIgnoreCase("drop") || option.equalsIgnoreCase("check"))
			return true;
		if (option.equalsIgnoreCase("clean") || option.equalsIgnoreCase("rub"))
		{
			if (!plugin.isInPlay(id)) { return true; }
			return rolledItemsManager.isRolled(id);
		}
		if ("harpoon".equalsIgnoreCase(option)
				&& !hasAnyHarpoonInInvOrWorn())
		{
			String t = target.toLowerCase();
			if (t.contains("fishing spot") || t.contains("spirit pool"))
				return true;
		}
		if (SkillOp.isSkillOp(option))
		{
			if (SkillOp.fromString(option) == SkillOp.FIRE
					&& !target.toLowerCase().contains("pottery oven"))
			{
				return true;
			}

			return restrictions.isSkillOpEnabled(option);
		}
		if (Spell.isSpell(option))
			return restrictions.isSpellOpEnabled(option);
		if (Spell.isSpell(target))
			return restrictions.isSpellOpEnabled(target);

		boolean enabled = !disabledActions.contains(action);
		if (enabled)
			return true;
		if (id == 0 || id == -1 || !plugin.isInPlay(id))
			return true;
		return rolledItemsManager.isRolled(id);
	}

	/**
	 * A static helper to further safeguard ground item actions.
	 * If a ground item is locked, this method consumes the event.
	 */
	public static void handleGroundItems(ItemManager itemManager, RolledItemsManager rolledItemsManager,
										 MenuOptionClicked event, RollBoundPlugin plugin) {
		if (event.getMenuAction() != null && GROUND_ACTIONS.contains(event.getMenuAction())) {
			int rawItemId = event.getId() != -1
					? event.getId()
					: event.getMenuEntry().getItemId();
			int mapped = EnsouledHeadMapping.toTradeableId(rawItemId);
			int canonicalGroundId = itemManager.canonicalize(mapped);
			if (plugin.isGeTradeable(canonicalGroundId)
					&& !plugin.isNotTracked(canonicalGroundId)
					&& rolledItemsManager != null
					&& !rolledItemsManager.isRolled(canonicalGroundId)) {
				event.consume();
			}
		}
	}

	/**
	 Checks for harpoon in inventory and worn items for
	 barbarian fishing.
	 **/
	private boolean hasAnyHarpoonInInvOrWorn()
	{
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		ItemContainer inv  = client.getItemContainer(InventoryID.INV);

		if (worn != null)
		{
			for (Item item : worn.getItems())
			{
				SkillItem si = SkillItem.fromId(item.getId());
				if (si != null && si.getSkillOp() == SkillOp.HARPOON) return true;
			}
		}

		if (inv != null)
		{
			for (Item item : inv.getItems())
			{
				SkillItem si = SkillItem.fromId(item.getId());
				if (si != null && si.getSkillOp() == SkillOp.HARPOON) return true;
			}
		}

		return false;
	}
}

package com.rollbound.menus;

import lombok.Getter;
import net.runelite.api.gameval.ItemID;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

@Getter
public enum BlightedSack
{
    ENTANGLE(
            ItemID.BLIGHTED_SACK_ENTANGLE,
            Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
                    "Snare", "Entangle", "Bind"
            )))
    ),
    SURGE(
            ItemID.BLIGHTED_SACK_SURGE,
            Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
                    "Wind Surge", "Water Surge", "Earth Surge", "Fire Surge",
                    "Wind Wave",  "Water Wave",  "Earth Wave",  "Fire Wave"
            )))
    ),
    TELEBLOCK(
            ItemID.BLIGHTED_SACK_TELEBLOCK,
            Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
                    "Tele Block", "Teleport to Target"
            )))
    ),
    VENGEANCE(
            ItemID.BLIGHTED_SACK_VENGEANCE,
            Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
                    "Vengeance", "Vengeance Other"
            )))
    ),
    ANCIENT_ICE(
            ItemID.BLIGHTED_SACK_ICEBARRAGE,
            Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
                    "Ice Rush", "Ice Burst", "Ice Blitz", "Ice Barrage"
            )))
    );

    private final int sackItemId;
    private final Set<String> allowedSpells;
    private static final Map<String, BlightedSack> SPELL_TO_SACK;
    static
    {
        Map<String, BlightedSack> map = new HashMap<>();
        for (BlightedSack sack : values())
        {
            for (String spell : sack.allowedSpells)
            {
                map.put(spell, sack);
            }
        }
        SPELL_TO_SACK = Collections.unmodifiableMap(map);
    }

    BlightedSack(int sackItemId, Set<String> allowedSpells)
    {
        this.sackItemId = sackItemId;
        this.allowedSpells = allowedSpells;
    }

    /**
     * @return the BlightedSack that grants this spell, or null if none.
     */
    public static BlightedSack fromSpell(String spellName)
    {
        return SPELL_TO_SACK.get(spellName);
    }
}

package com.rollbound.menus;

import net.runelite.api.gameval.InterfaceID;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * Interfaces that need special handling for RollBound item restrictions/dimming.
 */
public enum EnabledUI
{
    BANK(InterfaceID.BANKMAIN, true, true),
    DEPOSIT_BOX(InterfaceID.BANK_DEPOSITBOX, true, true),
    CUSTOM_FUR_STORE(InterfaceID.HuntingCustomfurs.CONTENT, false, true),
    CRAFTING_GOLD(InterfaceID.CraftingGold.UNIVERSE, false, true),
    TTREK_REWARDS(InterfaceID.TREK_REWARDS, false, true),
    SKILLMULTI(InterfaceID.Skillmulti.ALL, false, true),
    RUNEDOKU(InterfaceID.ROGUETRADER_SUDOKU, false, true);

    private static final Map<Integer, EnabledUI> BY_GROUP_ID;

    static
    {
        Map<Integer, EnabledUI> values = new HashMap<>();
        for (EnabledUI ui : EnabledUI.values())
        {
            values.put(ui.id, ui);
        }
        BY_GROUP_ID = Collections.unmodifiableMap(values);
    }

    private final int id;
    private final boolean greyLockedItems;
    private final boolean allowAllActions;

    EnabledUI(int id, boolean greyLockedItems, boolean allowAllActions)
    {
        this.id = (id > 0xFFFF) ? (id >>> 16) : id;
        this.greyLockedItems = greyLockedItems;
        this.allowAllActions = allowAllActions;
    }

    public int getId()
    {
        return id;
    }

    public boolean isGreyLockedItems()
    {
        return greyLockedItems;
    }

    public boolean isAllowAllActions()
    {
        return allowAllActions;
    }

    public static EnabledUI fromGroupId(int groupId)
    {
        return BY_GROUP_ID.get(groupId);
    }
}

package com.rollbound.menus;

import com.rollbound.RollBoundPlugin;
import com.rollbound.managers.RolledItemsManager;
import com.rollbound.account.AccountManager;
import net.runelite.api.*;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.events.GameTick;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.*;

@Singleton
public class Restrictions
{
	private static final int[] RUNE_POUCH_TYPE_VARBITS = {
			VarbitID.RUNE_POUCH_TYPE_1,
			VarbitID.RUNE_POUCH_TYPE_2,
			VarbitID.RUNE_POUCH_TYPE_3,
			VarbitID.RUNE_POUCH_TYPE_4,
			VarbitID.RUNE_POUCH_TYPE_5,
			VarbitID.RUNE_POUCH_TYPE_6
	};

	private static final int[] RUNE_POUCH_AMOUNT_VARBITS = {
			VarbitID.RUNE_POUCH_QUANTITY_1,
			VarbitID.RUNE_POUCH_QUANTITY_2,
			VarbitID.RUNE_POUCH_QUANTITY_3,
			VarbitID.RUNE_POUCH_QUANTITY_4,
			VarbitID.RUNE_POUCH_QUANTITY_5,
			VarbitID.RUNE_POUCH_QUANTITY_6
	};

	private static final WorldArea FOUNTAIN_OF_RUNE_AREA =
			new WorldArea(3367, 3890, 13, 9, 0);

	private boolean isInFountainArea()
	{
		WorldPoint lp = client.getLocalPlayer().getWorldLocation();
		return FOUNTAIN_OF_RUNE_AREA.contains(lp);
	}

	private boolean isInLMS()
	{
		EnumSet<WorldType> worldTypes = client.getWorldType();
		return (worldTypes.contains(WorldType.LAST_MAN_STANDING));

	}

	public static final int SPELL_REQUIREMENT_OVERLAY_NORMAL = InterfaceID.MagicSpellbook.TOOLTIP;
	public static final int AUTOCAST_REQUIREMENT_OVERLAY_NORMAL = InterfaceID.Autocast.INFO;

	@Inject private RollBoundPlugin plugin;
	@Inject private Client client;
	@Inject private RolledItemsManager rolledItemsManager;
	@Inject private AccountManager accountManager;
	private final Set<SkillOp> enabledSkillOps = EnumSet.noneOf(SkillOp.class);
	private final HashSet<Integer> availableRunes = new HashSet<>();

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!accountManager.ready()) return;
		enabledSkillOps.clear();
		availableRunes.clear();

		ItemContainer equippedItems = client.getItemContainer(InventoryID.WORN);
		ItemContainer inventoryItems = client.getItemContainer(InventoryID.INV);

		if (equippedItems != null)
		{
			Arrays.stream(equippedItems.getItems()).forEach(item -> {
				int id = item.getId();
				SkillItem skillItem = SkillItem.fromId(id);
				if (skillItem != null && !skillItem.isRequiresUnlock())
				{
					enabledSkillOps.add(skillItem.getSkillOp());
					return;
				}

				if (shouldSkipItem(id)) return;
				if (RuneProvider.isEquippedProvider(id))
					availableRunes.addAll(RuneProvider.getProvidedRunes(id));
				if (skillItem != null) enabledSkillOps.add(skillItem.getSkillOp());
			});
		}

		if (inventoryItems != null)
		{
			Arrays.stream(inventoryItems.getItems()).forEach(item -> {
				int id = item.getId();
				SkillItem skillItem = SkillItem.fromId(id);
				if (skillItem != null && !skillItem.isRequiresUnlock())
				{
					enabledSkillOps.add(skillItem.getSkillOp());
					return;
				}

				if (shouldSkipItem(id)) return;
				if (RuneProvider.isInvProvider(id))
					availableRunes.addAll(RuneProvider.getProvidedRunes(id));
				if (skillItem != null) enabledSkillOps.add(skillItem.getSkillOp());
			});
		}

		EnumComposition pouchEnum = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		for (int i = 0; i < 6; i++)
		{
			int qty     = client.getVarbitValue(RUNE_POUCH_AMOUNT_VARBITS[i]);
			int typeIdx = client.getVarbitValue(RUNE_POUCH_TYPE_VARBITS[i]);
			if (qty <= 0)
			{
				continue;
			}

			int runeId = pouchEnum.getIntValue(typeIdx);
			if (shouldSkipItem(runeId))
			{
				continue;
			}

			if (RuneProvider.isInvProvider(runeId))
			{
				availableRunes.addAll(RuneProvider.getProvidedRunes(runeId));
			}
		}
	}

	public boolean isSkillOpEnabled(String option)
	{
		SkillOp op = SkillOp.fromString(option);
		return enabledSkillOps.contains(op);
	}

	private boolean shouldSkipItem(int id)
	{
		if (!plugin.isInPlay(id))
		{
			return !(RuneProvider.isEquippedProvider(id)
					|| RuneProvider.isInvProvider(id));
		}
		return !rolledItemsManager.isRolled(id);
	}

	public boolean isSpellOpEnabled(String spellName)
	{
		if (isInFountainArea() || isInLMS()) { return true; }
		BlightedSack sack = BlightedSack.fromSpell(spellName);
		if (sack != null)
		{
			int sackId = sack.getSackItemId();
			ItemContainer inv = client.getItemContainer(InventoryID.INV);
			if (inv != null	&& (sackId == ItemID.BLIGHTED_SACK_SURGE || rolledItemsManager.isRolled(sackId)))
			{
				for (Item item : inv.getItems())
				{
					if (item.getId() == sackId)
					{
						return true;
					}
				}
			}
		}

		Widget autocastOverlay = client.getWidget(AUTOCAST_REQUIREMENT_OVERLAY_NORMAL);
		if (autocastOverlay != null) return processChildren(autocastOverlay);

		Widget spellOverlay = client.getWidget(SPELL_REQUIREMENT_OVERLAY_NORMAL);
		if (spellOverlay != null) return processChildren(spellOverlay);
		return false;
	}

	public boolean processChildren(Widget widget)
	{
		Widget[] children = widget.getDynamicChildren();
		if (children == null) return true;

		for (Widget child : children)
		{
			int id = child.getItemId();
			if (id == -1) continue;

			if (plugin.isInPlay(id) && !availableRunes.contains(id))
				return false;
		}
		return true;
	}
}

