@Getter
public enum SkillOp
{
	CHOP_DOWN("Chop down"),
	MINE("Mine"),
	SMALL_NET("Small Net"),
	BIG_NET("Big Net"),
	CAGE("Cage"),
	BAIT("Bait"),
	LURE("Lure"),
	HARPOON("Harpoon"),
	RAKE("Rake"),
	PRUNE("Prune"),
	CURE("Cure"),
	GRIND("Grind"),
	SMITH("Smith"),
	SMELT("Smelt"),
	SHEAR("Shear"),
	CLEAN("Clean"),
	FIRE("Fire"),
	CRAFT_RUNE("Craft-rune");

	private final String option;

	SkillOp(String option)
	{
		this.option = option;
	}

	private static final HashSet<String> ALL_SKILL_OPS = new HashSet<>();
	private static final HashMap<String, SkillOp> STRING_TO_OP = new HashMap<>();

	static
	{
		for (SkillOp skillOp : SkillOp.values())
		{
			ALL_SKILL_OPS.add(skillOp.option);
			STRING_TO_OP.put(skillOp.option, skillOp);
		}
	}

	public static boolean isSkillOp(String option)
	{
		return ALL_SKILL_OPS.contains(option);
	}

	public static SkillOp fromString(String option)
	{
		if (!isSkillOp(option)) return null;
		return STRING_TO_OP.get(option);
	}
}

package com.rollbound.tracker;

/**
 * Encodes arbitrary display strings for use as Firebase Realtime Database object keys.
 *
 * Firebase keys may not contain '.', '$', '#', '[', ']' or '/'. '%' is encoded too so
 * the transformation is reversible without collisions with literal escape sequences.
 */
public final class FirebaseKeyCodec
{
    private FirebaseKeyCodec() {}

    public static String encode(String value)
    {
        if (value == null)
        {
            return "";
        }

        StringBuilder out = new StringBuilder(value.length() + 8);
        for (int i = 0; i < value.length(); i++)
        {
            char c = value.charAt(i);
            switch (c)
            {
                case '%': out.append("%25"); break;
                case '.': out.append("%2E"); break;
                case '$': out.append("%24"); break;
                case '#': out.append("%23"); break;
                case '[': out.append("%5B"); break;
                case ']': out.append("%5D"); break;
                case '/': out.append("%2F"); break;
                default:
                    if (c <= 0x1F || c == 0x7F)
                    {
                        out.append(String.format("%%%02X", (int) c));
                    }
                    else
                    {
                        out.append(c);
                    }
                    break;
            }
        }
        return out.toString();
    }
}

