        putVarbit(map, "Wilderness Elite", Varbits.DIARY_WILDERNESS_ELITE);
    }

    private void collectCombatAchievements(PlayerProgressSnapshot.CombatAchievements out)
    {
        addTaskCount(out, "easy", Varbits.COMBAT_TASK_EASY);
        addTaskCount(out, "medium", Varbits.COMBAT_TASK_MEDIUM);
        addTaskCount(out, "hard", Varbits.COMBAT_TASK_HARD);
        addTaskCount(out, "elite", Varbits.COMBAT_TASK_ELITE);
        addTaskCount(out, "master", Varbits.COMBAT_TASK_MASTER);
        addTaskCount(out, "grandmaster", Varbits.COMBAT_TASK_GRANDMASTER);
        out.tiers.put("easy", varbit(Varbits.COMBAT_ACHIEVEMENT_TIER_EASY) > 0);
        out.tiers.put("medium", varbit(Varbits.COMBAT_ACHIEVEMENT_TIER_MEDIUM) > 0);
        out.tiers.put("hard", varbit(Varbits.COMBAT_ACHIEVEMENT_TIER_HARD) > 0);
        out.tiers.put("elite", varbit(Varbits.COMBAT_ACHIEVEMENT_TIER_ELITE) > 0);
        out.tiers.put("master", varbit(Varbits.COMBAT_ACHIEVEMENT_TIER_MASTER) > 0);
        out.tiers.put("grandmaster", varbit(Varbits.COMBAT_ACHIEVEMENT_TIER_GRANDMASTER) > 0);
    }

    private void addTaskCount(PlayerProgressSnapshot.CombatAchievements out, String key, int varbit)
    {
        int value = varbit(varbit);
        out.taskCounts.put(key, value);
        out.count += value;
    }

    private void collectSlayer(PlayerProgressSnapshot.Slayer out)
    {
        out.points = varbit(Varbits.SLAYER_POINTS);
        out.taskStreak = varbit(Varbits.SLAYER_TASK_STREAK);
        out.bossTask = varbit(Varbits.SLAYER_TASK_BOSS);
        putUnlock(out, "biggerAndBadder", VarbitID.SLAYER_UNLOCK_SUPERIORMOBS);
        putUnlock(out, "likeABoss", VarbitID.SLAYER_UNLOCK_BOSSES);
        putUnlock(out, "aviansies", VarbitID.SLAYER_UNLOCK_AVIANSIES);
        putUnlock(out, "basilisks", VarbitID.SLAYER_UNLOCK_BASILISK);
        putUnlock(out, "fossilIslandWyverns", VarbitID.SLAYER_UNLOCK_FOSSILWYVERNBLOCK);
        putUnlock(out, "grotesqueGuardians", VarbitID.SLAYER_UNLOCK_GROTESQUEKILLS);
        putUnlock(out, "lizardmen", VarbitID.SLAYER_UNLOCK_LIZARDMEN);
        putUnlock(out, "mithrilDragons", VarbitID.SLAYER_UNLOCK_MITHRILDRAGONS);
        putUnlock(out, "slayerRingStorage", VarbitID.SLAYER_UNLOCK_STORAGE);
        putUnlock(out, "tzHaar", VarbitID.SLAYER_UNLOCK_TZHAAR);
        putUnlock(out, "vampyres", VarbitID.SLAYER_UNLOCK_VAMPYRES);
        putUnlock(out, "warpedCreatures", VarbitID.SLAYER_UNLOCK_WARPED_CREATURES);
        putUnlock(out, "wildernessExtraTasks", VarbitID.SLAYER_UNLOCK_WILDY_EXTRATASKS);
        putUnlock(out, "redDragons", VarbitID.SLAYER_UNLOCK_REDDRAGONS);
        // Newer unlocks are included when present in the RuneLite API used by this build.
        putUnlock(out, "gryphons", VarbitID.SLAYER_UNLOCK_GRYPHONS);
        putUnlock(out, "aquanites", VarbitID.SLAYER_UNLOCK_AQUANITES);
    }

    private void collectBarbarianTraining(Map<String, Integer> map)
    {
        putVarbit(map, "BRUT_FISHING_S", VarbitID.BRUT_FISHING_S);
        putVarbit(map, "BRUT_FISHING_R", VarbitID.BRUT_FISHING_R);
        putVarbit(map, "BRUT_FIRE", VarbitID.BRUT_FIRE);
        putVarbit(map, "BRUT_TRACKER", VarbitID.BRUT_TRACKER);
        putVarbit(map, "BRUT_HERB_POTION", VarbitID.BRUT_HERB_POTION);
        putVarbit(map, "BRUT_SMITH_SPEAR", VarbitID.BRUT_SMITH_SPEAR);
        putVarbit(map, "BRUT_SMITH_HASTA", VarbitID.BRUT_SMITH_HASTA);
        putVarbit(map, "BRUT_CRAFT_SHIP", VarbitID.BRUT_CRAFT_SHIP);
        putVarbit(map, "BRUT_TRIED_POOL", VarbitID.BRUT_TRIED_POOL);
        putVarbit(map, "BRUT_TRIED_DOOR", VarbitID.BRUT_TRIED_DOOR);
        putVarbit(map, "BRUT_PRAYER_TOTAL", VarbitID.BRUT_PRAYER_TOTAL);
        putVarbit(map, "BRUT_ALL_CERT_DONE", VarbitID.BRUT_ALL_CERT_DONE);
        putVarbit(map, "BRUT_FARMING_PLANTING", VarbitID.BRUT_FARMING_PLANTING);
        putVarbit(map, "BRUT_FARMING_SMASHING", VarbitID.BRUT_FARMING_SMASHING);
        putVarbit(map, "BRUT_MINIQUEST", VarbitID.BRUT_MINIQUEST);
        putVarbit(map, "BRUT_SMASH_POTS_AUTOMATICALLY", VarbitID.BRUT_SMASH_POTS_AUTOMATICALLY);
        putVarbit(map, "BRUT_DIBBER_FAILED_ATTEMPTS", VarbitID.BRUT_DIBBER_FAILED_ATTEMPTS);
    }

    private void putUnlock(PlayerProgressSnapshot.Slayer out, String key, int id)
    {
        out.unlocks.put(key, varbit(id) > 0);
    }

    private void putVarbit(Map<String, Integer> map, String key, int id)
    {
        map.put(key, varbit(id));
    }

    private int varbit(int id)
    {
        try
        {
            return client.getVarbitValue(id);
        }
        catch (Exception ignored)
        {
            return 0;
        }
    }
}

package com.rollbound.tracker;

import com.google.gson.JsonObject;

import java.util.LinkedHashMap;
import java.util.Map;

/** Compact, JSON-friendly snapshot of player progression used by the RollBound web tracker. */
public final class PlayerProgressSnapshot
{
    public int schemaVersion = 1;
    public long updatedAt;
    public String playerName;
    public String accountType;
    public boolean online;
    public Map<String, Integer> levels = new LinkedHashMap<>();
    public Map<String, Integer> quests = new LinkedHashMap<>();
    public int questPoints;
    public Map<String, Integer> achievementDiaries = new LinkedHashMap<>();
    public CombatAchievements combatAchievements = new CombatAchievements();
    public Slayer slayer = new Slayer();
    public Map<String, Integer> barbarianTraining = new LinkedHashMap<>();
    public int hunterRumoursCompleted;

    /**
     * Serialise explicitly rather than relying on reflective Gson serialisation.
     * Dynamic map keys are encoded because Firebase Realtime Database rejects keys
     * containing '.', '$', '#', '[', ']' and '/'.
     */
    public JsonObject toFirebaseJson()
    {
        JsonObject out = new JsonObject();
        out.addProperty("schemaVersion", schemaVersion);
        out.addProperty("updatedAt", updatedAt);
        if (playerName != null) out.addProperty("playerName", playerName);
        if (accountType != null) out.addProperty("accountType", accountType);
        out.addProperty("online", online);
        out.add("levels", integerMap(levels));
        out.add("quests", integerMap(quests));
        out.addProperty("questPoints", questPoints);
        out.add("achievementDiaries", integerMap(achievementDiaries));

        JsonObject ca = new JsonObject();
        ca.addProperty("count", combatAchievements == null ? 0 : combatAchievements.count);
        ca.add("taskCounts", integerMap(combatAchievements == null ? null : combatAchievements.taskCounts));
        ca.add("tiers", booleanMap(combatAchievements == null ? null : combatAchievements.tiers));
        out.add("combatAchievements", ca);

        JsonObject slayerJson = new JsonObject();
        Slayer s = slayer == null ? new Slayer() : slayer;
        slayerJson.addProperty("points", s.points);
        slayerJson.addProperty("taskStreak", s.taskStreak);
        slayerJson.addProperty("bossTask", s.bossTask);
        slayerJson.add("unlocks", booleanMap(s.unlocks));
        out.add("slayer", slayerJson);

        out.add("barbarianTraining", integerMap(barbarianTraining));
        out.addProperty("hunterRumoursCompleted", hunterRumoursCompleted);
        return out;
    }

    private static JsonObject integerMap(Map<String, Integer> map)
    {
        JsonObject out = new JsonObject();
        if (map == null) return out;
        for (Map.Entry<String, Integer> entry : map.entrySet())
        {
            if (entry.getKey() == null) continue;
            out.addProperty(FirebaseKeyCodec.encode(entry.getKey()), entry.getValue() == null ? 0 : entry.getValue());
        }
        return out;
    }

    private static JsonObject booleanMap(Map<String, Boolean> map)
    {
        JsonObject out = new JsonObject();
        if (map == null) return out;
        for (Map.Entry<String, Boolean> entry : map.entrySet())
        {
            if (entry.getKey() == null) continue;
            out.addProperty(FirebaseKeyCodec.encode(entry.getKey()), Boolean.TRUE.equals(entry.getValue()));
        }
        return out;
    }

    public static final class CombatAchievements
    {
        public int count;
        public Map<String, Integer> taskCounts = new LinkedHashMap<>();
        public Map<String, Boolean> tiers = new LinkedHashMap<>();
    }

    public static final class Slayer
    {
        public int points;
        public int taskStreak;
        public int bossTask;
        public Map<String, Boolean> unlocks = new LinkedHashMap<>();
    }
}

package com.rollbound.tracker;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.rollbound.RollBoundConfig;
import com.rollbound.drops.DropItem;
import com.rollbound.drops.DropTableSection;
import com.rollbound.drops.NpcDropData;
import com.rollbound.firebase.FirebaseDatabaseClient;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * Realtime player progression + tracker source publisher.
 *
 * Snapshots are hash-deduplicated and debounced. The Firebase key is a group-specific
 * SHA-256 pseudonym derived from the account hash, so the raw account hash is never uploaded.
 */
@Singleton
public final class TrackerTelemetryService
{
    private static final Logger log = LoggerFactory.getLogger(TrackerTelemetryService.class);
    private static final long DEBOUNCE_MS = 750L;
    private static final long KEEPALIVE_SECONDS = 60L;
    private static final String HUNTER_RUMOURS_KEY = "trackerHunterRumoursCompleted";

    private final Client client;
    private final ClientThread clientThread;
    private final RollBoundConfig config;
    private final ConfigManager configManager;
    private final FirebaseDatabaseClient databaseClient;
    private final PlayerProgressCollector collector;
    private final Gson gson;

    private final AtomicBoolean queued = new AtomicBoolean(false);
    private final Set<ScheduledFuture<?>> scheduledTasks = ConcurrentHashMap.newKeySet();
    private volatile ScheduledExecutorService executor;
    private volatile boolean running;
    private volatile String lastFingerprint;
    private volatile String activePlayerKey;
    private volatile String activeDatabaseUrl;

    @Inject
    public TrackerTelemetryService(Client client, ClientThread clientThread, RollBoundConfig config,
                                   ConfigManager configManager, FirebaseDatabaseClient databaseClient,
                                   PlayerProgressCollector collector, Gson gson)
    {
        this.client = client;
        this.clientThread = clientThread;
        this.config = config;
        this.configManager = configManager;
        this.databaseClient = databaseClient;
        this.collector = collector;
        this.gson = gson;
    }

    public synchronized void start()
    {
        stop();
        running = true;
        executor = Executors.newSingleThreadScheduledExecutor(r -> {
            Thread t = new Thread(r, "RollBound-Tracker-Telemetry");
            t.setDaemon(true);
            return t;
        });
        scheduledTasks.add(executor.scheduleWithFixedDelay(
                () -> requestSync(true), 5, KEEPALIVE_SECONDS, TimeUnit.SECONDS));
        requestSync(true);
    }

    public synchronized void stop()
    {
        running = false;
        queued.set(false);
        publishOfflineBestEffort();
        cancelScheduledTasks();
        if (executor != null)
        {
            executor.shutdownNow();
            executor = null;
        }
        lastFingerprint = null;
        activePlayerKey = null;
        activeDatabaseUrl = null;
    }

    public void requestSync()
    {
        requestSync(false);
    }

    public void requestSync(boolean force)
    {
        ScheduledExecutorService current = executor;
        if (!running || current == null || current.isShutdown()) return;
        if (!force && !queued.compareAndSet(false, true)) return;
        if (force) queued.set(true);
        ScheduledFuture<?> future = current.schedule(() -> {
            queued.set(false);
            collectAndPublish(force);
        }, force ? 50L : DEBOUNCE_MS, TimeUnit.MILLISECONDS);
        scheduledTasks.add(future);
        scheduledTasks.removeIf(done -> done.isDone() || done.isCancelled());
    }

    private void collectAndPublish(boolean force)
    {
        if (!running) return;
        clientThread.invokeLater(() -> {
            try
            {
                String databaseUrl = databaseClient.normaliseDatabaseUrl(config.firebaseDatabaseUrl());
                if (databaseUrl == null || client.getGameState() != GameState.LOGGED_IN || client.getAccountHash() == -1)
                {
                    return;
                }
                PlayerProgressSnapshot snapshot = collector.collect(getHunterRumoursCompleted());
                if (snapshot == null) return;
                String playerKey = playerKey(databaseUrl, client.getAccountHash());
                JsonObject tree = snapshot.toFirebaseJson();
                JsonObject fingerprintTree = tree.deepCopy();
                fingerprintTree.remove("updatedAt");
                String fingerprint = gson.toJson(fingerprintTree);
                if (!force && playerKey.equals(activePlayerKey) && databaseUrl.equals(activeDatabaseUrl)
                        && fingerprint.equals(lastFingerprint))
                {
                    return;
                }
                activePlayerKey = playerKey;
                activeDatabaseUrl = databaseUrl;
                lastFingerprint = fingerprint;
                databaseClient.patch(databaseUrl, "players/" + playerKey, tree)
                        .exceptionally(error -> {
                            log.warn("Could not publish RollBound tracker progress: {}", error.getMessage());
                            return null;
                        });
            }
            catch (Exception error)
            {
                log.debug("Could not collect RollBound tracker progress", error);
            }
        });
    }

    public void setHunterRumoursCompleted(int count)
    {
        try
        {
            configManager.setRSProfileConfiguration("rollbound", HUNTER_RUMOURS_KEY, Math.max(0, count));
        }
        catch (Exception ignored) {}
        requestSync();
    }

    private int getHunterRumoursCompleted()
    {
        try
        {
            Integer value = configManager.getRSProfileConfiguration("rollbound", HUNTER_RUMOURS_KEY, Integer.class);
            return value == null ? 0 : Math.max(0, value);
        }
        catch (Exception ignored)
        {
            return 0;
        }
    }

    public void publishNpcDropData(NpcDropData data)
    {
        if (!running || data == null || data.getName() == null || data.getDropTableSections() == null) return;
        String databaseUrl = databaseClient.normaliseDatabaseUrl(config.firebaseDatabaseUrl());
        if (databaseUrl == null) return;

        JsonObject npc = new JsonObject();
        npc.addProperty("npcId", data.getNpcId());
        npc.addProperty("name", data.getName());
        npc.addProperty("level", data.getLevel());
        npc.addProperty("updatedAt", System.currentTimeMillis());
        JsonObject drops = new JsonObject();
        for (DropTableSection section : data.getDropTableSections())
        {
            if (section == null || section.getItems() == null) continue;
            for (DropItem item : section.getItems())
            {
                if (item == null || item.getItemId() <= 0) continue;
                JsonObject drop = new JsonObject();
                drop.addProperty("itemId", item.getItemId());
                drop.addProperty("name", item.getName());
                drop.addProperty("rarity", item.getRarity());
                drop.addProperty("section", section.getHeader());
                drops.add(Integer.toString(item.getItemId()), drop);
            }
        }
        npc.add("drops", drops);
        int npcKey = data.getNpcId() > 0 ? data.getNpcId() : Math.abs(data.getName().toLowerCase().hashCode());
        databaseClient.patch(databaseUrl, "trackerSources/npcs/" + npcKey, npc)
                .exceptionally(error -> {
                    log.debug("Could not publish RollBound NPC source data", error);
                    return null;
                });
    }

    public void publishOfflineBestEffort()
    {
        try
        {
            String databaseUrl = activeDatabaseUrl;
            String key = activePlayerKey;
            if (databaseUrl == null || key == null) return;
            JsonObject offline = new JsonObject();
            offline.addProperty("online", false);
            offline.addProperty("updatedAt", System.currentTimeMillis());
            databaseClient.patch(databaseUrl, "players/" + key, offline);
        }
        catch (Exception ignored) {}
    }

    private void cancelScheduledTasks()
    {
        for (ScheduledFuture<?> future : scheduledTasks)
        {
            future.cancel(false);
        }
        scheduledTasks.clear();
    }

    static String playerKey(String databaseUrl, long accountHash)
    {
        try
        {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] bytes = digest.digest((databaseUrl + ":" + accountHash).getBytes(StandardCharsets.UTF_8));
            StringBuilder out = new StringBuilder("p_");
            for (int i = 0; i < 12; i++)
            {
                out.append(String.format("%02x", bytes[i] & 0xff));
            }
            return out.toString();
        }
        catch (Exception ignored)
        {
            return "p_" + Long.toUnsignedString(accountHash);
        }
    }
}

package com.rollbound.ui;

import com.rollbound.drops.DropCache;
import com.rollbound.drops.NpcDropData;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.events.MenuOpened;
import net.runelite.client.eventbus.Subscribe;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.function.Consumer;

/** Adds a Show Drops entry to NPC menus and forwards loaded data to RollBound's sidebar. */
@Singleton
public class DropsMenuListener
{
    private static final Logger log = LoggerFactory.getLogger(DropsMenuListener.class);

    private final Client client;
    private final DropCache dropCache;
    private volatile Consumer<NpcDropData> onDropsLoaded;

    @Inject
    public DropsMenuListener(Client client, DropCache dropCache)
    {
        this.client = client;
        this.dropCache = dropCache;
    }

    public void setOnDropsLoaded(Consumer<NpcDropData> onDropsLoaded)
    {
        this.onDropsLoaded = onDropsLoaded;
    }

    @Subscribe
    public void onMenuOpened(MenuOpened event)
    {
        MenuEntry attackEntry = null;
        NPC target = null;

        for (MenuEntry entry : event.getMenuEntries())
        {
            if (entry.getType() != MenuAction.NPC_SECOND_OPTION || !"Attack".equals(entry.getOption()))
            {
                continue;
            }

            NPC possible = entry.getNpc();
            if (possible != null && possible.getCombatLevel() > 0)
            {
                attackEntry = entry;
                target = possible;
                break;
            }
        }

        if (attackEntry == null || target == null)
        {
            return;
        }

        final int id = target.getId();
        final String name = target.getName();
        final int level = target.getCombatLevel();

        client.getMenu().createMenuEntry(0)
                .setOption("Show Drops")
                .setTarget(attackEntry.getTarget())
                .setIdentifier(attackEntry.getIdentifier())
                .setParam0(attackEntry.getParam0())
                .setParam1(attackEntry.getParam1())
                .setType(MenuAction.RUNELITE)
                .onClick(me -> fetchAndDisplayDrops(id, name, level, 1));
    }

    private void fetchAndDisplayDrops(int id, String name, int level, int attemptsLeft)
    {
        dropCache.get(id, name, level).whenComplete((dropData, error) ->
        {
            if (dropData != null && error == null)
            {
                Consumer<NpcDropData> consumer = onDropsLoaded;
                if (consumer != null)
                {
                    consumer.accept(dropData);
                }
                return;
            }

            if (attemptsLeft > 0)
            {
                fetchAndDisplayDrops(id, name, level, attemptsLeft - 1);
            }
            else
            {
                log.error("Failed to fetch drop data for {}", name, error);
            }
        });
    }
}

package com.rollbound.ui;

import com.rollbound.filters.EnsouledHeadMapping;
import com.rollbound.managers.RolledItemsManager;
import com.rollbound.menus.EnabledUI;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.api.ScriptID;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Dims item icon widgets when item is tradeable and locked.
 *
 * Relevant item widgets are cached and the widget tree is only rebuilt after interface or
 * inventory changes. BeforeRender then only reapplies opacity to the cached item widgets.
 */
@Singleton
public class ItemDimmerController
{
    private static final int[] NO_RELATED_IDS = new int[0];

    private final Client client;
    private final RolledItemsManager rolledItemsManager;
    private final ItemManager itemManager;

    private final List<Widget> itemWidgets = new ArrayList<>();
    private final Set<Widget> itemWidgetSet = java.util.Collections.newSetFromMap(new IdentityHashMap<>());
    private final Map<Integer, Integer> canonicalIdCache = new HashMap<>(256);
    private final Map<Integer, int[]> relatedIdsCache = new HashMap<>(256);
    private final Map<Integer, Boolean> dimDecisionCache = new HashMap<>(256);
    private final Map<Integer, Boolean> groupDimmingCache = new HashMap<>(32);
    private final ConcurrentHashMap<Integer, Boolean> tradeableCache = new ConcurrentHashMap<>();

    private volatile int dimOpacity = 150;
    private volatile boolean enabled = true;
    private volatile boolean rebuildNeeded = true;

    @Inject
    public ItemDimmerController(Client client, RolledItemsManager rolledItemsManager, ItemManager itemManager)
    {
        this.client = client;
        this.rolledItemsManager = rolledItemsManager;
        this.itemManager = itemManager;
    }

    public void setEnabled(boolean enabled)
    {
        if (this.enabled == enabled)
        {
            return;
        }

        this.enabled = enabled;

        if (enabled)
        {
            rebuildNeeded = true;
        }
        else
        {
            restoreItemWidgets();
            clearWidgetCache();
        }
    }

    public void setDimOpacity(int opacity)
    {
        this.dimOpacity = Math.max(0, Math.min(255, opacity));
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        rebuildNeeded = true;
    }

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event)
    {
        rebuildNeeded = true;
    }

    @Subscribe
    public void onWidgetClosed(WidgetClosed event)
    {
        rebuildNeeded = true;
    }

    @Subscribe
    public void onScriptPostFired(ScriptPostFired event)
    {
        switch (event.getScriptId())
        {
            case ScriptID.INVENTORY_DRAWITEM:
            case ScriptID.INTERFACE_INV_DRAW_SLOT_BIG:
                cacheItemWidget(client.getScriptActiveWidget());
                break;

            case ScriptID.BANKMAIN_BUILD:
            case ScriptID.BANKMAIN_FINISHBUILDING:
            case ScriptID.BANKMAIN_SEARCH_REFRESH:
            case ScriptID.BANK_DEPOSITBOX_INIT:
            case ScriptID.GROUP_IRONMAN_STORAGE_BUILD:
            case ScriptID.RAIDS_STORAGE_PRIVATE_ITEMS:
            case ScriptID.SEED_VAULT_BUILD:
                rebuildNeeded = true;
                break;

            default:
                break;
        }
    }

    /**
     * Reapply dimming immediately before RuneLite draws the frame, without rescanning the entire
     * widget tree unless an inventory/interface event has invalidated the cache.
     */
    @Subscribe
    public void onBeforeRender(BeforeRender event)
    {
        if (!enabled || client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }

        if (rebuildNeeded)
        {
            rebuildItemWidgetCache();
        }

        dimDecisionCache.clear();

        for (int i = 0; i < itemWidgets.size(); i++)
        {
            applyDimming(itemWidgets.get(i));
        }
    }

    private void rebuildItemWidgetCache()
    {
        itemWidgets.clear();
        itemWidgetSet.clear();
        groupDimmingCache.clear();

        Widget[] roots = client.getWidgetRoots();
        if (roots != null)
        {
            for (Widget root : roots)
            {
                collectItemWidgets(root);
            }
        }

        rebuildNeeded = false;
    }

    private void collectItemWidgets(Widget widget)
    {
        if (widget == null || widget.isHidden())
        {
            return;
        }

        if ((widget.getId() >>> 16) == InterfaceID.COLLECTION)
        {
            return;
        }

        if (widget.getItemId() > 0)
        {
            cacheItemWidget(widget);
        }

        Widget[] dynamicChildren = widget.getDynamicChildren();
        if (dynamicChildren != null)
        {
            for (Widget child : dynamicChildren)
            {
                collectItemWidgets(child);
            }
        }

        Widget[] staticChildren = widget.getStaticChildren();
        if (staticChildren != null)
        {
            for (Widget child : staticChildren)
            {
                collectItemWidgets(child);
            }
        }

        Widget[] nestedChildren = widget.getNestedChildren();
        if (nestedChildren != null)
        {
            for (Widget child : nestedChildren)
            {
                collectItemWidgets(child);
            }
        }
    }

    private void cacheItemWidget(Widget widget)
    {
        if (widget == null || widget.getItemId() <= 0)
        {
            return;
        }

        if ((widget.getId() >>> 16) == InterfaceID.COLLECTION)
        {
            return;
        }

        if (itemWidgetSet.add(widget))
        {
            itemWidgets.add(widget);
        }
    }

    private void applyDimming(Widget widget)
    {
        if (widget == null || widget.isHidden())
        {
            return;
        }

        int itemId = widget.getItemId();
        if (itemId <= 0 || isBankPlaceholderWidget(widget))
        {
            return;
        }

        int groupId = widget.getId() >>> 16;
        if (!shouldDimGroup(groupId))
        {
            if (widget.getOpacity() != 0)
            {
                widget.setOpacity(0);
            }
            return;
        }

        int target = shouldDimMemoized(itemId) ? dimOpacity : 0;
        if (widget.getOpacity() != target)
        {
            widget.setOpacity(target);
        }
    }

    private boolean shouldDimGroup(int groupId)
    {
        Boolean cached = groupDimmingCache.get(groupId);
        if (cached != null)
        {
            return cached;
        }

        EnabledUI ui = EnabledUI.fromGroupId(groupId);
        boolean result = ui == null || ui.isGreyLockedItems();
        groupDimmingCache.put(groupId, result);
        return result;
    }

    private boolean shouldDimMemoized(int rawItemId)
    {
        int mappedItemId = EnsouledHeadMapping.toTradeableId(rawItemId);
        int canonicalItemId = canonicalize(mappedItemId);
        if (canonicalItemId <= 0)
        {
            return false;
        }

        Boolean cached = dimDecisionCache.get(canonicalItemId);
        if (cached != null)
        {
            return cached;
        }

        boolean result = isGeTradeableCanonical(canonicalItemId)
                && !isRolled(mappedItemId, canonicalItemId);
        dimDecisionCache.put(canonicalItemId, result);
        return result;
    }

    private int canonicalize(int itemId)
    {
        Integer cached = canonicalIdCache.get(itemId);
        if (cached != null)
        {
            return cached;
        }

        int canonicalItemId;
        try
        {
            canonicalItemId = itemManager.canonicalize(itemId);
        }
        catch (Exception error)
        {
            canonicalItemId = itemId;
        }

        canonicalIdCache.put(itemId, canonicalItemId);
        return canonicalItemId;
    }

    private boolean isRolled(int normalizedItemId, int canonicalItemId)
    {
        if (rolledItemsManager == null)
        {
            return true;
        }

        try
        {
            if (normalizedItemId > 0 && rolledItemsManager.isRolled(normalizedItemId))
            {
                return true;
            }
            if (canonicalItemId > 0
                    && canonicalItemId != normalizedItemId
                    && rolledItemsManager.isRolled(canonicalItemId))
            {
                return true;
            }

            for (int relatedId : getRelatedIds(normalizedItemId))
            {
                if (rolledItemsManager.isRolled(relatedId))
                {
                    return true;
                }
            }

            if (canonicalItemId != normalizedItemId)
            {
                for (int relatedId : getRelatedIds(canonicalItemId))
                {
                    if (rolledItemsManager.isRolled(relatedId))
                    {
                        return true;
                    }
                }
            }
        }
        catch (Exception error)
        {
            return true;
        }

        return false;
    }

    private int[] getRelatedIds(int itemId)
    {
        if (itemId <= 0)
        {
            return NO_RELATED_IDS;
        }

        int[] cached = relatedIdsCache.get(itemId);
        if (cached != null)
        {
            return cached;
        }

        int[] relatedIds = NO_RELATED_IDS;

        try
        {
            ItemComposition composition = itemManager.getItemComposition(itemId);
            if (composition != null)
            {
                int placeholderId = composition.getPlaceholderTemplateId() != -1
                        ? composition.getPlaceholderId()
                        : -1;
                int linkedNoteId = composition.getLinkedNoteId();

                boolean hasPlaceholder = placeholderId > 0 && placeholderId != itemId;
                boolean hasLinkedNote = linkedNoteId > 0
                        && linkedNoteId != itemId
                        && linkedNoteId != placeholderId;

                if (hasPlaceholder && hasLinkedNote)
                {
                    relatedIds = new int[]{placeholderId, linkedNoteId};
                }
                else if (hasPlaceholder)
                {
                    relatedIds = new int[]{placeholderId};
                }
                else if (hasLinkedNote)
                {
                    relatedIds = new int[]{linkedNoteId};
                }
            }
        }
        catch (Exception ignored)
        {
        }

        relatedIdsCache.put(itemId, relatedIds);
        return relatedIds;
    }

    private void restoreItemWidgets()
    {
        for (int i = 0; i < itemWidgets.size(); i++)
        {
            Widget widget = itemWidgets.get(i);
            if (widget != null
                    && widget.getItemId() > 0
                    && !isBankPlaceholderWidget(widget)
                    && widget.getOpacity() != 0)
            {
                widget.setOpacity(0);
            }
        }
    }

    private void clearWidgetCache()
    {
        itemWidgets.clear();
        itemWidgetSet.clear();
        groupDimmingCache.clear();
        dimDecisionCache.clear();
        rebuildNeeded = true;
    }

    private boolean isBankPlaceholderWidget(Widget widget)
    {
        return widget.getItemId() > 0 && widget.getItemQuantity() == 0;
    }

    private boolean isGeTradeableCanonical(int canonicalItemId)
    {
        try
        {
            Boolean cached = tradeableCache.get(canonicalItemId);
            if (cached != null)
            {
                return cached;
            }

            ItemComposition composition = itemManager.getItemComposition(canonicalItemId);
            boolean tradeable = composition != null && composition.isGeTradeable();
            tradeableCache.put(canonicalItemId, tradeable);
            return tradeable;
        }
        catch (Exception error)
        {
            return false;
        }
    }
}

package com.rollbound.ui;

import com.rollbound.drops.DropCache;
import com.rollbound.drops.NpcDropData;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.Objects;
import java.util.concurrent.CompletableFuture;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

/**
 * Resolves the Wiki's broad title search into real NPC drop-table results.
 *
 * The Wiki search itself can return ordinary pages such as items or outfits. Those
 * candidates are never shown directly. Each candidate is loaded through DropCache
 * and only pages that resolve to a non-empty NPC drop table are returned.
 *
 * This preserves the old RollBound Drops search behaviour, including separate
 * combat-level/page variants for NPCs which have more than one drop table.
 */
@Singleton
public class NpcSearchService
{
    private static final Pattern ID_LEVEL_PATTERN = Pattern.compile("^(\\d+)\\s+(?:lvl|level)?\\s*(\\d+)$", Pattern.CASE_INSENSITIVE);
    private static final Pattern NAME_LVL_PATTERN = Pattern.compile("^(.*)\\s+(?:lvl|level)\\s*(\\d+)$", Pattern.CASE_INSENSITIVE);
    private static final Pattern LVL_NAME_PATTERN = Pattern.compile("^(?:lvl|level)\\s*(\\d+)\\s+(.*)$", Pattern.CASE_INSENSITIVE);
    private static final Pattern NAME_NUM_PATTERN = Pattern.compile("^(.*\\D)\\s+(\\d+)$");
    private static final Pattern NUM_NAME_PATTERN = Pattern.compile("^(\\d+)\\s+(\\D.*)$");
    private static final int MAX_SEARCH_CANDIDATES = 50;

    private final DropCache dropCache;

    @Inject
    public NpcSearchService(DropCache dropCache)
    {
        this.dropCache = dropCache;
    }

    private static final class ParsedQuery
    {
        Integer npcId;
        Integer level;
        String name;
    }

    private static ParsedQuery parse(String query)
    {
        if (query == null)
        {
            return null;
        }

        String lower = query.trim().toLowerCase(Locale.ROOT);
        if (lower.isEmpty())
        {
            return null;
        }

        ParsedQuery parsed = new ParsedQuery();
        Matcher matcher;

        if (lower.matches("\\d+"))
        {
            parsed.npcId = Integer.valueOf(lower);
            return parsed;
        }
        if ((matcher = ID_LEVEL_PATTERN.matcher(lower)).matches())
        {
            parsed.npcId = Integer.valueOf(matcher.group(1));
            parsed.level = Integer.valueOf(matcher.group(2));
            return parsed;
        }
        if ((matcher = NAME_LVL_PATTERN.matcher(lower)).matches())
        {
            parsed.name = matcher.group(1).trim();
            parsed.level = Integer.valueOf(matcher.group(2));
            return parsed;
        }
        if ((matcher = LVL_NAME_PATTERN.matcher(lower)).matches())
        {
            parsed.level = Integer.valueOf(matcher.group(1));
            parsed.name = matcher.group(2).trim();
            return parsed;
        }
        if ((matcher = NAME_NUM_PATTERN.matcher(lower)).matches())
        {
            parsed.name = matcher.group(1).trim();
            parsed.level = Integer.valueOf(matcher.group(2));
            return parsed;
        }
        if ((matcher = NUM_NAME_PATTERN.matcher(lower)).matches())
        {
            parsed.level = Integer.valueOf(matcher.group(1));
            parsed.name = matcher.group(2).trim();
            return parsed;
        }

        parsed.name = lower;
        return parsed;
    }

    /** Search by partial name, combat level, or NPC ID without blocking Swing. */
    public CompletableFuture<List<NpcDropData>> search(String query)
    {
        ParsedQuery parsed = parse(query);
        if (parsed == null)
        {
            return CompletableFuture.completedFuture(Collections.emptyList());
        }

        // Pure NPC ID lookup. An exact ID is passed straight through to Special:Lookup.
        if (parsed.npcId != null && parsed.name == null)
        {
            int level = parsed.level == null ? 0 : parsed.level;
            return dropCache.get(parsed.npcId, "", level)
                    .thenApply(data -> data == null || data.getDropTableSections() == null
                            || data.getDropTableSections().isEmpty()
                            ? Collections.emptyList()
                            : Collections.singletonList(data));
        }

        String nameFilter = parsed.name == null ? "" : parsed.name;
        int levelFilter = parsed.level == null ? -1 : parsed.level;

        return dropCache.searchNpcNames(nameFilter)
                .thenCompose(names ->
                {
                    List<String> candidates = names == null
                            ? Collections.emptyList()
                            : names.stream()
                                    .filter(Objects::nonNull)
                                    .map(String::trim)
                                    .filter(name -> !name.isEmpty())
                                    // Keep the expensive drop-table fetches focused on titles that
                                    // actually contain the user's text. The Wiki lookup itself is
                                    // deliberately broader (50 candidates) so shorter searches do
                                    // not lose valid NPCs simply because unrelated pages ranked higher.
                                    .filter(name -> nameFilter.isEmpty() || safeLower(name).contains(nameFilter))
                                    .limit(MAX_SEARCH_CANDIDATES)
                                    .collect(Collectors.toList());
                    return fetchAll(candidates, levelFilter > -1 ? levelFilter : 0);
                })
                .thenApply(results ->
                {
                    List<NpcDropData> filtered = results;

                    if (parsed.npcId != null)
                    {
                        filtered = filtered.stream()
                                .filter(data -> data.getNpcId() == parsed.npcId)
                                .collect(Collectors.toList());
                    }

                    final int wantedLevel = levelFilter;
                    filtered = filtered.stream()
                            .filter(data -> wantedLevel < 0 || data.getLevel() == wantedLevel)
                            .sorted(Comparator
                                    .comparingInt((NpcDropData data) -> levenshtein(
                                            safeLower(data.getName()), nameFilter))
                                    .thenComparing(data -> safeLower(data.getName()))
                                    .thenComparingInt(NpcDropData::getLevel))
                            .collect(Collectors.toList());

                    // A broad Wiki query can lead to the same resolved page more than once.
                    // De-duplicate by the values visible to the user while preserving order.
                    List<NpcDropData> unique = new ArrayList<>();
                    for (NpcDropData candidate : filtered)
                    {
                        boolean duplicate = unique.stream().anyMatch(existing ->
                                Objects.equals(existing.getName(), candidate.getName())
                                        && existing.getLevel() == candidate.getLevel()
                                        && existing.getNpcId() == candidate.getNpcId());
                        if (!duplicate)
                        {
                            unique.add(candidate);
                        }
                    }
                    return unique;
                });
    }

    private CompletableFuture<List<NpcDropData>> fetchAll(List<String> names, int level)
    {
        if (names.isEmpty())
        {
            return CompletableFuture.completedFuture(Collections.emptyList());
        }

        List<CompletableFuture<List<NpcDropData>>> futures = names.stream()
                .filter(Objects::nonNull)
                .map(String::trim)
                .filter(name -> !name.isEmpty())
                .map(name -> dropCache.searchNpcVariants(name, level))
                .collect(Collectors.toList());

        if (futures.isEmpty())
        {
            return CompletableFuture.completedFuture(Collections.emptyList());
        }

        return CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]))
                .thenApply(ignored -> futures.stream()
                        .flatMap(future -> future.join().stream())
                        .filter(Objects::nonNull)
                        .filter(data -> data.getDropTableSections() != null && !data.getDropTableSections().isEmpty())
                        .collect(Collectors.toList()));
    }

    private static String safeLower(String value)
    {
        return value == null ? "" : value.toLowerCase(Locale.ROOT);
    }

    private static int levenshtein(String a, String b)
    {
        int[][] dp = new int[a.length() + 1][b.length() + 1];
        for (int i = 0; i <= a.length(); i++)
        {
            dp[i][0] = i;
        }
        for (int j = 0; j <= b.length(); j++)
        {
            dp[0][j] = j;
        }
        for (int i = 1; i <= a.length(); i++)
        {
            for (int j = 1; j <= b.length(); j++)
            {
                dp[i][j] = Math.min(
                        Math.min(dp[i - 1][j] + 1, dp[i][j - 1] + 1),
                        dp[i - 1][j - 1] + (a.charAt(i - 1) == b.charAt(j - 1) ? 0 : 1));
            }
        }
        return dp[a.length()][b.length()];
    }
}

package com.rollbound.ui;

import com.rollbound.RollBoundConfig;
import com.rollbound.drops.DropCache;
import com.rollbound.drops.DropItem;
import com.rollbound.drops.DropTableSection;
import com.rollbound.drops.NpcDropData;
import com.rollbound.managers.ObtainedItemsManager;
import net.runelite.client.game.ItemManager;

import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JProgressBar;
import javax.swing.JTextField;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import java.awt.AlphaComposite;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * RollBound sidebar view for NPC drops.
 *
 * Drop items are displayed as RuneScape item icons. Items the shared RollBound
 * group has obtained are shown at full opacity; unobtained items are dimmed.
 */
public final class RollBoundDropsPanel extends JPanel
{
    private static final int GRID_COLUMNS = 4;
    private static final int ICON_SIZE = 32;
    private static final float UNOBTAINED_ALPHA = 0.38f;
    private static final Color OBTAINED_BORDER = new Color(74, 170, 92);
    private static final Color OBTAINED_BACKGROUND = new Color(38, 66, 43);
    private static final Color UNOBTAINED_BORDER = new Color(86, 86, 86);
    private static final Color UNOBTAINED_BACKGROUND = new Color(38, 38, 38);

    private final DropCache dropCache;
    private final NpcSearchService npcSearchService;
    private final ObtainedItemsManager obtainedItemsManager;
    private final ItemManager itemManager;
    private final RollBoundConfig config;

    private final JTextField searchField = new JTextField();
    private final JLabel statusLabel = new JLabel("Search for an NPC");
    private final JProgressBar progressBar = new JProgressBar();
    private final JPanel content = new JPanel();
    private volatile NpcDropData currentData;

    public RollBoundDropsPanel(
            DropCache dropCache,
            NpcSearchService npcSearchService,
            ObtainedItemsManager obtainedItemsManager,
            ItemManager itemManager,
            RollBoundConfig config)
    {
        this.dropCache = dropCache;
        this.npcSearchService = npcSearchService;
        this.obtainedItemsManager = obtainedItemsManager;
        this.itemManager = itemManager;
        this.config = config;
        init();
    }

    private void init()
    {
        setLayout(new BorderLayout(0, 8));
        setOpaque(false);

        JPanel search = new JPanel(new BorderLayout(6, 0));
        search.setOpaque(false);
        searchField.setToolTipText("Search NPC names from the Old School RuneScape Wiki");
        searchField.addActionListener(e -> search());
        JButton button = new JButton("Search");
        button.addActionListener(e -> search());
        search.add(searchField, BorderLayout.CENTER);
        search.add(button, BorderLayout.EAST);

        statusLabel.setForeground(new Color(220, 220, 220));
        statusLabel.setFont(statusLabel.getFont().deriveFont(Font.BOLD, 13f));
        statusLabel.setHorizontalAlignment(SwingConstants.CENTER);
        statusLabel.setAlignmentX(CENTER_ALIGNMENT);
        statusLabel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 22));

        progressBar.setStringPainted(true);
        progressBar.setBorderPainted(false);
        progressBar.setVisible(false);
        progressBar.setAlignmentX(CENTER_ALIGNMENT);
        progressBar.setMaximumSize(new Dimension(Integer.MAX_VALUE, 22));
        progressBar.setPreferredSize(new Dimension(180, 22));
        progressBar.setFont(progressBar.getFont().deriveFont(Font.BOLD, 13f));
        progressBar.setForeground(OBTAINED_BORDER);
        progressBar.setBackground(new Color(45, 45, 45));

        JPanel top = new JPanel();
        top.setOpaque(false);
        top.setLayout(new BoxLayout(top, BoxLayout.Y_AXIS));
        top.add(search);
        top.add(Box.createVerticalStrut(7));
        top.add(statusLabel);
        top.add(Box.createVerticalStrut(5));
        top.add(progressBar);
        add(top, BorderLayout.NORTH);

        content.setOpaque(false);
        content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
        add(content, BorderLayout.CENTER);
    }

    private void search()
    {
        String query = searchField.getText() == null ? "" : searchField.getText().trim();
        if (query.isEmpty())
        {
            return;
        }

        currentData = null;
        progressBar.setVisible(false);
        statusLabel.setFont(statusLabel.getFont().deriveFont(Font.PLAIN, 11f));
        statusLabel.setForeground(new Color(180, 180, 180));
        statusLabel.setText("Searching…");
        content.removeAll();
        content.revalidate();
        content.repaint();

        npcSearchService.search(query).whenComplete((results, error) -> SwingUtilities.invokeLater(() ->
        {
            if (error != null)
            {
                statusLabel.setText("Could not search NPCs.");
                return;
            }
            if (results == null || results.isEmpty())
            {
                statusLabel.setText("No matching NPCs with drop tables found.");
                return;
            }

            statusLabel.setText("Select an NPC:");
            int shown = 0;
            for (NpcDropData npc : results)
            {
                String label = npc.getName() == null ? "NPC" : npc.getName();
                if (npc.getLevel() > 0)
                {
                    label += " (Lvl " + npc.getLevel() + ")";
                }

                JButton result = new JButton(label);
                result.setHorizontalAlignment(JButton.LEFT);
                result.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
                result.addActionListener(e -> showDrops(npc));
                content.add(result);
                content.add(Box.createVerticalStrut(3));
                if (++shown >= 20)
                {
                    break;
                }
            }
            content.revalidate();
            content.repaint();
        }));
    }

    public void showDrops(NpcDropData data)
    {
        if (!SwingUtilities.isEventDispatchThread())
        {
            SwingUtilities.invokeLater(() -> showDrops(data));
            return;
        }

        currentData = data;
        content.removeAll();
        if (data == null)
        {
            progressBar.setVisible(false);
            statusLabel.setFont(statusLabel.getFont().deriveFont(Font.PLAIN, 11f));
            statusLabel.setForeground(new Color(180, 180, 180));
            statusLabel.setText("No drop data loaded.");
            content.revalidate();
            content.repaint();
            return;
        }

        String title = data.getName() == null ? "NPC" : data.getName();
        if (data.getLevel() > 0)
        {
            title += " (Lvl " + data.getLevel() + ")";
        }
        statusLabel.setFont(statusLabel.getFont().deriveFont(Font.BOLD, 14f));
        statusLabel.setForeground(new Color(220, 220, 220));
        statusLabel.setText(title);

        List<VisibleSection> visibleSections = buildVisibleSections(data.getDropTableSections());
        updateProgress(visibleSections);

        for (VisibleSection section : visibleSections)
        {
            addSection(section);
        }

        if (content.getComponentCount() == 0)
        {
            progressBar.setVisible(false);
            JLabel empty = new JLabel("No drop-table entries available.");
            empty.setForeground(new Color(180, 180, 180));
            content.add(empty);
        }
        content.revalidate();
        content.repaint();
    }

    public void refresh()
    {
        NpcDropData data = currentData;
        if (data != null)
        {
            showDrops(data);
        }
    }

    private boolean showSection(String header)
    {
        String value = header == null ? "" : header.toLowerCase(Locale.ROOT);
        if (!config.showRareDropTable() && value.contains("rare drop table"))
        {
            return false;
        }
        return config.showGemDropTable() || !value.contains("gem drop table");
    }

    private List<VisibleSection> buildVisibleSections(List<DropTableSection> sections)
    {
        List<VisibleSection> visible = new ArrayList<>();
        if (sections == null)
        {
            return visible;
        }

        for (DropTableSection section : sections)
        {
            if (section == null || !showSection(section.getHeader()))
            {
                continue;
            }

            List<DropItem> items = sortedValidItems(section);
            if (!items.isEmpty())
            {
                visible.add(new VisibleSection(
                        section.getHeader() == null ? "Drops" : section.getHeader(),
                        items));
            }
        }
        return visible;
    }

    private List<DropItem> sortedValidItems(DropTableSection section)
    {
        Map<Integer, DropItem> unique = new LinkedHashMap<>();
        if (section.getItems() != null)
        {
            for (DropItem item : section.getItems())
            {
                if (item != null && item.getItemId() > 0)
                {
                    unique.putIfAbsent(item.getItemId(), item);
                }
            }
        }

        List<DropItem> items = new ArrayList<>(unique.values());
        if (config.sortDropsByRarity())
        {
            items.sort(Comparator.comparingDouble(DropItem::getRarityValue)
                    .thenComparing(item -> item.getName() == null ? "" : item.getName()));
        }
        else
        {
            items.sort(Comparator.comparingInt(DropItem::getItemId));
        }
        return items;
    }

    private void updateProgress(List<VisibleSection> sections)
    {
        Set<Integer> uniqueIds = new LinkedHashSet<>();
        for (VisibleSection section : sections)
        {
            for (DropItem item : section.items)
            {
                uniqueIds.add(item.getItemId());
            }
        }

        int obtained = 0;
        for (int itemId : uniqueIds)
        {
            if (obtainedItemsManager.isObtained(itemId))
            {
                obtained++;
            }
        }

        int total = uniqueIds.size();
        progressBar.setMinimum(0);
        progressBar.setMaximum(Math.max(1, total));
        progressBar.setValue(obtained);
        progressBar.setString(obtained + "/" + total + " obtained");
        progressBar.setVisible(total > 0);
    }

    private void addSection(VisibleSection section)
    {
        if (content.getComponentCount() > 0)
        {
            content.add(Box.createVerticalStrut(7));

            JPanel divider = new JPanel();
            divider.setBackground(new Color(62, 62, 62));
            divider.setMaximumSize(new Dimension(Integer.MAX_VALUE, 1));
            divider.setPreferredSize(new Dimension(1, 1));
            divider.setAlignmentX(LEFT_ALIGNMENT);
            content.add(divider);

            content.add(Box.createVerticalStrut(5));
        }

        JLabel heading = new JLabel(section.header);
        heading.setForeground(new Color(205, 205, 205));
        heading.setFont(heading.getFont().deriveFont(Font.BOLD, 11f));
        heading.setBorder(BorderFactory.createEmptyBorder(2, 2, 5, 2));
        heading.setAlignmentX(LEFT_ALIGNMENT);
        content.add(heading);

        JPanel grid = new JPanel(new GridLayout(0, GRID_COLUMNS, 4, 4));
        grid.setOpaque(false);
        grid.setAlignmentX(LEFT_ALIGNMENT);
        grid.setBorder(BorderFactory.createEmptyBorder(0, 2, 2, 2));
        int rows = (section.items.size() + GRID_COLUMNS - 1) / GRID_COLUMNS;
        grid.setMaximumSize(new Dimension(Integer.MAX_VALUE, Math.max(ICON_SIZE + 8, rows * (ICON_SIZE + 8))));

        for (DropItem item : section.items)
        {
            grid.add(buildDropIcon(item));
        }

        content.add(grid);
    }

    private JPanel buildDropIcon(DropItem item)
    {
        boolean obtained = obtainedItemsManager.isObtained(item.getItemId());

        JPanel cell = new JPanel(new BorderLayout());
        cell.setOpaque(true);
        cell.setBackground(obtained ? OBTAINED_BACKGROUND : UNOBTAINED_BACKGROUND);
        cell.setBorder(BorderFactory.createLineBorder(
                obtained ? OBTAINED_BORDER : UNOBTAINED_BORDER,
                obtained ? 2 : 1));
        cell.setPreferredSize(new Dimension(44, 42));
        cell.setMinimumSize(new Dimension(44, 42));

        OpacityLabel icon = new OpacityLabel(obtained ? 1f : UNOBTAINED_ALPHA);
        icon.setHorizontalAlignment(SwingConstants.CENTER);
        icon.setVerticalAlignment(SwingConstants.CENTER);
        icon.setPreferredSize(new Dimension(ICON_SIZE, ICON_SIZE));
        icon.setToolTipText(buildTooltip(item, obtained));

        try
        {
            itemManager.getImage(item.getItemId()).addTo(icon);
        }
        catch (Exception ignored)
        {
            icon.setText("?");
            icon.setForeground(new Color(180, 180, 180));
        }

        cell.setToolTipText(icon.getToolTipText());
        cell.add(icon, BorderLayout.CENTER);
        return cell;
    }

    private String buildTooltip(DropItem item, boolean obtained)
    {
        String name = item.getName() == null || item.getName().isBlank()
                ? "Unknown item" : item.getName();
        String rarity = item.getOneOverRarity();
        if (rarity == null || rarity.isBlank())
        {
            rarity = "Unknown";
        }
        return "<html><b>" + escapeHtml(name) + "</b><br>Rate: " + escapeHtml(rarity)
                + "<br>" + (obtained ? "Obtained" : "Not obtained") + "</html>";
    }

    private static String escapeHtml(String text)
    {
        return text.replace("&", "&amp;")
                .replace("<", "&lt;")
                .replace(">", "&gt;")
                .replace("\"", "&quot;");
    }

    private static final class VisibleSection
    {
        private final String header;
        private final List<DropItem> items;

        private VisibleSection(String header, List<DropItem> items)
        {
            this.header = header;
            this.items = items;
        }
    }

    /** JLabel that applies alpha to the item icon while preserving normal Swing tooltips. */
    private static final class OpacityLabel extends JLabel
    {
        private final float alpha;

        private OpacityLabel(float alpha)
        {
            this.alpha = Math.max(0f, Math.min(1f, alpha));
            setOpaque(false);
        }

        @Override
        protected void paintComponent(Graphics graphics)
        {
            Graphics2D g2 = (Graphics2D) graphics.create();
            try
            {
                g2.setComposite(AlphaComposite.SrcOver.derive(alpha));
                super.paintComponent(g2);
            }
            finally
            {
                g2.dispose();
            }
        }
    }
