package com.rollbound.firebase;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.junit.Test;

import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;

import static org.junit.Assert.*;

public class FirebaseDatabaseClientTest
{
    @Test
    public void patchUsesSilentResponseToAvoidEchoBandwidth() throws Exception
    {
        AtomicReference<Request> captured = new AtomicReference<>();
        OkHttpClient http = new OkHttpClient.Builder()
                .addInterceptor(chain -> {
                    captured.set(chain.request());
                    return new Response.Builder()
                            .request(chain.request())
                            .protocol(Protocol.HTTP_1_1)
                            .code(204)
                            .message("No Content")
                            .body(ResponseBody.create(null, new byte[0]))
                            .build();
                })
                .build();

        FirebaseDatabaseClient client = new FirebaseDatabaseClient(http, new Gson());
        JsonObject payload = new JsonObject();
        payload.addProperty("online", true);

        JsonElement result = client.patch("https://example.firebaseio.com", "players/p1", payload)
                .get(2, TimeUnit.SECONDS);

        assertNotNull(captured.get());
        assertEquals("PATCH", captured.get().method());
        assertEquals("silent", captured.get().url().queryParameter("print"));
        assertEquals("RuneLite-RollBound/5.1.8", captured.get().header("User-Agent"));
        assertTrue(result.isJsonNull());
    }
}

package com.rollbound.firebase;

import com.google.gson.JsonObject;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class FirebaseGameRulesTest
{
    @Test
    public void retiredRulesAreIgnoredAndResetFalse()
    {
        JsonObject oldRules = new JsonObject();
        oldRules.addProperty("freeToPlay", true);
        oldRules.addProperty("includeF2PTradeOnlyItems", true);
        oldRules.addProperty("enableItemSets", true);
        oldRules.addProperty("enableFlatpacks", true);
        oldRules.addProperty("requireWeaponPoison", true);
        oldRules.addProperty("requireRolledUnlockedForGe", false);

        FirebaseGameRules rules = FirebaseGameRules.fromJson(oldRules);
        assertNotNull(rules);
        assertFalse(rules.isRequireRolledUnlockedForGe());

        JsonObject patch = FirebaseGameRules.legacyRulesOffPatch(oldRules);
        assertFalse(patch.get("gameRules/freeToPlay").getAsBoolean());
        assertFalse(patch.get("gameRules/includeF2PTradeOnlyItems").getAsBoolean());
        assertFalse(patch.get("gameRules/enableItemSets").getAsBoolean());
        assertFalse(patch.get("gameRules/enableFlatpacks").getAsBoolean());
        assertFalse(patch.get("gameRules/requireWeaponPoison").getAsBoolean());
    }

    @Test
    public void currentSerialisationKeepsRetiredRulesOff()
    {
        FirebaseGameRules rules = new FirebaseGameRules(
                FirebaseGameRules.SCHEMA_VERSION, true, 123L);
        JsonObject json = rules.toJson();

        assertTrue(json.get("requireRolledUnlockedForGe").getAsBoolean());
        assertFalse(json.get("freeToPlay").getAsBoolean());
        assertFalse(json.get("includeF2PTradeOnlyItems").getAsBoolean());
        assertFalse(json.get("enableItemSets").getAsBoolean());
        assertFalse(json.get("enableFlatpacks").getAsBoolean());
        assertFalse(json.get("requireWeaponPoison").getAsBoolean());
    }
}

package com.rollbound.firebase;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import org.junit.Test;

import static org.junit.Assert.*;

public class FirebaseRealtimeStateTest
{
    private final FirebaseRealtimeState state = new FirebaseRealtimeState(new Gson());

    @Test
    public void initialRootPutHydratesState()
    {
        FirebaseRealtimeState.ApplyResult result = state.apply("put",
                "{\"path\":\"/\",\"data\":{\"obtainedItems\":{\"100\":1},\"players\":{\"p1\":{\"online\":true}}}}" );

        assertTrue(result.isRollBoundStateChanged());
        assertTrue(state.isInitialised());
        assertEquals(1L, result.getSnapshot().getAsJsonObject("obtainedItems").get("100").getAsLong());
        assertTrue(state.snapshot().has("players"));
    }

    @Test
    public void playerOnlyPatchDoesNotRequestRollBoundReapply()
    {
        state.apply("put", "{\"path\":\"/\",\"data\":{\"obtainedItems\":{\"100\":1},\"players\":{}}}");

        FirebaseRealtimeState.ApplyResult result = state.apply("patch",
                "{\"path\":\"/players/p1\",\"data\":{\"online\":true,\"updatedAt\":123}}" );

        assertFalse(result.isRollBoundStateChanged());
        assertNull(result.getSnapshot());
        JsonObject player = state.snapshot().getAsJsonObject("players").getAsJsonObject("p1");
        assertTrue(player.get("online").getAsBoolean());
        assertEquals(123L, player.get("updatedAt").getAsLong());
    }

    @Test
    public void rootMultiLocationPatchHandlesSlashKeys()
    {
        state.apply("put", "{\"path\":\"/\",\"data\":{\"obtainedItems\":{},\"rolledItems\":{},\"players\":{}}}");

        FirebaseRealtimeState.ApplyResult result = state.apply("patch",
                "{\"path\":\"/\",\"data\":{\"obtainedItems/200\":456,\"rolledItems/300\":789,\"players/p1/online\":true}}" );

        assertTrue(result.isRollBoundStateChanged());
        JsonObject snapshot = result.getSnapshot();
        assertEquals(456L, snapshot.getAsJsonObject("obtainedItems").get("200").getAsLong());
        assertEquals(789L, snapshot.getAsJsonObject("rolledItems").get("300").getAsLong());
        assertTrue(state.snapshot().getAsJsonObject("players").getAsJsonObject("p1").get("online").getAsBoolean());
    }

    @Test
    public void putNullDeletesNestedValue()
    {
        state.apply("put", "{\"path\":\"/\",\"data\":{\"liveRolls\":{\"event1\":{\"pickedItemId\":10}}}}" );

        FirebaseRealtimeState.ApplyResult result = state.apply("put",
                "{\"path\":\"/liveRolls/event1\",\"data\":null}" );

        assertTrue(result.isRollBoundStateChanged());
        assertFalse(result.getSnapshot().getAsJsonObject("liveRolls").has("event1"));
    }

    @Test
    public void reconnectRootPutReplacesStaleMirror()
    {
        state.apply("put", "{\"path\":\"/\",\"data\":{\"obtainedItems\":{\"100\":1},\"players\":{\"old\":{}}}}" );
        state.apply("put", "{\"path\":\"/\",\"data\":{\"obtainedItems\":{\"200\":2}}}" );

        JsonObject snapshot = state.snapshot();
        assertFalse(snapshot.has("players"));
        assertFalse(snapshot.getAsJsonObject("obtainedItems").has("100"));
        assertEquals(2L, snapshot.getAsJsonObject("obtainedItems").get("200").getAsLong());
    }
}

package com.rollbound.firebase;

import org.junit.Test;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import static org.junit.Assert.assertEquals;

public class FirebaseRollEventTest
{
    @Test
    public void orderedBatchIgnoresArrivalOrder()
    {
        long at = 123456789L;
        String batch = "batch-1";

        FirebaseRollEvent a = new FirebaseRollEvent("z-event", at, "Player", 100, false,
                Arrays.asList(1, 2), batch, 0, 3);
        FirebaseRollEvent b = new FirebaseRollEvent("a-event", at, "Player", 200, false,
                Arrays.asList(3, 4), batch, 1, 3);
        FirebaseRollEvent c = new FirebaseRollEvent("m-event", at, "Player", 300, false,
                Arrays.asList(5, 6), batch, 2, 3);

        // Simulate Firebase/object iteration arriving B, C, A.
        List<FirebaseRollEvent> shuffled = new ArrayList<>(Arrays.asList(b, c, a));
        shuffled.sort(FirebaseRollEvent::compareForPlayback);

        assertEquals("z-event", shuffled.get(0).getEventId());
        assertEquals("a-event", shuffled.get(1).getEventId());
        assertEquals("m-event", shuffled.get(2).getEventId());
    }

    @Test
    public void legacyTimestampTiesAreDeterministic()
    {
        long at = 123456789L;
        FirebaseRollEvent z = new FirebaseRollEvent("z-event", at, "Player", 100, false, Arrays.asList(1, 2));
        FirebaseRollEvent a = new FirebaseRollEvent("a-event", at, "Player", 200, false, Arrays.asList(3, 4));

        List<FirebaseRollEvent> events = new ArrayList<>(Arrays.asList(z, a));
        events.sort(FirebaseRollEvent::compareForPlayback);

        assertEquals("a-event", events.get(0).getEventId());
        assertEquals("z-event", events.get(1).getEventId());
    }

    @Test
    public void pickPreservesBatchMetadata()
    {
        FirebaseRollEvent start = new FirebaseRollEvent("event", 123L, "Player", 100, false,
                Arrays.asList(1, 2), "batch", 2, 4);
        FirebaseRollEvent completed = start.withPick(2, 456L);

        assertEquals("batch", completed.getBatchId());
        assertEquals(2, completed.getSequence());
        assertEquals(4, completed.getBatchSize());
        assertEquals(2, completed.getChosenItemId());
        assertEquals(456L, completed.getPickedAt());
    }
}

package com.rollbound.firebase;

import okhttp3.OkHttpClient;
import org.junit.Test;

import java.io.BufferedReader;
import java.io.StringReader;
import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.assertEquals;

public class FirebaseSseStreamTest
{
    @Test
    public void forwardsPutAndPatchPayloadsWithoutSyntheticRefreshes() throws Exception
    {
        List<String> events = new ArrayList<>();
        FirebaseSseStream stream = new FirebaseSseStream(
                new OkHttpClient(),
                "https://example.firebaseio.com/.json",
                (type, data) -> events.add(type + ":" + data),
                null,
                null);

        stream.running = true;
        String input =
                "event: put\n" +
                "data: {\"path\":\"/\",\"data\":{\"a\":1}}\n\n" +
                "event: keep-alive\n" +
                "data: null\n\n" +
                "event: patch\n" +
                "data: {\"path\":\"/a\",\"data\":{\"b\":2}}\n\n";

        stream.readEvents(new BufferedReader(new StringReader(input)));

        assertEquals(2, events.size());
        assertEquals("put:{\"path\":\"/\",\"data\":{\"a\":1}}", events.get(0));
        assertEquals("patch:{\"path\":\"/a\",\"data\":{\"b\":2}}", events.get(1));
    }
}
